import React, { useState } from 'react';
import { SalonSettings, Service, TeamMember } from '../types.ts';
import { db } from '../firebase.ts';
import { doc, setDoc } from "firebase/firestore";

interface AdminSettingsViewProps {
  settings: SalonSettings;
  services: Service[];
  customers: any[];
  bookings: any[];
  transactions: any[];
  loggedMember: TeamMember;
}

const AdminSettingsView: React.FC<AdminSettingsViewProps> = ({ 
  settings, 
  loggedMember
}) => {
  const isOwner = loggedMember.role === 'owner';
  const [memberData, setMemberData] = useState<TeamMember>(loggedMember);

  const updateMyProfile = async () => {
    try {
      const updatedMembers = settings.teamMembers.map(m => m.id === memberData.id ? memberData : m);
      await setDoc(doc(db, "settings", "main"), { 
        ...settings, 
        teamMembers: updatedMembers, 
        lastUpdated: Date.now() 
      });
      alert("Perfil atualizado com sucesso!");
    } catch (error) {
      console.error("Erro ao atualizar perfil:", error);
      alert("Erro ao salvar alterações.");
    }
  };

  const weekDays = [
    { n: 0, label: 'Dom' }, { n: 1, label: 'Seg' }, { n: 2, label: 'Ter' },
    { n: 3, label: 'Qua' }, { n: 4, label: 'Qui' }, { n: 5, label: 'Sex' }, { n: 6, label: 'Sáb' },
  ];

  return (
    <div className="space-y-12 pb-32 animate-fade-in">
      <div className="bg-tea-900 text-white p-10 rounded-[3rem] shadow-xl">
        <h2 className="text-3xl font-serif font-bold mb-2 italic">
          Configurações {isOwner ? 'do Salão' : 'do Meu Perfil'}
        </h2>
        <p className="text-tea-100 font-light text-sm italic">
          {isOwner ? 'Gestão completa da unidade Studio Moriá.' : 'Gerencie sua agenda e horários de trabalho.'}
        </p>
      </div>

      <section className="bg-white p-10 rounded-[3rem] border border-gray-100 shadow-sm space-y-10">
        <h3 className="text-2xl font-serif text-tea-900 italic font-bold">Meus Horários & Disponibilidade</h3>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
          <div className="space-y-6">
            <h4 className="text-[10px] font-bold text-tea-700 uppercase tracking-widest">Turno de Atendimento</h4>
            <div className="flex items-center gap-4">
              <input 
                type="time" 
                className="flex-1 p-4 bg-gray-50 rounded-2xl font-bold outline-none border-2 border-transparent focus:border-tea-200 transition-all" 
                value={memberData.businessHours?.start || settings.businessHours.start} 
                onChange={e => setMemberData({ 
                  ...memberData, 
                  businessHours: { 
                    ...(memberData.businessHours || settings.businessHours), 
                    start: e.target.value 
                  } 
                })} 
              />
              <span className="text-gray-300 font-bold">até</span>
              <input 
                type="time" 
                className="flex-1 p-4 bg-gray-50 rounded-2xl font-bold outline-none border-2 border-transparent focus:border-tea-200 transition-all" 
                value={memberData.businessHours?.end || settings.businessHours.end} 
                onChange={e => setMemberData({ 
                  ...memberData, 
                  businessHours: { 
                    ...(memberData.businessHours || settings.businessHours), 
                    end: e.target.value 
                  } 
                })} 
              />
            </div>
          </div>

          <div className="space-y-6">
            <h4 className="text-[10px] font-bold text-tea-700 uppercase tracking-widest">Dias de Folga</h4>
            <div className="flex flex-wrap gap-2">
              {weekDays.map(day => {
                const offDays = memberData.offDays || [];
                const isOff = offDays.includes(day.n);
                return (
                  <button 
                    key={day.n}
                    onClick={() => {
                      const next = isOff 
                        ? offDays.filter(d => d !== day.n) 
                        : [...offDays, day.n];
                      setMemberData({ ...memberData, offDays: next });
                    }}
                    className={`px-4 py-3 rounded-xl text-[10px] font-bold uppercase tracking-widest transition-all border-2 ${
                      isOff 
                        ? 'bg-tea-800 text-white border-tea-800 shadow-md' 
                        : 'bg-white text-gray-400 border-gray-100 hover:border-tea-100'
                    }`}
                  >
                    {day.label}
                  </button>
                );
              })}
            </div>
          </div>
        </div>

        <div className="pt-10 border-t border-gray-50 flex justify-end">
          <button 
            onClick={updateMyProfile}
            className="w-full md:w-auto px-12 py-5 bg-tea-900 text-white rounded-2xl font-bold uppercase text-[10px] tracking-[0.2em] shadow-xl hover:bg-black transition-all active:scale-95"
          >
            Salvar Alterações de Perfil
          </button>
        </div>
      </section>

      {isOwner && (
        <section className="bg-tea-50/50 p-10 rounded-[3rem] border border-tea-100 space-y-8">
          <div className="flex items-center gap-4">
             <div className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center text-2xl shadow-sm">🏢</div>
             <div>
                <h3 className="text-xl font-serif text-tea-950 italic font-bold">Configurações Globais (Dona)</h3>
                <p className="text-xs text-gray-500">Estas opções afetam o funcionamento de todo o salão.</p>
             </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-6 rounded-3xl border border-tea-50">
               <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2">Agenda Aberta Até</p>
               <input 
                type="date" 
                value={settings.agendaOpenUntil} 
                onChange={async (e) => {
                  await setDoc(doc(db, "settings", "main"), { ...settings, agendaOpenUntil: e.target.value });
                }}
                className="w-full bg-transparent font-bold text-tea-900 outline-none"
               />
            </div>
            {/* Outras configurações globais poderiam ser adicionadas aqui */}
          </div>
        </section>
      )}
    </div>
  );
};

export default AdminSettingsView;

