import React, { useState } from 'react';
import { TeamMember } from '../types';

interface AdminLoginProps {
  teamMembers: TeamMember[];
  onLogin: (member: TeamMember) => void;
  onBack: () => void;
}

const AdminLogin: React.FC<AdminLoginProps> = ({ teamMembers, onLogin, onBack }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    // Procura o membro pelo username digitado (case insensitive para facilitar)
    const member = teamMembers.find(m => m.username.toLowerCase() === username.toLowerCase());

    if (member && member.password === password) {
      onLogin(member);
    } else {
      setError(true);
      setTimeout(() => setError(false), 2000);
    }
  };

  return (
    <div className="min-h-[80vh] flex items-center justify-center px-4">
      <div className="max-w-md w-full bg-white rounded-[3rem] shadow-2xl p-12 border border-tea-50 text-center animate-slide-up">
        <div className="mb-8 inline-block p-4 rounded-3xl bg-tea-50">
          <svg className="w-10 h-10 text-tea-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"></path>
          </svg>
        </div>

        <h2 className="text-3xl font-serif text-tea-900 mb-2">Portal Studio Moriá</h2>
        <p className="text-gray-500 mb-10 font-light italic">Área Restrita: Digite suas credenciais.</p>

        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="space-y-1 text-left">
            <label className="text-[10px] font-bold text-tea-700 uppercase tracking-widest ml-2">Usuário</label>
            <input 
              type="text"
              placeholder="Ex: moria"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              className="w-full px-6 py-4 rounded-2xl bg-gray-50 border-2 border-transparent outline-none focus:border-tea-200 focus:bg-white transition-all font-bold text-tea-900"
              required
            />
          </div>

          <div className="space-y-1 text-left">
            <label className="text-[10px] font-bold text-tea-700 uppercase tracking-widest ml-2">Senha</label>
            <input 
              type="password" 
              placeholder="••••••"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className={`w-full px-6 py-4 rounded-2xl bg-gray-50 border-2 transition-all outline-none text-center text-lg tracking-widest ${error ? 'border-red-300 bg-red-50' : 'border-transparent focus:border-tea-200 focus:bg-white'}`}
              required
            />
            {error && <p className="text-red-500 text-[10px] font-bold mt-2 text-center animate-bounce uppercase">Acesso Negado</p>}
          </div>

          <button 
            type="submit"
            className="w-full bg-tea-800 text-white py-5 rounded-2xl font-bold text-lg hover:bg-tea-950 transition-all shadow-xl shadow-tea-100"
          >
            Acessar Painel
          </button>
        </form>

        <button 
          onClick={onBack}
          className="mt-8 text-tea-500 font-bold text-sm hover:underline"
        >
          Voltar para o site
        </button>
      </div>
    </div>
  );
};

export default AdminLogin;

import React, { useState } from 'react';
import { SalonSettings, Service, TeamMember } from '../types.ts';
import { db } from '../firebase.ts';
import { doc, setDoc } from "firebase/firestore";

interface AdminSettingsViewProps {
  settings: SalonSettings;
  services: Service[];
  customers: any[];
  bookings: any[];
  transactions: any[];
  loggedMember: TeamMember;
}

const AdminSettingsView: React.FC<AdminSettingsViewProps> = ({ 
  settings, 
  services,
  loggedMember
}) => {
  const isOwner = loggedMember.role === 'owner';

  // Estado para o perfil que está sendo editado (próprio ou da equipe pela dona)
  const [memberInEdit, setMemberInEdit] = useState<TeamMember | null>(null);
  const [isAddingNew, setIsAddingNew] = useState(false);
  const [myProfileData, setMyProfileData] = useState<TeamMember>(loggedMember);

  const saveSettings = async (updatedTeam: TeamMember[]) => {
    try {
      await setDoc(doc(db, "settings", "main"), { 
        ...settings, 
        teamMembers: updatedTeam, 
        lastUpdated: Date.now() 
      });
      alert("Configurações salvas com sucesso!");
    } catch (error) {
      console.error("Erro ao salvar:", error);
      alert("Falha na gravação.");
    }
  };

  const updateMyProfile = async () => {
    const updated = settings.teamMembers.map(m => m.id === myProfileData.id ? myProfileData : m);
    await saveSettings(updated);
  };

  const handleAddNewMember = () => {
    const newMember: TeamMember = {
      id: `tm-${Date.now()}`,
      name: "",
      username: "",
      password: "",
      role: 'staff',
      assignedServiceIds: [],
      businessHours: settings.businessHours,
      offDays: [0] // Domingo padrão
    };
    setMemberInEdit(newMember);
    setIsAddingNew(true);
  };

  const saveMemberChange = async () => {
    if (!memberInEdit) return;
    if (!memberInEdit.name || !memberInEdit.username || !memberInEdit.password) {
      alert("Preencha Nome, Usuário e Senha.");
      return;
    }

    let updatedTeam: TeamMember[];
    if (isAddingNew) {
      updatedTeam = [...settings.teamMembers, memberInEdit];
    } else {
      updatedTeam = settings.teamMembers.map(m => m.id === memberInEdit.id ? memberInEdit : m);
    }

    await saveSettings(updatedTeam);
    setMemberInEdit(null);
    setIsAddingNew(false);
  };

  const deleteMember = async (id: string) => {
    if (confirm("Deseja realmente remover este colaborador da equipe?")) {
      const updated = settings.teamMembers.filter(m => m.id !== id);
      await saveSettings(updated);
    }
  };

  const weekDays = [
    { n: 0, label: 'Dom' }, { n: 1, label: 'Seg' }, { n: 2, label: 'Ter' },
    { n: 3, label: 'Qua' }, { n: 4, label: 'Qui' }, { n: 5, label: 'Sex' }, { n: 6, label: 'Sáb' },
  ];

  return (
    <div className="space-y-12 pb-32 animate-fade-in">
      <div className="bg-tea-900 text-white p-10 rounded-[3rem] shadow-xl flex justify-between items-center">
        <div>
          <h2 className="text-3xl font-serif font-bold mb-2 italic">
            Configurações
          </h2>
          <p className="text-tea-100 font-light text-sm italic">
            {isOwner ? 'Painel de Gestão Studio Moriá.' : 'Gerencie seu acesso e horários.'}
          </p>
        </div>
        <div className="hidden md:block text-right">
           <span className="text-[10px] font-bold uppercase tracking-[0.2em] opacity-40">Profissional Logada</span>
           <p className="font-serif italic font-bold text-xl">{loggedMember.name}</p>
        </div>
      </div>

      {/* SEÇÃO 1: MEU PERFIL (ACESSÍVEL A TODOS) */}
      <section className="bg-white p-10 rounded-[3rem] border border-gray-100 shadow-sm space-y-10">
        <h3 className="text-2xl font-serif text-tea-900 italic font-bold">Meu Acesso & Horários</h3>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
          {/* Dados de Login */}
          <div className="space-y-6">
            <h4 className="text-[10px] font-bold text-tea-700 uppercase tracking-widest">Credenciais de Entrada</h4>
            <div className="grid grid-cols-1 gap-4">
               <div>
                  <label className="text-[9px] text-gray-400 font-bold uppercase ml-1">Usuário</label>
                  <input 
                    type="text" 
                    value={myProfileData.username} 
                    onChange={e => setMyProfileData({...myProfileData, username: e.target.value})}
                    className="w-full p-4 bg-gray-50 rounded-2xl font-bold border-2 border-transparent focus:border-tea-100 outline-none" 
                  />
               </div>
               <div>
                  <label className="text-[9px] text-gray-400 font-bold uppercase ml-1">Senha Pessoal</label>
                  <input 
                    type="password" 
                    value={myProfileData.password} 
                    onChange={e => setMyProfileData({...myProfileData, password: e.target.value})}
                    className="w-full p-4 bg-gray-50 rounded-2xl font-bold border-2 border-transparent focus:border-tea-100 outline-none" 
                  />
               </div>
            </div>
          </div>

          {/* Horários */}
          <div className="space-y-6">
            <h4 className="text-[10px] font-bold text-tea-700 uppercase tracking-widest">Disponibilidade</h4>
            <div className="flex flex-wrap gap-2">
              {weekDays.map(day => {
                const offDays = myProfileData.offDays || [];
                const isOff = offDays.includes(day.n);
                return (
                  <button 
                    key={day.n}
                    onClick={() => {
                      const next = isOff ? offDays.filter(d => d !== day.n) : [...offDays, day.n];
                      setMyProfileData({ ...myProfileData, offDays: next });
                    }}
                    className={`px-4 py-3 rounded-xl text-[10px] font-bold uppercase tracking-widest transition-all border-2 ${
                      isOff ? 'bg-tea-800 text-white border-tea-800' : 'bg-white text-gray-400 border-gray-100'
                    }`}
                  >
                    {day.label}
                  </button>
                );
              })}
            </div>
          </div>
        </div>

        <div className="pt-10 border-t border-gray-50 flex justify-end">
          <button 
            onClick={updateMyProfile}
            className="w-full md:w-auto px-12 py-5 bg-tea-900 text-white rounded-2xl font-bold uppercase text-[10px] tracking-[0.2em] shadow-xl hover:bg-black transition-all"
          >
            Salvar Alterações
          </button>
        </div>
      </section>

      {/* SEÇÃO 2: GESTÃO DE EQUIPE (APENAS DONA) */}
      {isOwner && (
        <section className="space-y-8">
          <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-4 px-4">
             <div>
                <h3 className="text-2xl font-serif text-tea-950 italic font-bold">Gestão de Equipe</h3>
                <p className="text-xs text-gray-500 italic">Cadastre colaboradoras e defina acessos.</p>
             </div>
             <button 
              onClick={handleAddNewMember}
              className="bg-tea-50 text-tea-900 border border-tea-200 px-6 py-3 rounded-2xl font-bold uppercase text-[9px] tracking-widest hover:bg-tea-900 hover:text-white transition-all shadow-sm"
             >
              + Nova Colaboradora
             </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {settings.teamMembers.map(member => (
              <div key={member.id} className="bg-white p-8 rounded-[3rem] border border-gray-100 shadow-sm relative group hover:border-tea-200 transition-all">
                <div className="flex justify-between items-start mb-6">
                   <div className="w-12 h-12 bg-tea-50 rounded-2xl flex items-center justify-center text-xl text-tea-900 font-bold">
                      {member.name.charAt(0)}
                   </div>
