                        <input 
                          type="text" 
                          value={memberInEdit.username} 
                          onChange={e => setMemberInEdit({...memberInEdit, username: e.target.value})}
                          placeholder="Ex: ana.silva"
                          className="w-full p-4 bg-gray-50 rounded-2xl font-bold border-2 border-transparent focus:border-tea-100 outline-none" 
                        />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[9px] font-bold text-gray-400 uppercase tracking-widest ml-1">Senha Inicial</label>
                        <input 
                          type="text" 
                          value={memberInEdit.password} 
                          onChange={e => setMemberInEdit({...memberInEdit, password: e.target.value})}
                          placeholder="Ex: 123456"
                          className="w-full p-4 bg-gray-50 rounded-2xl font-bold border-2 border-transparent focus:border-tea-100 outline-none" 
                        />
                      </div>
                   </div>
                </div>

                <div className="space-y-1">
                   <label className="text-[9px] font-bold text-gray-400 uppercase tracking-widest ml-1">Procedimentos Permitidos</label>
                   <div className="grid grid-cols-2 gap-2 max-h-40 overflow-y-auto custom-scroll p-2 bg-gray-50 rounded-2xl">
                      {services.map(srv => (
                        <label key={srv.id} className="flex items-center gap-3 p-2 cursor-pointer">
                           <input 
                            type="checkbox" 
                            checked={memberInEdit.assignedServiceIds.includes(srv.id)}
                            onChange={() => {
                              const ids = memberInEdit.assignedServiceIds.includes(srv.id)
                                ? memberInEdit.assignedServiceIds.filter(i => i !== srv.id)
