      depositStatus: 'paid',
      agreedToCancellationPolicy: true,
      policyAgreedAt: new Date().toISOString()
    });
    setActionModal({ open: false, booking: null, hour: '' });
  };

  const handleReleaseSlot = async (bookingId: string) => {
    await deleteDoc(doc(db, "bookings", bookingId));
    setActionModal({ open: false, booking: null, hour: '' });
  };

  const handleLiberateDay = async () => {
    if(!confirm("Deseja liberar TODOS os horários deste dia para agendamento das clientes?")) return;

    for (const hour of timeSlots) {
      const status = getSlotStatus(hour);
      if (status.type === 'blocked') {
        await addDoc(collection(db, "bookings"), {
          customerId: 'liberated',
          customerName: 'HORÁRIO LIBERADO',
          serviceId: 'liberated',
          serviceName: 'Aberto para Agendamento',
          teamMemberId: selectedProId,
          teamMemberName: selectedPro?.name,
          dateTime: `${selectedDate} ${hour}`,
          duration: 30,
          status: 'liberated',
          depositStatus: 'paid',
          agreedToCancellationPolicy: true,
          policyAgreedAt: new Date().toISOString()
        });
      }
    }
    alert("Dia liberado com sucesso!");
  };

  const handleBlockDay = async () => {
    if(!confirm("Deseja BLOQUEAR todos os horários livres e liberados deste dia? Agendamentos de clientes não serão afetados.")) return;

    const dayBookings = bookings.filter(b => 
      b.teamMemberId === selectedProId && 
      b.dateTime.startsWith(selectedDate) && 
      (b.status === 'liberated' || b.status === 'blocked')
    );

    for (const b of dayBookings) {
      await deleteDoc(doc(db, "bookings", b.id));
    }
    alert("Dia bloqueado com sucesso!");
  };

  const confirmBooking = async () => {
    if (!selectedCustomerId || !selectedServiceId) return;
    const customer = customers.find(c => c.id === selectedCustomerId);
    const service = services.find(s => s.id === selectedServiceId);
    if (!customer || !service) return;

    // Se houver uma liberação prévia nesse horário, removemos ela primeiro
    const existing = getSlotStatus(bookingModal.hour);
    if (existing.booking && (existing.type === 'liberated' || existing.type === 'blocked')) {
      await deleteDoc(doc(db, "bookings", existing.booking.id));
    }

    await addDoc(collection(db, "bookings"), {
      customerId: customer.id,
      customerName: customer.name,
      serviceId: service.id,
      serviceName: service.name,
      teamMemberId: selectedProId,
      teamMemberName: selectedPro?.name,
      dateTime: `${selectedDate} ${bookingModal.hour}`,
      duration: service.duration,
      status: 'scheduled', 
      depositStatus: 'paid',
      finalPrice: service.price,
      agreedToCancellationPolicy: true,
      policyAgreedAt: new Date().toISOString()
    });
    setBookingModal({ open: false, hour: '' });
  };

  return (
    <div className="space-y-8 animate-fade-in pb-20">
      <div className="bg-white p-8 rounded-[3rem] border border-gray-100 shadow-sm flex flex-col md:flex-row gap-6 items-end">
        <div className="flex-1 space-y-2">
          <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Data da Agenda</label>
          <input type="date" value={selectedDate} onChange={e => setSelectedDate(e.target.value)} className="w-full p-4 bg-gray-50 border-none rounded-2xl font-bold" />
        </div>
        <div className="flex-1 space-y-2">
          <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Colaboradora</label>
          <select 
            value={selectedProId} 
            onChange={e => isOwner && setSelectedProId(e.target.value)} 
            disabled={!isOwner}
            className="w-full p-4 bg-gray-50 border-none rounded-2xl font-bold disabled:opacity-50"
          >
            {teamMembers.map(m => <option key={m.id} value={m.id}>{m.name}</option>)}
          </select>
        </div>
        <div className="flex gap-2">
           <button onClick={handleLiberateDay} className="px-6 py-4 bg-tea-50 text-tea-900 border-2 border-tea-100 rounded-2xl text-[9px] font-bold uppercase tracking-widest hover:bg-tea-100 transition-all">🔓 Liberar Dia</button>
           <button onClick={handleBlockDay} className="px-6 py-4 bg-gray-800 text-gray-300 rounded-2xl text-[9px] font-bold uppercase tracking-widest hover:bg-black transition-all">🔒 Bloquear Dia</button>
        </div>
      </div>

      <div className="bg-white rounded-[3.5rem] shadow-sm border border-gray-100 p-8 grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-6 gap-3">
        {timeSlots.map(hour => {
          const status = getSlotStatus(hour);

          let slotStyles = "bg-gray-50 text-gray-300 border-transparent grayscale shadow-inner";
          let label = "🔒 Bloqueado";

          if (status.type === 'scheduled' || status.type === 'pending') {
            slotStyles = "bg-tea-800 text-white border-tea-800 shadow-md";
            label = status.booking?.customerName.split(' ')[0] || '';
          } else if (status.type === 'completed') {
            slotStyles = "bg-green-600 text-white border-green-600";
            label = "Concluído";
          } else if (status.type === 'liberated') {
            slotStyles = "bg-white text-tea-900 border-tea-100 shadow-sm";
            label = "✨ Vago (Liberado)";
          }

          return (
            <button 
              key={hour} 
              onClick={() => setActionModal({open: true, booking: status.booking || null, hour})} 
              className={`p-5 rounded-3xl border-2 transition-all flex flex-col items-center justify-center min-h-[95px] relative group ${slotStyles}`}
            >
               <span className="text-lg font-serif font-bold italic">{hour}</span>
               <span className="text-[8px] font-bold uppercase tracking-widest mt-1 opacity-80 text-center line-clamp-1">
                 {label}
               </span>
               <div className="absolute inset-0 bg-tea-950 text-white opacity-0 group-hover:opacity-100 rounded-3xl flex items-center justify-center transition-opacity z-10">
                  <span className="text-[10px] font-bold uppercase tracking-widest">Configurar</span>
               </div>
            </button>
          );
        })}
      </div>

      {actionModal.open && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-fade-in">
          <div className="bg-white w-full max-sm:max-w-xs max-w-sm rounded-[3rem] p-10 shadow-3xl text-center space-y-6 border border-tea-50">
            <div className="space-y-2">
              <span className="text-[10px] font-bold text-tea-600 uppercase tracking-widest">Gestão de Horário</span>
              <h3 className="text-3xl font-serif font-bold italic text-tea-950">{actionModal.hour}</h3>
            </div>

            <div className="space-y-3">
              {actionModal.booking && (actionModal.booking.status === 'scheduled' || actionModal.booking.status === 'pending') ? (
                <div className="space-y-4">
                  <div className="p-4 bg-gray-50 rounded-2xl border border-gray-100">
                      <p className="text-[10px] font-bold text-gray-400 uppercase mb-1">Cliente Agendada</p>
                      <p className="font-bold text-tea-900 text-lg uppercase tracking-tight">{actionModal.booking.customerName}</p>
                      <p className="text-[9px] text-tea-600 font-bold">{actionModal.booking.serviceName}</p>
                  </div>
                  <button onClick={() => updateDoc(doc(db, "bookings", actionModal.booking!.id), {status: 'completed'}).then(() => setActionModal({open:false, booking:null, hour:''}))} className="w-full py-4 bg-green-600 text-white rounded-2xl font-bold uppercase text-[10px] tracking-widest">Atendimento Concluído</button>
                  <button onClick={() => handleReleaseSlot(actionModal.booking!.id)} className="w-full py-4 bg-red-50 text-red-600 rounded-2xl font-bold uppercase text-[10px] tracking-widest">Cancelar Registro</button>
                </div>
              ) : (
                <>
                  <button 
                    onClick={() => { setBookingModal({open: true, hour: actionModal.hour}); setActionModal({open:false, booking:null, hour:''}); }} 
                    className="w-full py-5 bg-tea-900 text-white rounded-2xl font-bold uppercase text-[10px] tracking-widest shadow-xl hover:bg-black transition-all"
                  >
                    📅 Agendar Manualmente
                  </button>
                  {actionModal.booking?.status === 'liberated' ? (
                    <button 
                      onClick={() => handleReleaseSlot(actionModal.booking!.id)}
                      className="w-full py-5 bg-gray-800 text-gray-300 rounded-2xl font-bold uppercase text-[10px] tracking-widest hover:bg-black transition-all"
                    >
                      🔒 Bloquear este Horário
                    </button>
                  ) : (
                    <button 
                      onClick={() => handleLiberateSlot(actionModal.hour)}
                      className="w-full py-5 bg-tea-50 text-tea-900 border-2 border-tea-100 rounded-2xl font-bold uppercase text-[10px] tracking-widest hover:bg-tea-100 transition-all"
                    >
                      ✨ Liberar para Clientes
                    </button>
                  )}
                </>
              )}
            </div>
            <button onClick={() => setActionModal({open:false, booking:null, hour:''})} className="w-full py-2 text-gray-400 font-bold uppercase text-[9px] tracking-widest mt-4">Sair</button>
          </div>
        </div>
      )}

      {bookingModal.open && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-fade-in">
          <div className="bg-white w-full max-w-md rounded-[3rem] p-10 space-y-8 border-4 border-tea-100 shadow-3xl">
            <div className="text-center space-y-2">
              <h3 className="text-2xl font-serif font-bold italic text-tea-950">Agendar Cliente</h3>
              <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">Para {selectedDate} às {bookingModal.hour}</p>
            </div>

            <div className="space-y-4">
              <div className="space-y-1">
                <label className="text-[9px] font-bold text-tea-900 uppercase tracking-widest ml-2">Selecionar Cliente</label>
                <select value={selectedCustomerId} onChange={e => setSelectedCustomerId(e.target.value)} className="w-full p-4 bg-gray-50 rounded-2xl font-bold outline-none border-2 border-transparent focus:border-tea-100">
                  <option value="">Buscar cliente...</option>
                  {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[9px] font-bold text-tea-900 uppercase tracking-widest ml-2">Procedimento</label>
                <select value={selectedServiceId} onChange={e => setSelectedServiceId(e.target.value)} className="w-full p-4 bg-gray-50 rounded-2xl font-bold outline-none border-2 border-transparent focus:border-tea-100">
                  <option value="">Selecionar serviço...</option>
                  {services.map(s => <option key={s.id} value={s.id}>{s.name} - R${s.price}</option>)}
                </select>
              </div>
            </div>

            <div className="pt-4 flex flex-col gap-3">
              <button onClick={confirmBooking} className="w-full py-5 bg-tea-900 text-white rounded-2xl font-bold uppercase text-[10px] tracking-widest shadow-xl hover:bg-black transition-all">Salvar na Agenda</button>
              <button onClick={() => setBookingModal({open:false, hour:''})} className="w-full py-2 text-gray-400 font-bold uppercase text-[9px] tracking-widest">Descartar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminCalendar;

import React, { useState, useMemo } from 'react';
import { Customer, Booking, Service, SalonSettings, TeamMember, Promotion, WaitlistEntry } from '../types';
import { db } from '../firebase.ts';
import { collection, addDoc } from "firebase/firestore";

interface CustomerDashboardProps {
  customer: Customer;
  bookings: Booking[];
  services: Service[];
  settings: SalonSettings;
  onBook: (serviceId: string, dateTime: string, teamMemberId?: string, promoData?: any) => void;
  onUpdateProfile: (updated: Partial<Customer>) => void;
  onLogout: () => void;
  onCancelBooking: (id: string) => void;
  onAddToWaitlist: (serviceId: string, date: string) => void;
  promotions?: Promotion[];
  waitlist: WaitlistEntry[];
  onRemoveWaitlist: (id: string) => void;
}

const CustomerDashboard: React.FC<CustomerDashboardProps> = ({ 
  customer, 
  bookings, 
  services, 
  settings,
  onLogout,
  onAddToWaitlist,
  onRemoveWaitlist,
  promotions = [],
  waitlist = []
}) => {
  const [activeTab, setActiveTab] = useState<'home' | 'agendar' | 'agenda' | 'perfil'>('home');
  const [selectedService, setSelectedService] = useState<Service | null>(null);
  const [bookingStep, setBookingStep] = useState<1 | 2 | 3>(1);
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedTime, setSelectedTime] = useState<string>('');
  const [selectedProId, setSelectedProId] = useState<string>('');
  const [agreedToCancellation, setAgreedToCancellation] = useState(false);
  const [showPolicyModal, setShowPolicyModal] = useState(false);
  const [waitlistModal, setWaitlistModal] = useState<{ open: boolean; service: Service | null; date: string }>({
    open: false,
    service: null,
    date: new Date().toISOString().split('T')[0]
  });

  const POLICY_MODAL_TEXT = "Declaro ciência da taxa de reserva de 30%. Em caso de falta, 50% desse valor (no caso 15% do valor do serviço) será retido ao salão.";

  const myBookings = useMemo(() => 
    bookings.filter(b => b.customerId === customer.id).sort((a,b) => b.dateTime.localeCompare(a.dateTime)),
  [bookings, customer.id]);

  const completedCount = useMemo(() => myBookings.filter(b => b.status === 'completed').length, [myBookings]);
  const loyaltyProgress = (completedCount % 10);

  const highlightedServices = useMemo(() => services.filter(s => s.isVisible && s.isHighlighted), [services]);

  const activePromosAndTips = useMemo(() => {
    return promotions.filter(p => 
      p.isActive && 
      (p.targetCustomerIds.length === 0 || p.targetCustomerIds.includes(customer.id))
    ).sort((a,b) => b.createdAt.localeCompare(a.createdAt));
  }, [promotions, customer.id]);

  // Lista de todos os serviços visíveis sem filtros de categoria
  const allVisibleServices = useMemo(() => {
    return services.filter(s => s.isVisible);
  }, [services]);

  const getAvailabilityForDate = (date: string, service: Service) => {
    const slots: Record<string, TeamMember[]> = {};

    // Filtramos apenas as liberações explícitas feitas pela Moriá para esta data
    const liberatedSlots = bookings.filter(b => 
      b.dateTime.startsWith(date) && 
      b.status === 'liberated'
    );

    liberatedSlots.forEach(slot => {
      const time = slot.dateTime.split(' ')[1];
      const pro = settings.teamMembers.find(m => m.id === slot.teamMemberId);

      if (pro && pro.assignedServiceIds.includes(service.id)) {
        // Verifica se houve algum agendamento real que sobrepôs essa liberação
        const isActuallyTaken = bookings.some(b => 
          b.teamMemberId === pro.id && 
          b.dateTime === slot.dateTime && 
          (b.status === 'scheduled' || b.status === 'pending')
        );

        if (!isActuallyTaken) {
          if (!slots[time]) slots[time] = [];
          slots[time].push(pro);
        }
      }
    });

    return slots;
  };

  const availableSlotsForDate = useMemo(() => {
    if (!selectedService) return {};
    return getAvailabilityForDate(selectedDate, selectedService);
  }, [selectedService, selectedDate, bookings, settings]);

  const calendarDays = useMemo(() => {
    const days = [];
    const today = new Date();
    const limit = settings.agendaOpenUntil ? new Date(settings.agendaOpenUntil) : new Date(today.getTime() + 14 * 24 * 60 * 60 * 1000);

    let current = new Date(today);
    current.setHours(0,0,0,0);

    while (current <= limit) {
      const dateStr = current.toISOString().split('T')[0];
      const slots = selectedService ? getAvailabilityForDate(dateStr, selectedService) : {};
      const isAvailable = Object.keys(slots).length > 0;

      days.push({
        date: dateStr,
        dayName: current.toLocaleDateString('pt-BR', { weekday: 'short' }).replace('.', ''),
        dayNum: current.getDate(),
        isAvailable
      });
      current.setDate(current.getDate() + 1);
    }
    return days;
  }, [selectedService, bookings, settings]);

  const handleBookSubmit = async () => {
    if (selectedService && selectedProId && selectedTime && agreedToCancellation) {
      const pro = settings.teamMembers.find(m => m.id === selectedProId);

      // Quando um cliente agenda, mantemos o registro da liberação para controle administrativo
      // mas o novo agendamento 'pending' ou 'scheduled' sobrepõe a visualização.
      await addDoc(collection(db, "bookings"), {
        customerId: customer.id,
        customerName: customer.name,
        serviceId: selectedService.id,
        serviceName: selectedService.name,
        dateTime: `${selectedDate} ${selectedTime}`,
        duration: selectedService.duration,
        status: 'pending',
        depositStatus: 'pending',
        teamMemberId: selectedProId,
        teamMemberName: pro?.name,
        agreedToCancellationPolicy: true,
        policyAgreedAt: new Date().toISOString(),
        policyAgreedText: POLICY_MODAL_TEXT,
        originalPrice: selectedService.price,
        finalPrice: selectedService.price
      });
      setShowPolicyModal(false);
      setBookingStep(3);
    }
  };

  const handleJoinWaitlist = async () => {
    if (waitlistModal.service) {
      await onAddToWaitlist(waitlistModal.service.id, waitlistModal.date);
      setWaitlistModal({ ...waitlistModal, open: false });
      alert("Você entrou na fila de espera! Avisaremos via WhatsApp se uma vaga surgir.");
    }
  };

  return (
    <div className="min-h-screen bg-[#FDFDFD] pb-32 animate-fade-in font-sans">

      {/* Modal Fila de Espera */}
      {waitlistModal.open && (
        <div className="fixed inset-0 z-[250] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-fade-in">
          <div className="bg-white w-full max-w-sm rounded-[3rem] p-10 shadow-3xl animate-slide-up space-y-8 border border-gray-100">
             <div className="text-center space-y-2">
                <div className="w-16 h-16 bg-tea-50 text-tea-900 rounded-2xl flex items-center justify-center text-3xl mx-auto mb-4">⏳</div>
                <h3 className="text-xl font-serif font-bold text-tea-950 italic">Fila de Espera</h3>
                <p className="text-xs text-gray-500 italic">Informe a data que você gostaria de ser atendida para {waitlistModal.service?.name}</p>
             </div>

             <div className="space-y-4">
                <label className="text-[10px] font-bold text-tea-900 uppercase tracking-widest ml-1">Data Desejada</label>
                <input 
                  type="date" 
                  value={waitlistModal.date}
                  onChange={(e) => setWaitlistModal({ ...waitlistModal, date: e.target.value })}
                  className="w-full p-4 bg-gray-50 border-none rounded-2xl font-bold text-tea-950 outline-none"
                />
             </div>

             <div className="flex flex-col gap-3">
                <button onClick={handleJoinWaitlist} className="w-full py-5 bg-tea-900 text-white rounded-2xl font-bold uppercase text-[10px] tracking-widest shadow-xl hover:bg-black transition-all">Entrar na Fila</button>
                <button onClick={() => setWaitlistModal({ ...waitlistModal, open: false })} className="w-full py-2 text-gray-400 font-bold uppercase text-[9px]">Cancelar</button>
             </div>
          </div>
        </div>
      )}

      {showPolicyModal && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-tea-950/90 backdrop-blur-xl animate-fade-in">
          <div className="bg-white w-full max-w-sm rounded-[3.5rem] p-10 shadow-3xl animate-slide-up space-y-8 text-center border-4 border-tea-100">
            <div className="w-20 h-20 bg-tea-50 text-tea-900 rounded-full flex items-center justify-center text-4xl mx-auto shadow-inner">📄</div>
            <div className="space-y-4">
              <h3 className="text-xl font-serif font-bold text-tea-950 italic">Compromisso Moriá</h3>
              <p className="text-gray-600 text-sm leading-relaxed">{POLICY_MODAL_TEXT}</p>
            </div>
            <button onClick={handleBookSubmit} className="w-full py-5 bg-tea-900 text-white rounded-2xl font-bold uppercase text-[10px] tracking-widest hover:bg-black transition-all shadow-xl">Confirmar e Reservar</button>
            <button onClick={() => setShowPolicyModal(false)} className="w-full py-2 text-gray-400 font-bold uppercase text-[9px]">Cancelar</button>
          </div>
        </div>
      )}

      <header className="bg-gradient-to-b from-tea-900 to-tea-950 pt-16 pb-28 px-8 rounded-b-[5rem] shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 w-80 h-80 bg-tea-400/10 rounded-full -mr-40 -mt-40 blur-3xl pointer-events-none"></div>
        <div className="max-w-md mx-auto relative z-10 space-y-8">
          <div className="w-full flex justify-between items-center">
             <div className="w-16 h-16 bg-white/10 rounded-3xl backdrop-blur-md flex items-center justify-center border border-white/20 shadow-inner">
                <span className="text-white text-2xl font-serif italic font-bold">{customer.name.charAt(0)}</span>
             </div>
             <div className="text-right">
                <p className="text-[9px] font-bold text-tea-300 uppercase tracking-[0.3em] mb-1">Studio Moriá</p>
                <h1 className="text-2xl font-serif text-white font-bold italic leading-none">{customer.name.split(' ')[0]}</h1>
             </div>
          </div>
          <div className="w-full bg-white/5 backdrop-blur-md rounded-[3rem] p-8 border border-white/10 shadow-2xl space-y-4">
             <div className="flex justify-between items-center">
                <span className="text-[9px] font-bold text-tea-200 uppercase tracking-widest">Cartão Fidelidade</span>
                <span className="text-[10px] text-white font-serif italic">{completedCount} Visitas</span>
             </div>
             <div className="flex justify-between gap-2">
                {[...Array(10)].map((_, i) => (
                  <div key={i} className={`flex-1 h-2 rounded-full transition-all duration-700 ${i < loyaltyProgress ? 'bg-tea-300 shadow-[0_0_10px_rgba(142,201,154,0.6)]' : 'bg-white/10'}`}></div>
                ))}
             </div>
             <p className="text-[10px] text-tea-100 font-medium italic text-center">Ganhe um presente especial após 10 sessões ✨</p>
          </div>
        </div>
      </header>

      <main className="max-w-md mx-auto px-6 -mt-16 relative z-20 space-y-12 pb-10">

        {activeTab === 'home' && (
          <div className="space-y-12 animate-slide-up">
            <div className="grid grid-cols-2 gap-4">
               <button onClick={() => setActiveTab('agendar')} className="bg-white p-8 rounded-[3rem] shadow-xl border border-gray-50 flex flex-col items-center gap-4 group hover:bg-tea-50 transition-all">
                  <div className="w-12 h-12 bg-tea-100 text-tea-900 rounded-2xl flex items-center justify-center text-2xl group-hover:scale-110 transition-transform">✨</div>
                  <span className="text-[10px] font-bold text-tea-950 uppercase tracking-widest">Procedimentos</span>
               </button>
               <button onClick={() => setActiveTab('agenda')} className="bg-white p-8 rounded-[3rem] shadow-xl border border-gray-100 flex flex-col items-center gap-4 group hover:bg-tea-50 transition-all">
                  <div className="w-12 h-12 bg-gray-50 text-tea-800 rounded-2xl flex items-center justify-center text-2xl group-hover:scale-110 transition-transform">🗓️</div>
                  <span className="text-[10px] font-bold text-tea-950 uppercase tracking-widest">Minha Agenda</span>
               </button>
            </div>

            {highlightedServices.length > 0 && (
              <section className="space-y-6">
                 <div className="flex justify-between items-end px-2">
                    <h3 className="text-2xl font-serif text-tea-950 italic font-bold">Desejos Moriá</h3>
                    <button onClick={() => setActiveTab('agendar')} className="text-[9px] font-bold text-tea-600 uppercase tracking-widest hover:underline">Ver Todos</button>
                 </div>
                 <div className="flex gap-4 overflow-x-auto pb-4 no-scrollbar">
                    {highlightedServices.map(service => (
                      <div 
                        key={service.id} 
                        className="min-w-[240px] bg-tea-900 p-8 rounded-[3.5rem] shadow-2xl relative overflow-hidden group"
                      >
                         <div className="absolute top-0 right-0 w-20 h-20 bg-white/5 rounded-full -mr-10 -mt-10"></div>
                         <span className="text-[8px] font-bold text-tea-300 uppercase tracking-widest mb-4 block">{service.category}</span>
                         <h4 className="text-xl font-serif font-bold text-white italic mb-2 leading-tight">{service.name}</h4>
                         <p className="text-[10px] text-tea-100 font-bold uppercase tracking-widest mb-8">R$ {service.price.toFixed(2)}</p>
                         <div className="flex flex-col gap-2">
                            <button onClick={() => { setSelectedService(service); setActiveTab('agendar'); setBookingStep(2); }} className="w-full py-4 bg-white text-tea-900 rounded-2xl font-bold uppercase text-[9px] tracking-widest shadow-xl">Agendar</button>
                            <button onClick={() => setWaitlistModal({ open: true, service, date: new Date().toISOString().split('T')[0] })} className="w-full py-3 bg-white/10 text-white rounded-2xl font-bold uppercase text-[8px] tracking-widest border border-white/20">Fila de Espera</button>
                         </div>
                      </div>
                    ))}
                 </div>
              </section>
            )}

            <section className="space-y-6">
               <h3 className="text-2xl font-serif text-tea-950 italic font-bold px-2">Feed Studio Moriá</h3>
               <div className="space-y-6">
                  {activePromosAndTips.length > 0 ? activePromosAndTips.map(promo => (
                    <div 
                      key={promo.id} 
                      className={`p-8 rounded-[3.5rem] border shadow-sm space-y-4 relative overflow-hidden transition-all hover:shadow-md ${promo.type === 'promotion' ? 'bg-orange-50 border-orange-100' : 'bg-white border-gray-100'}`}
                    >
                       <div className="flex justify-between items-start">
                          <span className={`px-4 py-1.5 rounded-full text-[8px] font-bold uppercase tracking-widest ${promo.type === 'promotion' ? 'bg-orange-500 text-white' : 'bg-tea-50 text-tea-900'}`}>
                             {promo.type === 'promotion' ? 'Oferta Moriá' : 'Dica Especial ✨'}
                          </span>
                       </div>
                       <h4 className="text-lg font-serif font-bold text-tea-950 italic leading-tight">{promo.title}</h4>
                       <p className="text-gray-600 text-xs leading-relaxed italic line-clamp-3">{promo.content}</p>
                       {promo.linkedServiceId && (
                         <button onClick={() => { 
                           const srv = services.find(s => s.id === promo.linkedServiceId);
                           if (srv) { setSelectedService(srv); setActiveTab('agendar'); setBookingStep(2); }
                         }} className="w-full py-3 bg-tea-950 text-white rounded-2xl text-[9px] font-bold uppercase tracking-widest">Aproveitar agora</button>
                       )}
                    </div>
                  )) : (
                    <div className="text-center py-10 opacity-30 italic text-sm">Nenhuma novidade hoje.</div>
                  )}
               </div>
            </section>
          </div>
        )}

        {activeTab === 'agendar' && (
          <div className="space-y-8 animate-slide-up">
            <div className="flex items-center justify-between px-2">
               <button onClick={() => { if(bookingStep > 1) setBookingStep(prev => (prev - 1) as any); else setActiveTab('home'); }} className="p-3 bg-white rounded-2xl shadow-sm">←</button>
               <h3 className="text-xl font-serif font-bold text-tea-950 italic">{bookingStep === 1 ? 'Procedimentos' : bookingStep === 2 ? 'Escolha o Horário' : 'Confirmado'}</h3>
               <div className="w-10"></div>
            </div>

            {bookingStep === 1 && (
              <div className="space-y-6">
                {allVisibleServices.map(service => (
                  <div key={service.id} className="w-full bg-white p-8 rounded-[3rem] shadow-sm border border-gray-100 flex flex-col gap-6 group hover:border-tea-200 transition-all">
                     <div className="flex justify-between items-start">
                        <div className="space-y-1">
                           <p className="text-[8px] text-tea-600 font-bold uppercase tracking-widest">{service.category || 'Procedimento'}</p>
                           <p className="font-bold text-tea-950 text-xl group-hover:text-tea-800 transition-colors">{service.name}</p>
                           <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">R$ {service.price.toFixed(2)} • {service.duration}min</p>
                        </div>
                        <div className="w-12 h-12 bg-tea-50 rounded-2xl flex items-center justify-center text-tea-900 group-hover:bg-tea-900 group-hover:text-white transition-all text-xl">🌿</div>
                     </div>

                     <div className="flex gap-3">
                        <button 
                          onClick={() => { setSelectedService(service); setBookingStep(2); }}
                          className="flex-[2] py-4 bg-tea-900 text-white rounded-2xl font-bold uppercase text-[10px] tracking-widest shadow-xl hover:bg-black transition-all"
                        >
                           Agendar Agora
                        </button>
                        <button 
                          onClick={() => setWaitlistModal({ open: true, service, date: new Date().toISOString().split('T')[0] })}
                          className="flex-1 py-4 bg-white border-2 border-tea-100 text-tea-900 rounded-2xl font-bold uppercase text-[9px] tracking-widest hover:bg-tea-50 transition-all"
                        >
                           Fila de Espera
                        </button>
                     </div>
                  </div>
                ))}
                {allVisibleServices.length === 0 && (
                  <div className="text-center py-20 opacity-30 italic text-sm">Nenhum serviço disponível no momento.</div>
                )}
              </div>
            )}

            {bookingStep === 2 && selectedService && (
              <div className="space-y-8">
                 <div className="p-6 bg-tea-900 rounded-[2.5rem] text-white space-y-2 shadow-xl">
                    <p className="text-[8px] font-bold text-tea-300 uppercase tracking-widest">Você selecionou</p>
                    <h4 className="text-xl font-serif italic font-bold">{selectedService.name}</h4>
                    <p className="text-xs font-bold text-tea-100 uppercase tracking-widest">Investimento: R$ {selectedService.price.toFixed(2)}</p>
                 </div>

                 <div className="space-y-4">
                    <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Selecione o Dia</h4>
                    <div className="flex gap-3 overflow-x-auto pb-2 px-2 no-scrollbar">
                       {calendarDays.map(day => (
                         <button 
                          key={day.date} 
                          disabled={!day.isAvailable}
                          onClick={() => { setSelectedDate(day.date); setSelectedTime(''); }}
                          className={`min-w-[70px] p-4 rounded-3xl border-2 flex flex-col items-center transition-all ${!day.isAvailable ? 'opacity-20 border-transparent grayscale' : selectedDate === day.date ? 'bg-tea-100 border-tea-400 scale-110 shadow-md' : 'bg-white border-tea-50'}`}
                         >
                            <span className="text-[8px] font-bold text-tea-800 uppercase tracking-widest">{day.dayName}</span>
                            <span className="text-lg font-serif font-bold italic text-tea-950">{day.dayNum}</span>
                         </button>
                       ))}
                    </div>
                 </div>

                 <div className="space-y-4">
                    <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Selecione o Horário</h4>
                    <div className="grid grid-cols-4 gap-3">
                       {Object.keys(availableSlotsForDate).map(time => (
                         <button 
                          key={time} 
                          onClick={() => { setSelectedTime(time); setSelectedProId(availableSlotsForDate[time][0]?.id || ''); }}
                          className={`p-3 rounded-2xl border-2 font-bold text-xs transition-all ${selectedTime === time ? 'bg-tea-800 border-tea-800 text-white shadow-lg scale-105' : 'bg-white border-tea-50 text-tea-900 hover:border-tea-200'}`}
                         >
                           {time}
                         </button>
                       ))}
                       {Object.keys(availableSlotsForDate).length === 0 && (
                         <div className="col-span-4 text-center py-10 bg-gray-50 rounded-3xl border-2 border-dashed border-gray-100">
                            <p className="text-xs text-gray-400 italic mb-4">Agenda cheia para este dia.</p>
                            <button 
                              onClick={() => setWaitlistModal({ open: true, service: selectedService, date: selectedDate })}
                              className="text-tea-800 font-bold uppercase text-[9px] tracking-widest underline"
                            >
                              Deseja entrar na fila de espera?
                            </button>
                         </div>
                       )}
                    </div>
                 </div>

                 {selectedTime && (
                   <div className="pt-4 animate-slide-up space-y-6">
                      <label className="flex items-start gap-4 cursor-pointer p-4 bg-white rounded-3xl border-2 border-tea-50 hover:bg-tea-50 transition-all">
                         <input 
                          type="checkbox" 
                          checked={agreedToCancellation}
                          onChange={e => setAgreedToCancellation(e.target.checked)}
                          className="mt-1 w-5 h-5 rounded text-tea-900 border-tea-100 focus:ring-tea-900" 
                         />
                         <span className="text-[10px] text-gray-500 font-medium leading-relaxed italic">
                           Aceito a <button onClick={(e) => {e.preventDefault(); setShowPolicyModal(true);}} className="text-tea-700 font-bold underline">Política de Cancelamento</button> e reserva do Studio Moriá.
                         </span>
                      </label>
                      <button 
                        onClick={() => setShowPolicyModal(true)}
                        disabled={!agreedToCancellation}
                        className={`w-full py-6 rounded-3xl font-bold uppercase text-[11px] tracking-widest shadow-2xl transition-all ${agreedToCancellation ? 'bg-tea-900 text-white hover:bg-black shadow-tea-200' : 'bg-gray-100 text-gray-300'}`}
                      >
                        Confirmar Reserva
                      </button>
                   </div>
                 )}
              </div>
            )}

            {bookingStep === 3 && (
              <div className="text-center py-20 space-y-8 animate-slide-up">
                 <div className="w-32 h-32 bg-tea-50 text-tea-900 rounded-[3rem] flex items-center justify-center text-6xl mx-auto shadow-inner">🎉</div>
                 <div className="space-y-4 px-10">
                    <h3 className="text-3xl font-serif text-tea-950 font-bold italic leading-tight">Agendamento Enviado!</h3>
                    <p className="text-gray-500 text-xs leading-relaxed italic">Recebemos seu pedido. Avisaremos você pelo WhatsApp assim que o Studio Moriá confirmar.</p>
                 </div>
                 <button onClick={() => { setActiveTab('agenda'); setBookingStep(1); }} className="w-full py-6 bg-tea-900 text-white rounded-[2rem] font-bold uppercase text-[10px] tracking-widest shadow-xl">Ver Meus Horários</button>
              </div>
            )}
          </div>
        )}

        {activeTab === 'agenda' && (
          <div className="space-y-8 animate-slide-up">
             <div className="flex items-center justify-between px-2">
                <button onClick={() => setActiveTab('home')} className="p-3 bg-white rounded-2xl shadow-sm">←</button>
                <h3 className="text-xl font-serif font-bold text-tea-950 italic">Minha Agenda</h3>
                <div className="w-10"></div>
             </div>

             {/* Fila de Espera Ativa da Cliente */}
             {waitlist.length > 0 && (
                <div className="space-y-4">
                   <h4 className="text-[9px] font-bold text-tea-600 uppercase tracking-widest ml-4">Minha Fila de Espera</h4>
                   {waitlist.map(w => (
                     <div key={w.id} className="p-6 bg-tea-50/50 border border-tea-100 rounded-[2rem] flex justify-between items-center shadow-sm">
                        <div>
                           <p className="font-bold text-tea-950 text-sm">{w.serviceName}</p>
                           <p className="text-[9px] text-tea-700 font-bold uppercase tracking-widest italic">Interesse para: {w.preferredDate}</p>
                        </div>
                        <button onClick={() => onRemoveWaitlist(w.id)} className="text-[8px] bg-white text-tea-600 px-4 py-2 rounded-xl font-bold uppercase tracking-widest shadow-sm border border-tea-50">Cancelar</button>
                     </div>
                   ))}
                </div>
             )}

             <div className="space-y-6">
                {myBookings.map(booking => {
                  const bDate = new Date(booking.dateTime.replace(' ', 'T'));
                  const isPast = bDate < new Date();

                  return (
                    <div key={booking.id} className={`p-8 bg-white rounded-[3rem] border-2 shadow-sm transition-all ${isPast ? 'opacity-50 grayscale border-transparent' : 'border-tea-50 shadow-tea-100/10'}`}>
                       <div className="flex justify-between items-start mb-4">
                          <div className="space-y-1">
                             <p className="text-[8px] text-tea-600 font-bold uppercase tracking-widest">Confirmado ✓</p>
                             <h4 className="text-xl font-serif font-bold text-tea-950 italic">{booking.serviceName}</h4>
                          </div>
                          <span className={`px-4 py-1.5 rounded-full text-[8px] font-bold uppercase tracking-widest ${
                            booking.status === 'scheduled' ? 'bg-tea-800 text-white' : 
                            booking.status === 'completed' ? 'bg-green-100 text-green-700' :
                            booking.status === 'cancelled' ? 'bg-red-50 text-red-600' :
                            'bg-orange-100 text-orange-700'
                          }`}>
                            {booking.status === 'scheduled' ? 'Agendado' : 
                             booking.status === 'completed' ? 'Realizado' :
                             booking.status === 'cancelled' ? 'Cancelado' :
                             'Em Análise'}
                          </span>
                       </div>
                       <div className="flex items-center gap-6 pt-6 border-t border-gray-50">
                          <div className="flex flex-col">
                             <span className="text-[9px] text-gray-300 font-bold uppercase tracking-widest">Data</span>
                             <span className="text-sm font-bold text-gray-700">{bDate.toLocaleDateString()}</span>
                          </div>
                          <div className="flex flex-col">
                             <span className="text-[9px] text-gray-300 font-bold uppercase tracking-widest">Horário</span>
                             <span className="text-sm font-bold text-gray-700">{booking.dateTime.split(' ')[1]}</span>
                          </div>
                       </div>
                    </div>
                  );
                })}
                {myBookings.length === 0 && waitlist.length === 0 && (
                  <div className="text-center py-32 bg-gray-50 rounded-[4rem] border-2 border-dashed border-gray-100">
                     <p className="text-gray-400 font-serif italic text-lg px-10">Você ainda não tem agendamentos ou interesses registrados.</p>
                     <button onClick={() => setActiveTab('agendar')} className="text-tea-800 font-bold uppercase text-[9px] tracking-widest mt-6 bg-white px-6 py-3 rounded-full shadow-sm">Ver Procedimentos</button>
                  </div>
                )}
             </div>
          </div>
        )}
      </main>

      <nav className="fixed bottom-0 left-0 right-0 z-50 px-6 pb-6 pt-2">
         <div className="max-w-md mx-auto bg-tea-950/80 backdrop-blur-2xl rounded-[3rem] p-3 flex justify-between items-center border border-white/10 shadow-2xl">
            {[
              { id: 'home', label: 'Início', icon: '🏠' },
              { id: 'agendar', label: 'Cuidados', icon: '✨' },
              { id: 'agenda', label: 'Agenda', icon: '🗓️' },
              { id: 'logout', label: 'Sair', icon: '👋' }
            ].map(tab => (
              <button 
                key={tab.id}
                onClick={() => tab.id === 'logout' ? onLogout() : setActiveTab(tab.id as any)}
                className={`flex-1 flex flex-col items-center py-4 transition-all ${activeTab === tab.id ? 'text-tea-300 scale-110' : 'text-tea-100/40 hover:text-white'}`}
              >
                <span className="text-xl mb-1">{tab.icon}</span>
                <span className="text-[8px] font-bold uppercase tracking-[0.2em]">{tab.label}</span>
              </button>
            ))}
         </div>
      </nav>
    </div>
  );
};

export default CustomerDashboard;

import React, { useState, useEffect } from 'react';
import { View, Customer, Service, Booking, Transaction, SalonSettings, WaitlistEntry, Promotion, TeamMember } from './types.ts';
import { INITIAL_SERVICES, DEFAULT_SETTINGS } from './constants.ts';
import { db } from './firebase.ts';
import { 
  collection, 
  onSnapshot, 
  doc, 
  setDoc, 
  addDoc, 
  updateDoc, 
  deleteDoc
} from "firebase/firestore";

import Navbar from './components/Navbar.tsx';
import CustomerHome from './components/CustomerHome.tsx';
import CustomerRegister from './components/CustomerRegister.tsx';
import CustomerLoginView from './components/CustomerLoginView.tsx';
import CustomerProfile from './components/CustomerProfile.tsx';
import CustomerDashboard from './components/CustomerDashboard.tsx';
import AdminDashboard from './components/AdminDashboard.tsx';
import AdminCalendar from './components/AdminCalendar.tsx';
import AdminFinance from './components/AdminFinance.tsx';
import AdminClients from './components/AdminClients.tsx';
import AdminConfirmations from './components/AdminConfirmations.tsx';
import AdminSettingsView from './components/AdminSettingsView.tsx';
import AdminLogin from './components/AdminLogin.tsx';
import AdminMarketing from './components/AdminMarketing.tsx';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.CUSTOMER_HOME);
  const [isAdmin, setIsAdmin] = useState(false);
  const [loggedAdminMember, setLoggedAdminMember] = useState<TeamMember | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  const [settings, setSettings] = useState<SalonSettings>(DEFAULT_SETTINGS);
  const [services, setServices] = useState<Service[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [waitlist, setWaitlist] = useState<WaitlistEntry[]>([]);
  const [promotions, setPromotions] = useState<Promotion[]>([]);
  const [currentUser, setCurrentUser] = useState<Customer | null>(null);

  useEffect(() => {
    const unsubSettings = onSnapshot(doc(db, "settings", "main"), (snap) => {
      if (snap.exists()) {
        const remoteSettings = snap.data() as SalonSettings;

        // CORREÇÃO DE DUPLICIDADE: Filtra para garantir que ID tm1 seja único e dono
        let team = remoteSettings.teamMembers || [];
        const masterAdmin = team.find(m => m.id === 'tm1') || DEFAULT_SETTINGS.teamMembers[0];
        const otherMembers = team.filter(m => m.id !== 'tm1' && m.username !== 'admin');

        const correctedTeam = [
          { ...masterAdmin, id: 'tm1', username: 'admin', password: '460206', role: 'owner' as const },
          ...otherMembers
        ];

        setSettings({ ...remoteSettings, teamMembers: correctedTeam });
        setIsLoading(false);
      } else {
        setDoc(doc(db, "settings", "main"), DEFAULT_SETTINGS).then(() => setIsLoading(false));
      }
    });

    // Demais snapshots permanecem iguais para manter consistência dos dados
    const unsubServices = onSnapshot(collection(db, "services"), (snapshot) => {
      const data = snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Service));
      setServices(data);
    });

    const unsubCustomers = onSnapshot(collection(db, "customers"), (snapshot) => {
      setCustomers(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Customer)));
    });

    const unsubBookings = onSnapshot(collection(db, "bookings"), (snapshot) => {
      setBookings(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Booking)));
    });

    const unsubTransactions = onSnapshot(collection(db, "transactions"), (snapshot) => {
      setTransactions(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Transaction)));
    });

    const unsubWaitlist = onSnapshot(collection(db, "waitlist"), (snapshot) => {
      setWaitlist(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as WaitlistEntry)));
    });

    const unsubPromotions = onSnapshot(collection(db, "promotions"), (snapshot) => {
      setPromotions(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Promotion)));
    });

    return () => {
      unsubSettings(); unsubServices(); unsubCustomers();
      unsubBookings(); unsubTransactions(); unsubWaitlist(); unsubPromotions();
    };
  }, []);

  // Handlers de Auth...
  const handleAdminLogin = (member: TeamMember) => {
    setLoggedAdminMember(member);
    setIsAdmin(true);
    localStorage.setItem('moria_admin_session', JSON.stringify(member));
    setCurrentView(View.ADMIN_DASHBOARD);
  };

  const handleAdminLogout = () => {
    setLoggedAdminMember(null);
    setIsAdmin(false);
    localStorage.removeItem('moria_admin_session');
    setCurrentView(View.CUSTOMER_HOME);
  };

  const renderView = () => {
    if (isAdmin) {
      if (!loggedAdminMember) return <AdminLogin teamMembers={settings.teamMembers} onLogin={handleAdminLogin} onBack={() => { setIsAdmin(false); setCurrentView(View.CUSTOMER_HOME); }} />;

      switch (currentView) {
        case View.ADMIN_SETTINGS: return <AdminSettingsView settings={settings} services={services} customers={customers} bookings={bookings} transactions={transactions} loggedMember={loggedAdminMember} />;
        case View.ADMIN_CALENDAR: return <AdminCalendar bookings={bookings} services={services} customers={customers} teamMembers={settings.teamMembers} settings={settings} loggedMember={loggedAdminMember} />;
        case View.ADMIN_CONFIRMATIONS: return <AdminConfirmations bookings={bookings} customers={customers} waitlist={waitlist} onUpdateStatus={(id, s) => updateDoc(doc(db, "bookings", id), {status: s})} onUpdateDeposit={(id, d) => updateDoc(doc(db, "bookings", id), {depositStatus: d})} onDeleteBooking={(id) => deleteDoc(doc(db, "bookings", id))} onRemoveWaitlist={(id) => deleteDoc(doc(db, "waitlist", id))} />;
        case View.ADMIN_CLIENTS: return <AdminClients customers={customers} bookings={bookings} transactions={transactions} onDelete={(id) => deleteDoc(doc(db, "customers", id))} onUpdate={(id, d) => updateDoc(doc(db, "customers", id), d)} />;
        case View.ADMIN_FINANCE: return <AdminFinance transactions={transactions} onAdd={(d) => addDoc(collection(db, "transactions"), d)} onUpdate={(id, d) => updateDoc(doc(db, "transactions", id), d)} onDelete={(id) => deleteDoc(doc(db, "transactions", id))} customers={customers} services={services} />;
        case View.ADMIN_MARKETING: return <AdminMarketing customers={customers} promotions={promotions} services={services} bookings={bookings} />;
        default: return <AdminDashboard bookings={bookings} transactions={transactions} customers={customers} settings={settings} loggedMember={loggedAdminMember} />;
      }
    }

    if (currentUser && (currentView === View.CUSTOMER_DASHBOARD || currentView === View.CUSTOMER_LOGIN)) {
       return (
         <CustomerDashboard 
            customer={currentUser} 
            bookings={bookings} 
            services={services}
            settings={settings}
            onBook={() => {}}
            onUpdateProfile={(upd) => updateDoc(doc(db, "customers", currentUser.id), upd)}
            onLogout={() => { setCurrentUser(null); localStorage.removeItem('moria_user_session'); setCurrentView(View.CUSTOMER_HOME); }}
            onCancelBooking={(id) => updateDoc(doc(db, "bookings", id), {status: 'cancelled'})}
            onAddToWaitlist={(srvId, date) => addDoc(collection(db, "waitlist"), { customerId: currentUser.id, customerName: currentUser.name, customerWhatsapp: currentUser.whatsapp, serviceId: srvId, serviceName: services.find(s=>s.id===srvId)?.name, preferredDate: date, status: 'active', createdAt: new Date().toISOString() })}
            waitlist={waitlist.filter(w => w.customerId === currentUser.id)}
            onRemoveWaitlist={(id) => deleteDoc(doc(db, "waitlist", id))}
         />
       );
    }

    switch (currentView) {
      case View.CUSTOMER_REGISTER: return <CustomerRegister onRegister={(n, w, c, p, not) => {}} customers={customers} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      case View.CUSTOMER_LOGIN: return <CustomerLoginView onLogin={(c, p) => {}} onRegisterClick={() => setCurrentView(View.CUSTOMER_REGISTER)} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      default: return (
        <CustomerHome 
          settings={settings} services={services} bookings={bookings} 
          onBook={() => {}} 
          onAuthClick={() => setCurrentView(View.CUSTOMER_LOGIN)} 
          onAddToWaitlist={() => {}} 
          currentUser={currentUser} 
        />
      );
    }
  };

  return (
    <div className="min-h-screen bg-white">
      {currentView !== View.CUSTOMER_DASHBOARD && (
        <Navbar 
          view={currentView} 
          setView={setCurrentView} 
          isAdmin={isAdmin} 
          onToggleAdmin={() => { 
            if (isAdmin) handleAdminLogout();
            else { setCurrentView(View.ADMIN_LOGIN); setIsAdmin(true); }
          }} 
          salonName={settings.name} 
          logo={settings.logo} 
          currentUser={currentUser} 
          onLogout={() => { setCurrentUser(null); localStorage.removeItem('moria_user_session'); setCurrentView(View.CUSTOMER_HOME); }} 
          onAdminLogout={handleAdminLogout} 
          isAdminAuthenticated={!!loggedAdminMember} 
        />
      )}
      <main className={currentView === View.CUSTOMER_DASHBOARD ? "" : "max-w-7xl mx-auto px-4 py-8"}>
        {isLoading ? (
          <div className="flex items-center justify-center py-40">
            <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-tea-900"></div>
          </div>
        ) : renderView()}
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Booking, Service, TeamMember, SalonSettings, Customer } from '../types';
import { db } from '../firebase.ts';
import { collection, addDoc, doc, updateDoc, deleteDoc } from "firebase/firestore";

interface AdminCalendarProps {
  bookings: Booking[];
  services: Service[];
  customers: Customer[];
  teamMembers: TeamMember[];
  settings: SalonSettings; 
  loggedMember: TeamMember;
}

const AdminCalendar: React.FC<AdminCalendarProps> = ({ bookings, services, customers, teamMembers, settings, loggedMember }) => {
  const isOwner = loggedMember.role === 'owner';
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedProId, setSelectedProId] = useState(isOwner ? teamMembers[0]?.id : loggedMember.id);

  const [bookingModal, setBookingModal] = useState<{ open: boolean; hour: string }>({ open: false, hour: '' });
  const [actionModal, setActionModal] = useState<{ open: boolean; booking: Booking | null; hour: string }>({ open: false, booking: null, hour: '' });
  const [selectedCustomerId, setSelectedCustomerId] = useState('');
  const [selectedServiceId, setSelectedServiceId] = useState('');

  const selectedPro = teamMembers.find(m => m.id === selectedProId);
  const startHourNum = parseInt(settings.businessHours.start.split(':')[0]);
  const endHourNum = parseInt(settings.businessHours.end.split(':')[0]);

  const timeSlots = Array.from({ length: (endHourNum - startHourNum) * 2 + 1 }, (_, i) => {
    const totalMinutes = startHourNum * 60 + i * 30; 
    const h = Math.floor(totalMinutes / 60);
    const m = totalMinutes % 60;
    return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
  });

  const getSlotStatus = (hour: string) => {
    const activeBooking = bookings.find(b => 
      b.teamMemberId === selectedProId && 
      b.status !== 'cancelled' && 
      b.dateTime === `${selectedDate} ${hour}`
    );
    // REGRA MESTRE: Se não tem registro de liberação ou agendamento, o sistema entende como BLOQUEADO por padrão.
    return activeBooking ? { type: activeBooking.status, booking: activeBooking } : { type: 'blocked' };
  };

  const handleLiberateSlot = async (hour: string) => {
    await addDoc(collection(db, "bookings"), {
      customerId: 'liberated',
      customerName: 'HORÁRIO LIBERADO',
      serviceId: 'liberated',
      serviceName: 'Aberto para Agendamento',
      teamMemberId: selectedProId,
      teamMemberName: selectedPro?.name,
      dateTime: `${selectedDate} ${hour}`,
      duration: 30,
      status: 'liberated',
      depositStatus: 'paid',
      agreedToCancellationPolicy: true,
      policyAgreedAt: new Date().toISOString()
    });
    setActionModal({ open: false, booking: null, hour: '' });
  };

  const handleReleaseSlot = async (bookingId: string) => {
    await deleteDoc(doc(db, "bookings", bookingId));
    setActionModal({ open: false, booking: null, hour: '' });
  };

  const handleLiberateDay = async () => {
    if(!confirm("Liberar todos os horários deste dia para agendamento das clientes?")) return;
    for (const hour of timeSlots) {
      const status = getSlotStatus(hour);
      if (status.type === 'blocked') {
        await addDoc(collection(db, "bookings"), {
          customerId: 'liberated',
          customerName: 'HORÁRIO LIBERADO',
          serviceId: 'liberated',
          serviceName: 'Aberto para Agendamento',
          teamMemberId: selectedProId,
          teamMemberName: selectedPro?.name,
          dateTime: `${selectedDate} ${hour}`,
          duration: 30,
          status: 'liberated',
          depositStatus: 'paid',
          agreedToCancellationPolicy: true,
          policyAgreedAt: new Date().toISOString()
        });
      }
    }
    alert("Dia liberado para o público!");
  };

  const handleBlockDay = async () => {
    if(!confirm("Bloquear todo este dia? Registros de clientes não serão apagados, apenas liberações vago e bloqueios manuais.")) return;
    const dayBookings = bookings.filter(b => 
      b.teamMemberId === selectedProId && 
      b.dateTime.startsWith(selectedDate) && 
      (b.status === 'liberated' || b.status === 'blocked')
    );
    for (const b of dayBookings) {
      await deleteDoc(doc(db, "bookings", b.id));
    }
    alert("Dia bloqueado com sucesso!");
  };

  const confirmBooking = async () => {
    if (!selectedCustomerId || !selectedServiceId) return;
    const customer = customers.find(c => c.id === selectedCustomerId);
    const service = services.find(s => s.id === selectedServiceId);
    if (!customer || !service) return;

    // Remove liberação se existir
    const existing = getSlotStatus(bookingModal.hour);
    if (existing.booking && (existing.type === 'liberated' || existing.type === 'blocked')) {
      await deleteDoc(doc(db, "bookings", existing.booking.id));
    }

    await addDoc(collection(db, "bookings"), {
      customerId: customer.id,
      customerName: customer.name,
      serviceId: service.id,
      serviceName: service.name,
      teamMemberId: selectedProId,
      teamMemberName: selectedPro?.name,
      dateTime: `${selectedDate} ${bookingModal.hour}`,
      duration: service.duration,
      status: 'scheduled', 
      depositStatus: 'paid',
      finalPrice: service.price,
      agreedToCancellationPolicy: true,
      policyAgreedAt: new Date().toISOString()
    });
    setBookingModal({ open: false, hour: '' });
  };

  return (
    <div className="space-y-8 animate-fade-in pb-20">
      <div className="bg-white p-8 rounded-[3rem] border border-gray-100 shadow-sm flex flex-col md:flex-row gap-6 items-end">
        <div className="flex-1 space-y-2 w-full">
          <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Data da Agenda</label>
          <input type="date" value={selectedDate} onChange={e => setSelectedDate(e.target.value)} className="w-full p-4 bg-gray-50 border-none rounded-2xl font-bold" />
        </div>
        <div className="flex-1 space-y-2 w-full">
          <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Colaboradora</label>
          <select 
            value={selectedProId} 
            onChange={e => isOwner && setSelectedProId(e.target.value)} 
            disabled={!isOwner}
            className="w-full p-4 bg-gray-50 border-none rounded-2xl font-bold disabled:opacity-50"
          >
            {teamMembers.map(m => <option key={m.id} value={m.id}>{m.name}</option>)}
          </select>
        </div>
        <div className="flex gap-2 w-full md:w-auto">
           <button onClick={handleLiberateDay} className="flex-1 px-4 py-4 bg-tea-50 text-tea-900 border-2 border-tea-100 rounded-2xl text-[9px] font-bold uppercase tracking-widest hover:bg-tea-100 transition-all">🔓 Liberar Dia</button>
           <button onClick={handleBlockDay} className="flex-1 px-4 py-4 bg-gray-800 text-gray-300 rounded-2xl text-[9px] font-bold uppercase tracking-widest hover:bg-black transition-all">🔒 Bloquear Dia</button>
        </div>
      </div>

      <div className="bg-white rounded-[3.5rem] shadow-sm border border-gray-100 p-8 grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-6 gap-3">
        {timeSlots.map(hour => {
          const status = getSlotStatus(hour);

          let slotStyles = "bg-gray-50 text-gray-300 border-transparent grayscale shadow-inner";
          let label = "🔒 Bloqueado";

          if (status.type === 'scheduled' || status.type === 'pending') {
            slotStyles = "bg-tea-800 text-white border-tea-800 shadow-md";
            label = status.booking?.customerName.split(' ')[0] || '';
          } else if (status.type === 'completed') {
            slotStyles = "bg-green-600 text-white border-green-600";
            label = "Concluído";
          } else if (status.type === 'liberated') {
            slotStyles = "bg-white text-tea-900 border-tea-100 shadow-sm";
            label = "✨ Vago (Liberado)";
          }

          return (
            <button 
              key={hour} 
              onClick={() => setActionModal({open: true, booking: status.booking || null, hour})} 
              className={`p-5 rounded-3xl border-2 transition-all flex flex-col items-center justify-center min-h-[95px] relative group ${slotStyles}`}
            >
               <span className="text-lg font-serif font-bold italic">{hour}</span>
               <span className="text-[8px] font-bold uppercase tracking-widest mt-1 opacity-80 text-center line-clamp-1">
                 {label}
               </span>
            </button>
          );
        })}
      </div>

      {actionModal.open && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-fade-in">
          <div className="bg-white w-full max-sm:max-w-xs max-w-sm rounded-[3rem] p-10 shadow-3xl text-center space-y-6">
            <div className="space-y-2">
              <span className="text-[10px] font-bold text-tea-600 uppercase tracking-widest">Gestão de Horário</span>
              <h3 className="text-3xl font-serif font-bold italic text-tea-950">{actionModal.hour}</h3>
            </div>

            <div className="space-y-3">
              {actionModal.booking && (actionModal.booking.status === 'scheduled' || actionModal.booking.status === 'pending') ? (
                <div className="space-y-4">
                  <div className="p-4 bg-gray-50 rounded-2xl border border-gray-100 text-left">
                      <p className="text-[10px] font-bold text-gray-400 uppercase mb-1">Agendamento Ativo</p>
                      <p className="font-bold text-tea-900 text-lg">{actionModal.booking.customerName}</p>
                      <p className="text-[9px] text-tea-600 font-bold uppercase">{actionModal.booking.serviceName}</p>
                  </div>
                  <button onClick={() => updateDoc(doc(db, "bookings", actionModal.booking!.id), {status: 'completed'}).then(() => setActionModal({open:false, booking:null, hour:''}))} className="w-full py-4 bg-green-600 text-white rounded-2xl font-bold uppercase text-[10px] tracking-widest shadow-lg">Finalizar</button>
                  <button onClick={() => handleReleaseSlot(actionModal.booking!.id)} className="w-full py-4 bg-red-50 text-red-600 rounded-2xl font-bold uppercase text-[10px] tracking-widest">Cancelar</button>
                </div>
              ) : (
                <>
                  <button onClick={() => { setBookingModal({open: true, hour: actionModal.hour}); setActionModal({open:false, booking:null, hour:''}); }} className="w-full py-5 bg-tea-900 text-white rounded-2xl font-bold uppercase text-[10px] tracking-widest shadow-xl">📅 Agendar Cliente</button>
                  {actionModal.booking?.status === 'liberated' ? (
                    <button onClick={() => handleReleaseSlot(actionModal.booking!.id)} className="w-full py-5 bg-gray-800 text-gray-300 rounded-2xl font-bold uppercase text-[10px] tracking-widest">🔒 Bloquear Horário</button>
                  ) : (
                    <button onClick={() => handleLiberateSlot(actionModal.hour)} className="w-full py-5 bg-tea-50 text-tea-900 border-2 border-tea-100 rounded-2xl font-bold uppercase text-[10px] tracking-widest">✨ Liberar para Clientes</button>
                  )}
                </>
              )}
            </div>
            <button onClick={() => setActionModal({open:false, booking:null, hour:''})} className="w-full py-2 text-gray-400 font-bold uppercase text-[9px] tracking-widest">Fechar</button>
          </div>
        </div>
      )}

      {bookingModal.open && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-fade-in">
          <div className="bg-white w-full max-w-md rounded-[3rem] p-10 space-y-8 border-4 border-tea-100 shadow-3xl">
            <div className="text-center space-y-2">
              <h3 className="text-2xl font-serif font-bold italic text-tea-950">Novo Agendamento</h3>
              <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">Para {selectedDate} às {bookingModal.hour}</p>
            </div>

            <div className="space-y-4">
              <div className="space-y-1 text-left">
                <label className="text-[9px] font-bold text-tea-900 uppercase tracking-widest ml-2">Cliente</label>
                <select value={selectedCustomerId} onChange={e => setSelectedCustomerId(e.target.value)} className="w-full p-4 bg-gray-50 rounded-2xl font-bold outline-none border-2 border-transparent focus:border-tea-100 appearance-none">
                  <option value="">Selecione...</option>
                  {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>
              </div>
              <div className="space-y-1 text-left">
                <label className="text-[9px] font-bold text-tea-900 uppercase tracking-widest ml-2">Procedimento</label>
                <select value={selectedServiceId} onChange={e => setSelectedServiceId(e.target.value)} className="w-full p-4 bg-gray-50 rounded-2xl font-bold outline-none border-2 border-transparent focus:border-tea-100 appearance-none">
                  <option value="">Selecione...</option>
                  {services.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                </select>
              </div>
            </div>

            <div className="pt-4 flex flex-col gap-3">
              <button onClick={confirmBooking} className="w-full py-5 bg-tea-900 text-white rounded-2xl font-bold uppercase text-[10px] tracking-widest shadow-xl">Confirmar Reserva</button>
              <button onClick={() => setBookingModal({open:false, hour:''})} className="w-full py-2 text-gray-400 font-bold uppercase text-[9px]">Cancelar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

