import React, { useState, useEffect } from 'react';
import { View, Customer, Service, Booking, Transaction, SalonSettings, WaitlistEntry, Promotion, TeamMember } from './types.ts';
import { INITIAL_SERVICES, DEFAULT_SETTINGS } from './constants.ts';
import { db } from './firebase.ts';
import { 
  collection, 
  onSnapshot, 
  doc, 
  setDoc, 
  addDoc, 
  updateDoc, 
  deleteDoc
} from "firebase/firestore";

import Navbar from './components/Navbar.tsx';
import CustomerHome from './components/CustomerHome.tsx';
import CustomerRegister from './components/CustomerRegister.tsx';
import CustomerLoginView from './components/CustomerLoginView.tsx';
import CustomerProfile from './components/CustomerProfile.tsx';
import CustomerDashboard from './components/CustomerDashboard.tsx';
import AdminDashboard from './components/AdminDashboard.tsx';
import AdminCalendar from './components/AdminCalendar.tsx';
import AdminFinance from './components/AdminFinance.tsx';
import AdminClients from './components/AdminClients.tsx';
import AdminConfirmations from './components/AdminConfirmations.tsx';
import AdminSettingsView from './components/AdminSettingsView.tsx';
import AdminLogin from './components/AdminLogin.tsx';
import AdminMarketing from './components/AdminMarketing.tsx';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.CUSTOMER_HOME);
  const [isAdmin, setIsAdmin] = useState(false);
  const [loggedAdminMember, setLoggedAdminMember] = useState<TeamMember | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  const [settings, setSettings] = useState<SalonSettings>(DEFAULT_SETTINGS);
  const [services, setServices] = useState<Service[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [waitlist, setWaitlist] = useState<WaitlistEntry[]>([]);
  const [promotions, setPromotions] = useState<Promotion[]>([]);
  const [currentUser, setCurrentUser] = useState<Customer | null>(null);

  useEffect(() => {
    const unsubSettings = onSnapshot(doc(db, "settings", "main"), (snap) => {
      if (snap.exists()) {
        const remoteSettings = snap.data() as SalonSettings;

        let team = remoteSettings.teamMembers || [];
        const masterAdmin = team.find(m => m.id === 'tm1') || DEFAULT_SETTINGS.teamMembers[0];
        const otherMembers = team.filter(m => m.id !== 'tm1');

        // Mantém a Moriá sempre como tm1 e garante que ela não tenha serviços se for apenas admin
        const correctedTeam = [
          { 
            ...masterAdmin, 
            id: 'tm1', 
            username: 'admin', 
            password: '460206', 
            role: 'owner' as const,
            assignedServiceIds: masterAdmin.assignedServiceIds || [] 
          },
          ...otherMembers
        ];

        setSettings({ ...remoteSettings, teamMembers: correctedTeam });
        setIsLoading(false);
      } else {
        setDoc(doc(db, "settings", "main"), DEFAULT_SETTINGS).then(() => setIsLoading(false));
      }
    });

    const unsubServices = onSnapshot(collection(db, "services"), (snapshot) => {
      const data = snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Service));
      setServices(data);
    });

    const unsubCustomers = onSnapshot(collection(db, "customers"), (snapshot) => {
      setCustomers(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Customer)));
    });

    const unsubBookings = onSnapshot(collection(db, "bookings"), (snapshot) => {
      setBookings(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Booking)));
    });

    const unsubTransactions = onSnapshot(collection(db, "transactions"), (snapshot) => {
      setTransactions(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Transaction)));
    });

    const unsubWaitlist = onSnapshot(collection(db, "waitlist"), (snapshot) => {
      setWaitlist(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as WaitlistEntry)));
    });

    const unsubPromotions = onSnapshot(collection(db, "promotions"), (snapshot) => {
      setPromotions(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Promotion)));
    });

    return () => {
      unsubSettings(); unsubServices(); unsubCustomers();
      unsubBookings(); unsubTransactions(); unsubWaitlist(); unsubPromotions();
    };
  }, []);

  const handleAdminLogin = (member: TeamMember) => {
    setLoggedAdminMember(member);
    setIsAdmin(true);
    localStorage.setItem('moria_admin_session', JSON.stringify(member));
    setCurrentView(View.ADMIN_DASHBOARD);
  };

  const handleAdminLogout = () => {
    setLoggedAdminMember(null);
    setIsAdmin(false);
    localStorage.removeItem('moria_admin_session');
    setCurrentView(View.CUSTOMER_HOME);
  };

  const renderView = () => {
    if (isAdmin) {
      if (!loggedAdminMember) return <AdminLogin teamMembers={settings.teamMembers} onLogin={handleAdminLogin} onBack={() => { setIsAdmin(false); setCurrentView(View.CUSTOMER_HOME); }} />;

      switch (currentView) {
        case View.ADMIN_SETTINGS: return <AdminSettingsView settings={settings} services={services} customers={customers} bookings={bookings} transactions={transactions} loggedMember={loggedAdminMember} />;
        case View.ADMIN_CALENDAR: return <AdminCalendar bookings={bookings} services={services} customers={customers} teamMembers={settings.teamMembers} settings={settings} loggedMember={loggedAdminMember} />;
        case View.ADMIN_CONFIRMATIONS: return <AdminConfirmations bookings={bookings} customers={customers} waitlist={waitlist} onUpdateStatus={(id, s) => updateDoc(doc(db, "bookings", id), {status: s})} onUpdateDeposit={(id, d) => updateDoc(doc(db, "bookings", id), {depositStatus: d})} onDeleteBooking={(id) => deleteDoc(doc(db, "bookings", id))} onRemoveWaitlist={(id) => deleteDoc(doc(db, "waitlist", id))} />;
        case View.ADMIN_CLIENTS: return <AdminClients customers={customers} bookings={bookings} transactions={transactions} onDelete={(id) => deleteDoc(doc(db, "customers", id))} onUpdate={(id, d) => updateDoc(doc(db, "customers", id), d)} />;
        case View.ADMIN_FINANCE: return <AdminFinance transactions={transactions} onAdd={(d) => addDoc(collection(db, "transactions"), d)} onUpdate={(id, d) => updateDoc(doc(db, "transactions", id), d)} onDelete={(id) => deleteDoc(doc(db, "transactions", id))} customers={customers} services={services} />;
        case View.ADMIN_MARKETING: return <AdminMarketing customers={customers} promotions={promotions} services={services} bookings={bookings} />;
        default: return <AdminDashboard bookings={bookings} transactions={transactions} customers={customers} settings={settings} loggedMember={loggedAdminMember} />;
      }
    }

    if (currentUser && (currentView === View.CUSTOMER_DASHBOARD || currentView === View.CUSTOMER_LOGIN)) {
       return (
         <CustomerDashboard 
            customer={currentUser} 
            bookings={bookings} 
            services={services}
            settings={settings}
            onBook={() => {}}
            onUpdateProfile={(upd) => updateDoc(doc(db, "customers", currentUser.id), upd)}
            onLogout={() => { setCurrentUser(null); localStorage.removeItem('moria_user_session'); setCurrentView(View.CUSTOMER_HOME); }}
            onCancelBooking={(id) => updateDoc(doc(db, "bookings", id), {status: 'cancelled'})}
            onAddToWaitlist={(srvId, date) => addDoc(collection(db, "waitlist"), { customerId: currentUser.id, customerName: currentUser.name, customerWhatsapp: currentUser.whatsapp, serviceId: srvId, serviceName: services.find(s=>s.id===srvId)?.name, preferredDate: date, status: 'active', createdAt: new Date().toISOString() })}
            waitlist={waitlist.filter(w => w.customerId === currentUser.id)}
            onRemoveWaitlist={(id) => deleteDoc(doc(db, "waitlist", id))}
         />
       );
    }

    switch (currentView) {
      case View.CUSTOMER_REGISTER: return <CustomerRegister onRegister={(n, w, c, p, not) => {}} customers={customers} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      case View.CUSTOMER_LOGIN: return <CustomerLoginView onLogin={(c, p) => {}} onRegisterClick={() => setCurrentView(View.CUSTOMER_REGISTER)} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      default: return (
        <CustomerHome 
          settings={settings} services={services} bookings={bookings} 
          onBook={() => {}} 
          onAuthClick={() => setCurrentView(View.CUSTOMER_LOGIN)} 
          onAddToWaitlist={() => {}} 
          currentUser={currentUser} 
        />
      );
    }
  };

  return (
    <div className="min-h-screen bg-white">
      {currentView !== View.CUSTOMER_DASHBOARD && (
        <Navbar 
          view={currentView} 
          setView={setCurrentView} 
          isAdmin={isAdmin} 
          onToggleAdmin={() => { 
            if (isAdmin) handleAdminLogout();
            else { setCurrentView(View.ADMIN_LOGIN); setIsAdmin(true); }
          }} 
          salonName={settings.name} 
          logo={settings.logo} 
          currentUser={currentUser} 
          onLogout={() => { setCurrentUser(null); localStorage.removeItem('moria_user_session'); setCurrentView(View.CUSTOMER_HOME); }} 
          onAdminLogout={handleAdminLogout} 
          isAdminAuthenticated={!!loggedAdminMember} 
        />
      )}
      <main className={currentView === View.CUSTOMER_DASHBOARD ? "" : "max-w-7xl mx-auto px-4 py-8"}>
        {isLoading ? (
          <div className="flex items-center justify-center py-40">
            <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-tea-900"></div>
          </div>
        ) : renderView()}
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Booking, Service, TeamMember, SalonSettings, Customer } from '../types';
import { db } from '../firebase.ts';
import { collection, addDoc, doc, updateDoc, deleteDoc } from "firebase/firestore";

interface AdminCalendarProps {
  bookings: Booking[];
  services: Service[];
  customers: Customer[];
  teamMembers: TeamMember[];
  settings: SalonSettings; 
  loggedMember: TeamMember;
}

const AdminCalendar: React.FC<AdminCalendarProps> = ({ bookings, services, customers, teamMembers, settings, loggedMember }) => {
  const isOwner = loggedMember.role === 'owner';
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);

  // Se a Moriá não faz serviços, a agenda inicia selecionando o primeiro membro da equipe que faz serviços (se existir)
  const initialPro = teamMembers.find(m => m.assignedServiceIds.length > 0) || teamMembers[0];
  const [selectedProId, setSelectedProId] = useState(initialPro?.id);

  const [bookingModal, setBookingModal] = useState<{ open: boolean; hour: string }>({ open: false, hour: '' });
  const [actionModal, setActionModal] = useState<{ open: boolean; booking: Booking | null; hour: string }>({ open: false, booking: null, hour: '' });
  const [selectedCustomerId, setSelectedCustomerId] = useState('');
  const [selectedServiceId, setSelectedServiceId] = useState('');

  const selectedPro = teamMembers.find(m => m.id === selectedProId);
  const startHourNum = parseInt(settings.businessHours.start.split(':')[0]);
  const endHourNum = parseInt(settings.businessHours.end.split(':')[0]);

  const timeSlots = Array.from({ length: (endHourNum - startHourNum) * 2 + 1 }, (_, i) => {
    const totalMinutes = startHourNum * 60 + i * 30; 
    const h = Math.floor(totalMinutes / 60);
    const m = totalMinutes % 60;
    return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
  });

  const getSlotStatus = (hour: string) => {
    const activeBooking = bookings.find(b => 
      b.teamMemberId === selectedProId && 
      b.status !== 'cancelled' && 
      b.dateTime === `${selectedDate} ${hour}`
    );
    // REGRA: Tudo é BLOQUEADO se não houver registro de agendamento ou liberação explícita
    return activeBooking ? { type: activeBooking.status, booking: activeBooking } : { type: 'blocked' };
  };

  const handleLiberateSlot = async (hour: string) => {
    await addDoc(collection(db, "bookings"), {
      customerId: 'liberated',
      customerName: 'HORÁRIO LIBERADO',
      serviceId: 'liberated',
      serviceName: 'Aberto para Agendamento',
      teamMemberId: selectedProId,
      teamMemberName: selectedPro?.name,
      dateTime: `${selectedDate} ${hour}`,
      duration: 30,
      status: 'liberated',
      depositStatus: 'paid',
      agreedToCancellationPolicy: true,
      policyAgreedAt: new Date().toISOString()
    });
    setActionModal({ open: false, booking: null, hour: '' });
  };

  const handleReleaseSlot = async (bookingId: string) => {
    await deleteDoc(doc(db, "bookings", bookingId));
    setActionModal({ open: false, booking: null, hour: '' });
  };

  const handleLiberateDay = async () => {
    if(!confirm("Deseja LIBERAR todos os horários deste dia para o site?")) return;
    for (const hour of timeSlots) {
      const status = getSlotStatus(hour);
      if (status.type === 'blocked') {
        await addDoc(collection(db, "bookings"), {
          customerId: 'liberated',
          customerName: 'HORÁRIO LIBERADO',
          serviceId: 'liberated',
          serviceName: 'Aberto para Agendamento',
          teamMemberId: selectedProId,
          teamMemberName: selectedPro?.name,
          dateTime: `${selectedDate} ${hour}`,
          duration: 30,
          status: 'liberated',
          depositStatus: 'paid',
          agreedToCancellationPolicy: true,
          policyAgreedAt: new Date().toISOString()
        });
      }
    }
    alert("Dia liberado para o público!");
  };

  const handleBlockDay = async () => {
    if(!confirm("Deseja BLOQUEAR todo este dia? Isso remove as vagas do site. Agendamentos de clientes serão mantidos.")) return;
    const dayBookings = bookings.filter(b => 
      b.teamMemberId === selectedProId && 
      b.dateTime.startsWith(selectedDate) && 
      (b.status === 'liberated' || b.status === 'blocked')
    );
    for (const b of dayBookings) {
      await deleteDoc(doc(db, "bookings", b.id));
    }
    alert("Dia bloqueado com sucesso!");
  };

  const confirmBooking = async () => {
    if (!selectedCustomerId || !selectedServiceId) return;
    const customer = customers.find(c => c.id === selectedCustomerId);
    const service = services.find(s => s.id === selectedServiceId);
    if (!customer || !service) return;

    const existing = getSlotStatus(bookingModal.hour);
    if (existing.booking && (existing.type === 'liberated' || existing.type === 'blocked')) {
      await deleteDoc(doc(db, "bookings", existing.booking.id));
    }

    await addDoc(collection(db, "bookings"), {
      customerId: customer.id,
      customerName: customer.name,
      serviceId: service.id,
      serviceName: service.name,
      teamMemberId: selectedProId,
      teamMemberName: selectedPro?.name,
      dateTime: `${selectedDate} ${bookingModal.hour}`,
      duration: service.duration,
      status: 'scheduled', 
      depositStatus: 'paid',
      finalPrice: service.price,
      agreedToCancellationPolicy: true,
      policyAgreedAt: new Date().toISOString()
    });
    setBookingModal({ open: false, hour: '' });
  };

  return (
    <div className="space-y-8 animate-fade-in pb-20">
      <div className="bg-white p-8 rounded-[3rem] border border-gray-100 shadow-sm flex flex-col md:flex-row gap-6 items-end">
        <div className="flex-1 space-y-2 w-full">
          <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Data da Agenda</label>
          <input type="date" value={selectedDate} onChange={e => setSelectedDate(e.target.value)} className="w-full p-4 bg-gray-50 border-none rounded-2xl font-bold" />
        </div>
        <div className="flex-1 space-y-2 w-full">
          <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Profissional em Exibição</label>
          <select 
            value={selectedProId} 
            onChange={e => setSelectedProId(e.target.value)} 
            className="w-full p-4 bg-gray-50 border-none rounded-2xl font-bold"
          >
            {teamMembers.map(m => (
              <option key={m.id} value={m.id}>
                {m.name} {m.role === 'owner' ? '(ADM)' : ''}
              </option>
            ))}
          </select>
        </div>
        <div className="flex gap-2 w-full md:w-auto">
           <button onClick={handleLiberateDay} className="flex-1 px-4 py-4 bg-tea-50 text-tea-900 border-2 border-tea-100 rounded-2xl text-[9px] font-bold uppercase tracking-widest hover:bg-tea-100 transition-all">🔓 Liberar Dia</button>
           <button onClick={handleBlockDay} className="flex-1 px-4 py-4 bg-gray-800 text-gray-300 rounded-2xl text-[9px] font-bold uppercase tracking-widest hover:bg-black transition-all">🔒 Bloquear Dia</button>
        </div>
      </div>

      {selectedPro && selectedPro.assignedServiceIds.length === 0 && (
        <div className="p-6 bg-orange-50 rounded-3xl border border-orange-100 text-center">
           <p className="text-sm text-orange-800 font-bold italic">Atenção: {selectedPro.name} está como perfil administrativo e não possui serviços para agendamento direto.</p>
        </div>
      )}

      <div className="bg-white rounded-[3.5rem] shadow-sm border border-gray-100 p-8 grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-6 gap-3">
        {timeSlots.map(hour => {
          const status = getSlotStatus(hour);

          let slotStyles = "bg-gray-50 text-gray-300 border-transparent grayscale shadow-inner";
          let label = "🔒 Bloqueado";

          if (status.type === 'scheduled' || status.type === 'pending') {
            slotStyles = "bg-tea-800 text-white border-tea-800 shadow-md";
            label = status.booking?.customerName.split(' ')[0] || '';
          } else if (status.type === 'completed') {
            slotStyles = "bg-green-600 text-white border-green-600";
            label = "Concluído";
          } else if (status.type === 'liberated') {
            slotStyles = "bg-white text-tea-900 border-tea-100 shadow-sm";
            label = "✨ Aberto no Site";
          }

          return (
            <button 
              key={hour} 
              onClick={() => setActionModal({open: true, booking: status.booking || null, hour})} 
              className={`p-5 rounded-3xl border-2 transition-all flex flex-col items-center justify-center min-h-[95px] relative group ${slotStyles}`}
            >
               <span className="text-lg font-serif font-bold italic">{hour}</span>
               <span className="text-[8px] font-bold uppercase tracking-widest mt-1 opacity-80 text-center line-clamp-1">
                 {label}
               </span>
            </button>
          );
        })}
      </div>

      {actionModal.open && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-fade-in">
          <div className="bg-white w-full max-sm:max-w-xs max-w-sm rounded-[3rem] p-10 shadow-3xl text-center space-y-6">
            <div className="space-y-2">
              <span className="text-[10px] font-bold text-tea-600 uppercase tracking-widest">Gestão de Horário</span>
              <h3 className="text-3xl font-serif font-bold italic text-tea-950">{actionModal.hour}</h3>
            </div>

            <div className="space-y-3">
              {actionModal.booking && (actionModal.booking.status === 'scheduled' || actionModal.booking.status === 'pending') ? (
                <div className="space-y-4">
                  <div className="p-4 bg-gray-50 rounded-2xl border border-gray-100 text-left">
                      <p className="text-[10px] font-bold text-gray-400 uppercase mb-1">Agendamento Ativo</p>
                      <p className="font-bold text-tea-900 text-lg">{actionModal.booking.customerName}</p>
                      <p className="text-[9px] text-tea-600 font-bold uppercase">{actionModal.booking.serviceName}</p>
                  </div>
                  <button onClick={() => updateDoc(doc(db, "bookings", actionModal.booking!.id), {status: 'completed'}).then(() => setActionModal({open:false, booking:null, hour:''}))} className="w-full py-4 bg-green-600 text-white rounded-2xl font-bold uppercase text-[10px] tracking-widest shadow-lg">Finalizar Atendimento</button>
                  <button onClick={() => handleReleaseSlot(actionModal.booking!.id)} className="w-full py-4 bg-red-50 text-red-600 rounded-2xl font-bold uppercase text-[10px] tracking-widest">Cancelar Registro</button>
                </div>
              ) : (
                <>
                  <button onClick={() => { setBookingModal({open: true, hour: actionModal.hour}); setActionModal({open:false, booking:null, hour:''}); }} className="w-full py-5 bg-tea-900 text-white rounded-2xl font-bold uppercase text-[10px] tracking-widest shadow-xl">📅 Agendar Manualmente</button>
                  {actionModal.booking?.status === 'liberated' ? (
                    <button onClick={() => handleReleaseSlot(actionModal.booking!.id)} className="w-full py-5 bg-gray-800 text-gray-300 rounded-2xl font-bold uppercase text-[10px] tracking-widest">🔒 Bloquear para Clientes</button>
                  ) : (
                    <button onClick={() => handleLiberateSlot(actionModal.hour)} className="w-full py-5 bg-tea-50 text-tea-900 border-2 border-tea-100 rounded-2xl font-bold uppercase text-[10px] tracking-widest">✨ Abrir Vaga no Site</button>
                  )}
                </>
              )}
            </div>
            <button onClick={() => setActionModal({open:false, booking:null, hour:''})} className="w-full py-2 text-gray-400 font-bold uppercase text-[9px] tracking-widest">Fechar</button>
          </div>
        </div>
      )}

      {bookingModal.open && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-fade-in">
          <div className="bg-white w-full max-w-md rounded-[3rem] p-10 space-y-8 border-4 border-tea-100 shadow-3xl">
            <div className="text-center space-y-2">
              <h3 className="text-2xl font-serif font-bold italic text-tea-950">Agendamento Manual</h3>
              <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">Para {selectedDate} às {bookingModal.hour}</p>
            </div>

            <div className="space-y-4">
              <div className="space-y-1 text-left">
                <label className="text-[9px] font-bold text-tea-900 uppercase tracking-widest ml-2">Cliente do Studio</label>
                <select value={selectedCustomerId} onChange={e => setSelectedCustomerId(e.target.value)} className="w-full p-4 bg-gray-50 rounded-2xl font-bold outline-none border-2 border-transparent focus:border-tea-100 appearance-none">
                  <option value="">Selecione a cliente...</option>
                  {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>
              </div>
              <div className="space-y-1 text-left">
                <label className="text-[9px] font-bold text-tea-900 uppercase tracking-widest ml-2">Procedimento</label>
                <select value={selectedServiceId} onChange={e => setSelectedServiceId(e.target.value)} className="w-full p-4 bg-gray-50 rounded-2xl font-bold outline-none border-2 border-transparent focus:border-tea-100 appearance-none">
                  <option value="">Escolha o serviço...</option>
                  {services.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                </select>
              </div>
            </div>

            <div className="pt-4 flex flex-col gap-3">
              <button onClick={confirmBooking} className="w-full py-5 bg-tea-900 text-white rounded-2xl font-bold uppercase text-[10px] tracking-widest shadow-xl">Confirmar e Salvar</button>
              <button onClick={() => setBookingModal({open:false, hour:''})} className="w-full py-2 text-gray-400 font-bold uppercase text-[9px]">Descartar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminCalendar;

import React, { useState } from 'react';
import { Customer, Booking, Transaction } from '../types';
import { db } from '../firebase.ts';
import { collection, addDoc, doc, updateDoc, deleteDoc } from "firebase/firestore";

interface AdminClientsProps {
  customers: Customer[];
  bookings: Booking[];
  transactions: Transaction[];
  onDelete: (id: string) => void;
  onUpdate: (id: string, data: Partial<Customer>) => void;
}

const AdminClients: React.FC<AdminClientsProps> = ({ customers, bookings, transactions, onDelete, onUpdate }) => {
  const [search, setSearch] = useState('');
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);
  const [isEditing, setIsEditing] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);

  // Estados para Edição/Cadastro
  const [formData, setFormData] = useState({
    name: '',
    whatsapp: '',
    cpf: '',
    password: ''
  });

  const filtered = (customers || []).filter(c => {
    if (!c) return false;
    const s = (search || '').toLowerCase();
    const name = (c.name || '').toLowerCase();
    const whatsapp = (c.whatsapp || '');
    const cpf = (c.cpf || '');
    return name.includes(s) || whatsapp.includes(s) || cpf.includes(s);
  });

  const handleAddNew = async () => {
    if (!formData.name || !formData.whatsapp || !formData.cpf || !formData.password) {
      alert("Por favor, preencha todos os campos obrigatórios.");
      return;
    }

    const exists = customers.find(c => c.cpf.replace(/\D/g, '') === formData.cpf.replace(/\D/g, ''));
    if (exists) {
      alert("Este CPF já está cadastrado no sistema.");
      return;
    }

    try {
      await addDoc(collection(db, "customers"), {
        ...formData,
        receivesNotifications: true,
        agreedToTerms: true,
        history: [],
        createdAt: new Date().toISOString()
      });
      alert("Cliente cadastrada com sucesso! Ela já pode acessar o portal com o CPF e a senha definida.");
      setShowAddModal(false);
      setFormData({ name: '', whatsapp: '', cpf: '', password: '' });
    } catch (e) {
      alert("Erro ao salvar cliente.");
    }
  };

  const handleEditClick = () => {
    if (selectedCustomer) {
      setFormData({ 
        name: selectedCustomer.name || '', 
        whatsapp: selectedCustomer.whatsapp || '', 
        cpf: selectedCustomer.cpf || '',
        password: selectedCustomer.password || ''
      });
      setIsEditing(true);
    }
  };

  const handleSaveEdit = async () => {
    if (selectedCustomer) {
      await onUpdate(selectedCustomer.id, formData);
      setSelectedCustomer({ ...selectedCustomer, ...formData });
      setIsEditing(false);
      alert("Dados atualizados!");
    }
  };

  const getClientStats = (customerId: string) => {
    const myBookings = (bookings || []).filter(b => b.customerId === customerId);
    const myTransactions = (transactions || []).filter(t => t.customerId === customerId);
    const cancelledCount = myBookings.filter(b => b.status === 'cancelled').length;
    const paid = myTransactions.filter(t => t.status === 'paid' && t.type === 'receivable').reduce((sum, t) => sum + t.amount, 0);
    const pending = myTransactions.filter(t => t.status === 'pending' && t.type === 'receivable').reduce((sum, t) => sum + t.amount, 0);
    return { paid, pending, cancelledCount };
  };

  return (
    <div className="space-y-8 animate-fade-in pb-20">
      {/* Header com Busca e Ação */}
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 bg-white p-8 rounded-[3rem] border border-gray-100 shadow-sm">
        <div className="space-y-1">
          <h2 className="text-3xl font-serif font-bold text-tea-950 italic">Gestão de Clientes</h2>
          <p className="text-gray-400 text-sm">Administre cadastros e credenciais de acesso.</p>
        </div>
        <div className="flex flex-col sm:flex-row gap-4 w-full lg:w-auto">
          <div className="relative flex-1 sm:w-80">
            <span className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400">🔍</span>
            <input 
              placeholder="Buscar por nome ou CPF..." 
              className="w-full pl-12 pr-4 py-4 bg-gray-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-tea-100 font-medium"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
          </div>
          <button 
            onClick={() => { setFormData({ name: '', whatsapp: '', cpf: '', password: '' }); setShowAddModal(true); }}
            className="px-8 py-4 bg-tea-900 text-white rounded-2xl font-bold uppercase text-[10px] tracking-widest shadow-xl hover:bg-black transition-all"
          >
            ✨ Cadastrar Nova Cliente
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        {/* Lista Lateral */}
        <div className="lg:col-span-4 bg-white rounded-[3rem] shadow-sm border border-gray-100 overflow-hidden flex flex-col h-[650px]">
          <div className="p-6 bg-tea-50/50 border-b border-tea-100 flex justify-between items-center">
            <h3 className="font-bold text-tea-900 uppercase text-[9px] tracking-widest">Base Studio Moriá</h3>
            <span className="text-[9px] font-bold text-tea-600">{filtered.length} Registros</span>
          </div>
          <div className="overflow-y-auto flex-grow custom-scroll divide-y divide-gray-50">
            {filtered.map(customer => (
              <div 
                key={customer.id} 
                onClick={() => { setSelectedCustomer(customer); setIsEditing(false); }}
                className={`p-6 cursor-pointer transition-all hover:bg-tea-50/30 ${selectedCustomer?.id === customer.id ? 'bg-tea-50 border-l-4 border-tea-600' : ''}`}
              >
                <p className="font-bold text-tea-950 text-sm">{customer.name}</p>
                <p className="text-[10px] text-gray-400 font-medium mt-1">{customer.whatsapp}</p>
              </div>
            ))}
            {filtered.length === 0 && (
              <div className="p-20 text-center opacity-20 italic text-sm">Nenhuma cliente encontrada.</div>
            )}
          </div>
        </div>

        {/* Perfil Detalhado */}
        <div className="lg:col-span-8">
          {selectedCustomer ? (
            <div className="bg-white rounded-[3.5rem] shadow-sm border border-gray-100 overflow-hidden animate-slide-up h-full flex flex-col">
              <div className="p-10 bg-gray-50/30 border-b border-gray-100 flex justify-between items-center">
                <div className="flex gap-6 items-center">
                  <div className="w-20 h-20 bg-tea-900 rounded-[2.2rem] flex items-center justify-center text-white text-3xl font-serif font-bold shadow-xl">
                    {selectedCustomer.name.charAt(0)}
                  </div>
                  <div>
                    <h3 className="text-3xl font-serif text-tea-950 font-bold italic">{selectedCustomer.name}</h3>
                    <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest mt-1">CPF: {selectedCustomer.cpf} • WhatsApp: {selectedCustomer.whatsapp}</p>
                  </div>
                </div>
                <div className="flex gap-2">
                  <button onClick={handleEditClick} className="p-4 bg-white border border-gray-200 rounded-2xl hover:border-tea-500 shadow-sm transition-all">✏️</button>
                  <button onClick={() => { if(confirm("Excluir cliente?")) onDelete(selectedCustomer.id); setSelectedCustomer(null); }} className="p-4 bg-white border border-gray-200 rounded-2xl hover:border-red-500 shadow-sm transition-all text-red-400">🗑️</button>
                </div>
              </div>

              <div className="p-10 flex-grow space-y-10 overflow-y-auto custom-scroll">
                {isEditing ? (
