  const [modalConfig, setModalConfig] = useState<{ open: boolean; title: string; type: 'terms' | 'privacy' }>({
    open: false,
    title: '',
    type: 'terms'
  });

  // Verificação de CPF Duplicado (Apenas se o CPF for preenchido)
  const isDuplicateCpf = useMemo(() => {
    const cleanCpf = cpf.replace(/\D/g, '');
    if (cleanCpf.length < 1) return false;
    return customers.some(c => c.cpf && c.cpf.replace(/\D/g, '') === cleanCpf);
  }, [cpf, customers]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (isDuplicateCpf) {
      alert("Este CPF já possui um cadastro no Studio Moriá.");
      return;
    }
    // CPF agora é opcional, mas nome, whatsapp, senha e termos são obrigatórios
    if (name && whatsapp && password && agreedToTerms) {
      onRegister(name, whatsapp, cpf, password, receivesNotifications);
    } else {
      if (!agreedToTerms) {
        alert("Para sua segurança, é necessário aceitar os termos de uso.");
      } else {
        alert("Por favor, preencha todos os campos obrigatórios (Nome, WhatsApp e Senha).");
      }
    }
  };

  const openModal = (type: 'terms' | 'privacy') => {
    setModalConfig({
      open: true,
      type,
      title: type === 'terms' ? 'Termos de Uso' : 'Privacidade (LGPD)'
    });
  };

  return (
    <div className="min-h-screen flex items-center justify-center px-4 py-20 bg-[#F9FBFA]">
      <div className="max-w-xl w-full bg-white rounded-[3.5rem] shadow-[0_40px_100px_rgba(0,0,0,0.05)] overflow-hidden p-12 border border-white">
        <button onClick={onBack} className="text-tea-600 text-sm font-bold flex items-center gap-3 mb-12 hover:-translate-x-1 transition-transform group">
          <svg className="w-5 h-5 group-hover:scale-125 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M10 19l-7-7m0 0l7-7m-7 7h18"></path></svg>
          Voltar
        </button>

        <div className="mb-12">
          <h2 className="text-4xl font-serif text-tea-900 mb-4 italic">Sua Conta Moriá</h2>
          <p className="text-gray-500 font-light text-lg italic leading-relaxed">Cadastre-se para agendar seus procedimentos e acessar seu histórico de beleza.</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-8">
          <div className="space-y-4">
            <div className="relative group">
              <label className="block text-[11px] font-bold text-tea-700 uppercase tracking-[0.2em] mb-2 ml-2">Nome Completo</label>
              <input 
                type="text" 
                required
                value={name}
                onChange={(e) => setName(e.target.value)}
                className="w-full px-6 py-4 rounded-2xl bg-gray-50 border-transparent focus:bg-white focus:border-tea-200 outline-none transition-all placeholder-gray-300 shadow-inner"
                placeholder="Ex: Maria Santos"
              />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="relative group">
                <label className="block text-[11px] font-bold text-tea-700 uppercase tracking-[0.2em] mb-2 ml-2">WhatsApp</label>
                <input 
                  type="tel" 
                  required
                  value={whatsapp}
                  onChange={(e) => setWhatsapp(e.target.value)}
                  className="w-full px-6 py-4 rounded-2xl bg-gray-50 border-transparent focus:bg-white focus:border-tea-200 outline-none transition-all placeholder-gray-300 shadow-inner"
                  placeholder="(00) 00000-0000"
                />
              </div>
              <div className="relative group">
                <label className="block text-[11px] font-bold text-tea-700 uppercase tracking-[0.2em] mb-2 ml-2">Seu CPF (Opcional)</label>
                <input 
                  type="text" 
                  value={cpf}
                  onChange={(e) => setCpf(e.target.value)}
                  className={`w-full px-6 py-4 rounded-2xl bg-gray-50 border-2 outline-none transition-all placeholder-gray-300 shadow-inner ${isDuplicateCpf ? 'border-red-300 bg-red-50' : 'border-transparent focus:bg-white focus:border-tea-200'}`}
                  placeholder="000.000.000-00"
                />
                {isDuplicateCpf && <p className="text-[10px] text-red-600 font-bold mt-2 ml-2 uppercase animate-pulse">CPF já cadastrado! Tente fazer login.</p>}
              </div>
            </div>

            <div className="relative group">
              <label className="block text-[11px] font-bold text-tea-700 uppercase tracking-[0.2em] mb-2 ml-2">Crie uma Senha</label>
              <input 
                type="password" 
                required
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full px-6 py-4 rounded-2xl bg-gray-50 border-transparent focus:bg-white focus:border-tea-200 outline-none transition-all placeholder-gray-300 shadow-inner"
                placeholder="Mínimo 6 caracteres"
              />
            </div>
          </div>

          <div className="p-8 bg-tea-50/50 rounded-[2.5rem] border border-tea-100 space-y-6">
            <label className="flex items-start gap-5 cursor-pointer group">
              <div className="relative mt-1">
                <input 
                  type="checkbox"
                  checked={receivesNotifications}
                  onChange={(e) => setReceivesNotifications(e.target.checked)}
                  className="peer appearance-none w-6 h-6 rounded-lg border-2 border-tea-200 checked:bg-tea-500 checked:border-tea-500 transition-all cursor-pointer shadow-sm"
                />
                <svg className="absolute top-1 left-1 w-4 h-4 text-white opacity-0 peer-checked:opacity-100 transition-opacity pointer-events-none" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"></path></svg>
              </div>
              <div className="flex-1">
                <span className="text-sm font-bold text-tea-900 block mb-1">Receber lembretes via WhatsApp</span>
                <span className="text-xs text-tea-700/70 font-medium italic">Avisos de horários e promoções.</span>
              </div>
            </label>

            <label className="flex items-start gap-5 cursor-pointer group">
              <div className="relative mt-1">
                <input 
                  type="checkbox"
                  required
                  checked={agreedToTerms}
                  onChange={(e) => setAgreedToTerms(e.target.checked)}
                  className="peer appearance-none w-6 h-6 rounded-lg border-2 border-tea-200 checked:bg-tea-500 checked:border-tea-500 transition-all cursor-pointer shadow-sm"
                />
                <svg className="absolute top-1 left-1 w-4 h-4 text-white opacity-0 peer-checked:opacity-100 transition-opacity pointer-events-none" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"></path></svg>
              </div>
              <div className="flex-1">
                <span className="text-sm text-gray-700 leading-relaxed font-medium">
                  Aceito os <button type="button" onClick={() => openModal('terms')} className="text-tea-600 font-bold hover:underline">Termos</button> e a <button type="button" onClick={() => openModal('privacy')} className="text-tea-600 font-bold hover:underline">Política de Privacidade</button>.
                </span>
              </div>
            </label>
          </div>

          <button 
            type="submit"
            disabled={isDuplicateCpf || !agreedToTerms}
            className={`w-full py-6 rounded-[2rem] font-bold text-xl shadow-2xl transition-all duration-500 ${!isDuplicateCpf && agreedToTerms ? 'bg-tea-800 text-white hover:bg-tea-900 shadow-tea-200 hover:-translate-y-1' : 'bg-gray-100 text-gray-400 cursor-not-allowed opacity-70'}`}
          >
            {isDuplicateCpf ? 'CPF já em uso' : 'Concluir Cadastro'}
          </button>
        </form>
      </div>

      <TermsModal 
        isOpen={modalConfig.open} 
        onClose={() => setModalConfig({ ...modalConfig, open: false })}
        title={modalConfig.title}
        type={modalConfig.type}
      />
    </div>
  );
};

export default CustomerRegister;

import React, { useState } from 'react';
import { Customer, Booking, Transaction } from '../types';
import { db } from '../firebase.ts';
import { collection, addDoc, doc, updateDoc, deleteDoc } from "firebase/firestore";

interface AdminClientsProps {
  customers: Customer[];
  bookings: Booking[];
  transactions: Transaction[];
  onDelete: (id: string) => void;
  onUpdate: (id: string, data: Partial<Customer>) => void;
}

const AdminClients: React.FC<AdminClientsProps> = ({ customers, bookings, transactions, onDelete, onUpdate }) => {
  const [search, setSearch] = useState('');
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);
  const [isEditing, setIsEditing] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);

  const [formData, setFormData] = useState({
    name: '',
    whatsapp: '',
    cpf: '',
    password: ''
  });

  // Função para limpar referências circulares e metadados do Firestore antes de salvar
  const cleanData = (data: any) => {
    return JSON.parse(JSON.stringify(data));
  };

  const filtered = (customers || []).filter(c => {
    if (!c) return false;
    const s = (search || '').toLowerCase();
    const name = (c.name || '').toLowerCase();
    const whatsapp = (c.whatsapp || '');
    const cpf = (c.cpf || '');
    return name.includes(s) || whatsapp.includes(s) || cpf.includes(s);
  });

  const handleAddNew = async () => {
    // CPF agora é opcional. Validamos apenas o essencial.
    if (!formData.name || !formData.whatsapp || !formData.password) {
      alert("Por favor, preencha Nome, WhatsApp e defina uma Senha.");
      return;
    }

    if (formData.cpf) {
      const exists = customers.find(c => c.cpf && c.cpf.replace(/\D/g, '') === formData.cpf.replace(/\D/g, ''));
      if (exists) {
        alert("Este CPF já está cadastrado no sistema.");
        return;
      }
    }

    try {
      const newCustomer = {
        name: formData.name,
        whatsapp: formData.whatsapp,
        cpf: formData.cpf || "",
        password: formData.password,
        receivesNotifications: true,
        agreedToTerms: true,
        history: [],
        createdAt: new Date().toISOString()
      };

      await addDoc(collection(db, "customers"), cleanData(newCustomer));
      alert("Cliente cadastrada com sucesso! Ela já pode acessar o portal com os dados informados.");
      setShowAddModal(false);
      setFormData({ name: '', whatsapp: '', cpf: '', password: '' });
    } catch (e) {
      console.error("Erro ao cadastrar cliente:", e);
      alert("Erro ao salvar cadastro. Tente novamente.");
    }
  };

  const handleEditClick = () => {
    if (selectedCustomer) {
      setFormData({ 
        name: selectedCustomer.name || '', 
        whatsapp: selectedCustomer.whatsapp || '', 
        cpf: selectedCustomer.cpf || '',
        password: selectedCustomer.password || ''
      });
      setIsEditing(true);
    }
  };

  const handleSaveEdit = async () => {
    if (selectedCustomer) {
      try {
        const updatedFields = cleanData({
          name: formData.name,
          whatsapp: formData.whatsapp,
          cpf: formData.cpf,
          password: formData.password
        });

        await onUpdate(selectedCustomer.id, updatedFields);
        setSelectedCustomer({ ...selectedCustomer, ...updatedFields });
        setIsEditing(false);
        alert("Dados da cliente atualizados com sucesso!");
      } catch (e) {
        console.error("Erro ao editar cliente:", e);
        alert("Falha ao atualizar dados.");
      }
    }
  };

  const getClientStats = (customerId: string) => {
    const myBookings = (bookings || []).filter(b => b.customerId === customerId);
    const myTransactions = (transactions || []).filter(t => t.customerId === customerId);
    const cancelledCount = myBookings.filter(b => b.status === 'cancelled').length;
    const paid = myTransactions.filter(t => t.status === 'paid' && t.type === 'receivable').reduce((sum, t) => sum + t.amount, 0);
    const pending = myTransactions.filter(t => t.status === 'pending' && t.type === 'receivable').reduce((sum, t) => sum + t.amount, 0);
    return { paid, pending, cancelledCount };
  };

  return (
    <div className="space-y-8 animate-fade-in pb-20">
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 bg-white p-8 rounded-[3rem] border border-gray-100 shadow-sm">
        <div className="space-y-1">
          <h2 className="text-3xl font-serif font-bold text-tea-950 italic">Clientes</h2>
          <p className="text-gray-400 text-sm">Gerencie cadastros, senhas e histórico financeiro.</p>
        </div>
        <div className="flex flex-col sm:flex-row gap-4 w-full lg:w-auto">
          <div className="relative flex-1 sm:w-80">
            <span className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400">🔍</span>
            <input 
              placeholder="Buscar por nome, WhatsApp ou CPF..." 
              className="w-full pl-12 pr-4 py-4 bg-gray-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-tea-100 font-medium"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
          </div>
          <button 
            onClick={() => { setFormData({ name: '', whatsapp: '', cpf: '', password: '' }); setShowAddModal(true); }}
            className="px-8 py-4 bg-tea-900 text-white rounded-2xl font-bold uppercase text-[10px] tracking-widest shadow-xl hover:bg-black transition-all"
          >
            ✨ Cadastrar Nova Cliente
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        <div className="lg:col-span-4 bg-white rounded-[3rem] shadow-sm border border-gray-100 overflow-hidden flex flex-col h-[650px]">
          <div className="p-6 bg-tea-50/50 border-b border-tea-100 flex justify-between items-center">
            <h3 className="font-bold text-tea-900 uppercase text-[9px] tracking-widest">Base Studio Moriá</h3>
            <span className="text-[9px] font-bold text-tea-600">{filtered.length} Registros</span>
          </div>
          <div className="overflow-y-auto flex-grow custom-scroll divide-y divide-gray-50">
            {filtered.map(customer => (
              <div 
                key={customer.id} 
                onClick={() => { setSelectedCustomer(customer); setIsEditing(false); }}
                className={`p-6 cursor-pointer transition-all hover:bg-tea-50/30 ${selectedCustomer?.id === customer.id ? 'bg-tea-50 border-l-4 border-tea-600' : ''}`}
              >
                <p className="font-bold text-tea-950 text-sm">{customer.name}</p>
                <p className="text-[10px] text-gray-400 font-medium mt-1">{customer.whatsapp}</p>
              </div>
            ))}
            {filtered.length === 0 && (
              <div className="p-20 text-center opacity-20 italic text-sm">Nenhuma cliente encontrada.</div>
            )}
          </div>
        </div>

        <div className="lg:col-span-8">
          {selectedCustomer ? (
            <div className="bg-white rounded-[3.5rem] shadow-sm border border-gray-100 overflow-hidden animate-slide-up h-full flex flex-col">
              <div className="p-10 bg-gray-50/30 border-b border-gray-100 flex justify-between items-center">
                <div className="flex gap-6 items-center">
                  <div className="w-20 h-20 bg-tea-900 rounded-[2.2rem] flex items-center justify-center text-white text-3xl font-serif font-bold shadow-xl">
                    {selectedCustomer.name.charAt(0)}
                  </div>
                  <div>
                    <h3 className="text-3xl font-serif text-tea-950 font-bold italic">{selectedCustomer.name}</h3>
                    <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest mt-1">
                      {selectedCustomer.cpf ? `CPF: ${selectedCustomer.cpf}` : 'CPF: Não Informado'} • WhatsApp: {selectedCustomer.whatsapp}
                    </p>
                  </div>
                </div>
                <div className="flex gap-2">
                  <button onClick={handleEditClick} className="p-4 bg-white border border-gray-200 rounded-2xl hover:border-tea-500 shadow-sm transition-all">✏️</button>
                  <button onClick={() => { if(confirm("Excluir cliente?")) onDelete(selectedCustomer.id); setSelectedCustomer(null); }} className="p-4 bg-white border border-gray-200 rounded-2xl hover:border-red-500 shadow-sm transition-all text-red-400">🗑️</button>
                </div>
              </div>

              <div className="p-10 flex-grow space-y-10 overflow-y-auto custom-scroll">
                {isEditing ? (
                  <div className="space-y-6 animate-fade-in bg-tea-50/30 p-8 rounded-[2.5rem] border border-tea-100">
                    <h4 className="text-[10px] font-bold text-tea-900 uppercase tracking-widest mb-4">Editar Dados Cadastrais</h4>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                       <input value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} placeholder="Nome Completo" className="p-4 bg-white rounded-2xl border-none outline-none font-bold text-sm shadow-inner" />
                       <input value={formData.whatsapp} onChange={e => setFormData({...formData, whatsapp: e.target.value})} placeholder="WhatsApp" className="p-4 bg-white rounded-2xl border-none outline-none font-bold text-sm shadow-inner" />
                       <input value={formData.cpf} onChange={e => setFormData({...formData, cpf: e.target.value})} placeholder="CPF (Opcional)" className="p-4 bg-white rounded-2xl border-none outline-none font-bold text-sm shadow-inner" />
                       <input value={formData.password} onChange={e => setFormData({...formData, password: e.target.value})} placeholder="Senha de Acesso" className="p-4 bg-white rounded-2xl border-none outline-none font-bold text-sm shadow-inner" />
                    </div>
                    <div className="flex gap-3 pt-4">
                      <button onClick={handleSaveEdit} className="flex-1 py-4 bg-tea-900 text-white rounded-2xl font-bold uppercase text-[10px] tracking-widest shadow-lg">Salvar Alterações</button>
                      <button onClick={() => setIsEditing(false)} className="flex-1 py-4 bg-gray-100 text-gray-500 rounded-2xl font-bold uppercase text-[10px] tracking-widest">Cancelar</button>
                    </div>
                  </div>
                ) : (
                  <>
                    <section className="grid grid-cols-1 md:grid-cols-3 gap-6">
                      <div className="bg-tea-50 p-6 rounded-[2rem] border border-tea-100 text-center">
                        <p className="text-[9px] font-bold text-tea-700 uppercase mb-2">Total Pago</p>
                        <p className="text-2xl font-serif font-bold text-tea-900 italic">R$ {getClientStats(selectedCustomer.id).paid.toFixed(2)}</p>
                      </div>
                      <div className="bg-orange-50 p-6 rounded-[2rem] border border-orange-100 text-center">
                        <p className="text-[9px] font-bold text-orange-700 uppercase mb-2">Pendente</p>
                        <p className="text-2xl font-serif font-bold text-orange-900 italic">R$ {getClientStats(selectedCustomer.id).pending.toFixed(2)}</p>
                      </div>
                      <div className="bg-red-50 p-6 rounded-[2rem] border border-red-100 text-center">
                        <p className="text-[9px] font-bold text-red-700 uppercase mb-2">Cancelamentos</p>
                        <p className="text-2xl font-serif font-bold text-red-900 italic">{getClientStats(selectedCustomer.id).cancelledCount}</p>
                      </div>
                    </section>

                    <section className="space-y-4">
                      <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest border-b border-gray-50 pb-2 ml-2">Histórico Recente</h4>
                      <div className="space-y-3">
                        {bookings.filter(b => b.customerId === selectedCustomer.id).slice(0, 5).map(b => (
                          <div key={b.id} className="p-5 bg-white border border-gray-100 rounded-2xl flex justify-between items-center shadow-sm">
                            <div>
                              <p className="font-bold text-tea-950 text-sm">{b.serviceName}</p>
                              <p className="text-[9px] text-gray-400 font-bold uppercase">{b.dateTime}</p>
                            </div>
                            <span className={`px-3 py-1 rounded-full text-[8px] font-bold uppercase tracking-widest ${b.status === 'completed' ? 'bg-green-50 text-green-600' : 'bg-tea-50 text-tea-700'}`}>
                              {b.status === 'completed' ? 'Concluído' : 'Agendado'}
                            </span>
                          </div>
                        ))}
                      </div>
                    </section>
                  </>
                )}
              </div>
            </div>
          ) : (
            <div className="h-full flex flex-col items-center justify-center bg-gray-50/50 rounded-[4rem] border-4 border-dashed border-gray-100 p-20 text-center">
              <div className="w-24 h-24 bg-white rounded-full flex items-center justify-center text-4xl mb-6 shadow-sm border border-gray-200">👥</div>
              <h3 className="text-2xl font-serif text-tea-900 mb-2 font-bold italic">Selecione uma Cliente</h3>
              <p className="text-gray-400 max-w-xs mx-auto text-sm italic font-light leading-relaxed">Clique em uma cliente na lista ao lado para ver o perfil completo e credenciais de acesso.</p>
            </div>
          )}
        </div>
      </div>

      {showAddModal && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-fade-in">
          <div className="bg-white w-full max-w-lg rounded-[3.5rem] p-10 md:p-14 shadow-3xl animate-slide-up border-4 border-tea-100 space-y-8">
            <div className="text-center space-y-2">
              <h3 className="text-3xl font-serif font-bold italic text-tea-950">Novo Cadastro</h3>
              <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">Gere os dados de acesso para a cliente.</p>
            </div>

            <div className="space-y-5">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-tea-900 uppercase tracking-widest ml-2">Nome Completo *</label>
                <input 
                  type="text" 
                  value={formData.name} 
                  onChange={e => setFormData({...formData, name: e.target.value})}
                  className="w-full p-4 bg-gray-50 rounded-2xl font-bold outline-none focus:ring-2 focus:ring-tea-100 shadow-inner" 
                  placeholder="Ex: Maria Santos"
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-tea-900 uppercase tracking-widest ml-2">WhatsApp *</label>
                  <input 
                    type="tel" 
                    value={formData.whatsapp} 
                    onChange={e => setFormData({...formData, whatsapp: e.target.value})}
                    className="w-full p-4 bg-gray-50 rounded-2xl font-bold outline-none shadow-inner" 
                    placeholder="(13) 99999-0000"
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-tea-900 uppercase tracking-widest ml-2">CPF (Opcional)</label>
                  <input 
                    type="text" 
                    value={formData.cpf} 
                    onChange={e => setFormData({...formData, cpf: e.target.value})}
                    className="w-full p-4 bg-gray-50 rounded-2xl font-bold outline-none shadow-inner" 
                    placeholder="000.000.000-00"
                  />
                </div>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-tea-900 uppercase tracking-widest ml-2">Senha de Acesso *</label>
                <input 
                  type="text" 
                  value={formData.password} 
                  onChange={e => setFormData({...formData, password: e.target.value})}
                  className="w-full p-4 bg-gray-50 rounded-2xl font-bold outline-none border-2 border-tea-200 shadow-inner" 
                  placeholder="Crie uma senha inicial"
                />
                <p className="text-[8px] text-gray-400 italic ml-2 mt-1">* Informe esta senha à cliente para ela acessar o site.</p>
              </div>
            </div>

            <div className="pt-4 flex flex-col gap-3">
              <button onClick={handleAddNew} className="w-full py-5 bg-tea-900 text-white rounded-2xl font-bold uppercase text-[10px] tracking-widest shadow-xl hover:bg-black transition-all">Salvar Cliente</button>
              <button onClick={() => setShowAddModal(false)} className="w-full py-2 text-gray-400 font-bold uppercase text-[9px]">Cancelar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminClients;

import React, { useState, useMemo } from 'react';
import { Customer } from '../types';
import TermsModal from './TermsModal';

interface CustomerRegisterProps {
  onRegister: (name: string, whatsapp: string, cpf: string, password: string, receivesNotifications: boolean) => void;
  onBack: () => void;
  customers: Customer[];
}

const CustomerRegister: React.FC<CustomerRegisterProps> = ({ onRegister, onBack, customers = [] }) => {
  const [name, setName] = useState('');
  const [whatsapp, setWhatsapp] = useState('');
  const [cpf, setCpf] = useState('');
  const [password, setPassword] = useState('');
  const [receivesNotifications, setReceivesNotifications] = useState(true);
  const [agreedToTerms, setAgreedToTerms] = useState(false);

  const [modalConfig, setModalConfig] = useState<{ open: boolean; title: string; type: 'terms' | 'privacy' }>({
    open: false,
    title: '',
    type: 'terms'
  });

  // Verificação de CPF Duplicado (Apenas se o CPF for informado)
  const isDuplicateCpf = useMemo(() => {
    const cleanCpf = cpf.replace(/\D/g, '');
    if (cleanCpf.length < 1) return false;
    return customers.some(c => c.cpf && c.cpf.replace(/\D/g, '') === cleanCpf);
  }, [cpf, customers]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (isDuplicateCpf) {
      alert("Este CPF já possui um cadastro no Studio Moriá.");
      return;
    }

    // CPF é opcional, mas nome, whatsapp, senha e termos são obrigatórios
    if (name && whatsapp && password && agreedToTerms) {
      onRegister(name, whatsapp, cpf, password, receivesNotifications);
    } else {
      if (!agreedToTerms) {
        alert("Para sua segurança, é necessário aceitar os termos de uso.");
      } else {
        alert("Por favor, preencha todos os campos obrigatórios.");
      }
    }
  };

  const openModal = (type: 'terms' | 'privacy') => {
    setModalConfig({
      open: true,
      type,
      title: type === 'terms' ? 'Termos de Uso' : 'Privacidade (LGPD)'
    });
  };

  return (
    <div className="min-h-screen flex items-center justify-center px-4 py-20 bg-[#F9FBFA]">
      <div className="max-w-xl w-full bg-white rounded-[3.5rem] shadow-[0_40px_100px_rgba(0,0,0,0.05)] overflow-hidden p-12 border border-white">
        <button onClick={onBack} className="text-tea-600 text-sm font-bold flex items-center gap-3 mb-12 hover:-translate-x-1 transition-transform group">
          <svg className="w-5 h-5 group-hover:scale-125 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M10 19l-7-7m0 0l7-7m-7 7h18"></path></svg>
          Voltar
        </button>

        <div className="mb-12">
          <h2 className="text-4xl font-serif text-tea-900 mb-4 italic font-bold">Nova Conta</h2>
          <p className="text-gray-500 font-light text-lg italic leading-relaxed">Cadastre-se para agendar seus procedimentos no Studio Moriá.</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-8">
          <div className="space-y-4">
            <div className="relative group">
              <label className="block text-[11px] font-bold text-tea-700 uppercase tracking-[0.2em] mb-2 ml-2">Nome Completo *</label>
              <input 
                type="text" 
                required
                value={name}
                onChange={(e) => setName(e.target.value)}
                className="w-full px-6 py-4 rounded-2xl bg-gray-50 border-transparent focus:bg-white focus:border-tea-200 outline-none transition-all placeholder-gray-300 shadow-inner"
                placeholder="Ex: Maria Santos"
              />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="relative group">
                <label className="block text-[11px] font-bold text-tea-700 uppercase tracking-[0.2em] mb-2 ml-2">WhatsApp *</label>
                <input 
                  type="tel" 
                  required
                  value={whatsapp}
                  onChange={(e) => setWhatsapp(e.target.value)}
                  className="w-full px-6 py-4 rounded-2xl bg-gray-50 border-transparent focus:bg-white focus:border-tea-200 outline-none transition-all placeholder-gray-300 shadow-inner"
                  placeholder="(00) 00000-0000"
                />
              </div>
              <div className="relative group">
                <label className="block text-[11px] font-bold text-tea-700 uppercase tracking-[0.2em] mb-2 ml-2">Seu CPF (Opcional)</label>
                <input 
                  type="text" 
                  value={cpf}
                  onChange={(e) => setCpf(e.target.value)}
                  className={`w-full px-6 py-4 rounded-2xl bg-gray-50 border-2 outline-none transition-all placeholder-gray-300 shadow-inner ${isDuplicateCpf ? 'border-red-300 bg-red-50' : 'border-transparent focus:bg-white focus:border-tea-200'}`}
                  placeholder="000.000.000-00"
                />
                {isDuplicateCpf && <p className="text-[10px] text-red-600 font-bold mt-2 ml-2 uppercase animate-pulse">Este CPF já possui cadastro.</p>}
              </div>
            </div>

            <div className="relative group">
              <label className="block text-[11px] font-bold text-tea-700 uppercase tracking-[0.2em] mb-2 ml-2">Crie uma Senha *</label>
              <input 
                type="password" 
                required
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full px-6 py-4 rounded-2xl bg-gray-50 border-transparent focus:bg-white focus:border-tea-200 outline-none transition-all placeholder-gray-300 shadow-inner"
                placeholder="Mínimo 6 caracteres"
              />
            </div>
          </div>

          <div className="p-8 bg-tea-50/50 rounded-[2.5rem] border border-tea-100 space-y-6 shadow-sm">
            <label className="flex items-start gap-5 cursor-pointer group">
              <div className="relative mt-1">
                <input 
                  type="checkbox"
                  checked={receivesNotifications}
                  onChange={(e) => setReceivesNotifications(e.target.checked)}
                  className="peer appearance-none w-6 h-6 rounded-lg border-2 border-tea-200 checked:bg-tea-500 checked:border-tea-500 transition-all cursor-pointer shadow-sm"
                />
                <svg className="absolute top-1 left-1 w-4 h-4 text-white opacity-0 peer-checked:opacity-100 transition-opacity pointer-events-none" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"></path></svg>
              </div>
              <div className="flex-1">
                <span className="text-sm font-bold text-tea-900 block mb-1">Receber lembretes via WhatsApp</span>
                <span className="text-xs text-tea-700/70 font-medium italic">Avisos de agendamentos e novidades.</span>
              </div>
            </label>

            <label className="flex items-start gap-5 cursor-pointer group">
              <div className="relative mt-1">
                <input 
                  type="checkbox"
                  required
                  checked={agreedToTerms}
                  onChange={(e) => setAgreedToTerms(e.target.checked)}
                  className="peer appearance-none w-6 h-6 rounded-lg border-2 border-tea-200 checked:bg-tea-500 checked:border-tea-500 transition-all cursor-pointer shadow-sm"
                />
                <svg className="absolute top-1 left-1 w-4 h-4 text-white opacity-0 peer-checked:opacity-100 transition-opacity pointer-events-none" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"></path></svg>
              </div>
              <div className="flex-1">
                <span className="text-sm text-gray-700 leading-relaxed font-medium">
                  Aceito os <button type="button" onClick={() => openModal('terms')} className="text-tea-600 font-bold hover:underline">Termos</button> e a <button type="button" onClick={() => openModal('privacy')} className="text-tea-600 font-bold hover:underline">Política de Privacidade</button>.
                </span>
              </div>
            </label>
          </div>

          <button 
            type="submit"
            disabled={isDuplicateCpf || !agreedToTerms}
            className={`w-full py-6 rounded-[2rem] font-bold text-xl shadow-2xl transition-all duration-500 ${!isDuplicateCpf && agreedToTerms ? 'bg-tea-800 text-white hover:bg-tea-900 shadow-tea-200 hover:-translate-y-1' : 'bg-gray-100 text-gray-400 cursor-not-allowed opacity-70'}`}
          >
            Concluir Cadastro
          </button>
        </form>
      </div>

      <TermsModal 
        isOpen={modalConfig.open} 
        onClose={() => setModalConfig({ ...modalConfig, open: false })}
        title={modalConfig.title}
        type={modalConfig.type}
      />
    </div>
  );
};

export default CustomerRegister;

import React, { useState } from 'react';
import { SalonSettings, Service, TeamMember } from '../types.ts';
import { db } from '../firebase.ts';
import { doc, setDoc } from "firebase/firestore";

interface AdminSettingsViewProps {
  settings: SalonSettings;
  services: Service[];
  customers: any[];
  bookings: any[];
  transactions: any[];
  loggedMember: TeamMember;
}

const AdminSettingsView: React.FC<AdminSettingsViewProps> = ({ 
  settings, 
  services,
  loggedMember
}) => {
  const isOwner = loggedMember.role === 'owner';
  const [activeSubTab, setActiveSubTab] = useState<'identity' | 'operational' | 'team' | 'social'>('identity');

  const [tempSettings, setTempSettings] = useState<SalonSettings>(settings);
  const [memberInEdit, setMemberInEdit] = useState<TeamMember | null>(null);
  const [showPassword, setShowPassword] = useState<Record<string, boolean>>({});

  const togglePassword = (id: string) => {
    setShowPassword(prev => ({ ...prev, [id]: !prev[id] }));
  };

  // Função crítica para evitar erro de circularidade (Converting circular structure to JSON)
  const cleanData = (data: any) => {
    return JSON.parse(JSON.stringify(data));
  };

  const saveSettings = async (updated: SalonSettings) => {
    try {
      // Limpamos o objeto para remover referências internas do Firestore antes de salvar
      const dataToSave = cleanData({ 
        ...updated, 
        lastUpdated: Date.now() 
      });
      await setDoc(doc(db, "settings", "main"), dataToSave);
      alert("Configurações do Studio atualizadas!");
    } catch (e) {
      console.error("Erro ao salvar configurações:", e);
      alert("Erro ao salvar no banco de dados.");
    }
  };

  const handleMemberSave = async () => {
    if (!memberInEdit) return;
    const updatedTeam = [...tempSettings.teamMembers];
    const idx = updatedTeam.findIndex(m => m.id === memberInEdit.id);

    if (idx >= 0) updatedTeam[idx] = memberInEdit;
    else updatedTeam.push(memberInEdit);

    const newSettings = { ...tempSettings, teamMembers: updatedTeam };
    setTempSettings(newSettings);
    await saveSettings(newSettings);
    setMemberInEdit(null);
  };

  const renderIdentity = () => (
    <div className="space-y-8 animate-fade-in">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        <div className="space-y-4">
          <label className="text-[10px] font-bold text-tea-900 uppercase tracking-widest ml-2">Nome do Studio</label>
          <input 
            type="text" 
            value={tempSettings.name} 
            onChange={e => setTempSettings({...tempSettings, name: e.target.value})}
            className="w-full p-5 bg-gray-50 rounded-3xl font-bold border-2 border-transparent focus:border-tea-100 outline-none transition-all shadow-inner"
          />
        </div>
        <div className="space-y-4">
