    if (savedUser) {
      try {
        setCurrentUser(JSON.parse(savedUser));
        setCurrentView(View.CUSTOMER_DASHBOARD);
      } catch(e) { console.error("Sessão cliente corrompida."); }
    }

    // Ouvinte de Configurações - O mais crítico para o carregamento
