      const newCustomer = cleanData({
        name, whatsapp, cpf: cpf || "", password,
        receivesNotifications, agreedToTerms: true,
        history: [], createdAt: new Date().toISOString()
      });
      const docRef = await addDoc(collection(db, "customers"), newCustomer);
