  onDelete: (id: string) => Promise<void>;
}

const AdminFinance: React.FC<AdminFinanceProps> = ({ transactions, bookings, customers, onAdd, onUpdate, onDelete }) => {
  const [showAddForm, setShowAddForm] = useState(false);
  const [filter, setFilter] = useState<'all' | 'payable' | 'receivable'>('all');
  const [dateRange, setDateRange] = useState({
    start: new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0],
    end: new Date(new Date().getFullYear(), new Date().getMonth() + 1, 0).toISOString().split('T')[0]
  });

  // Estado do Novo Lançamento
  const [newTrans, setNewTrans] = useState({
    type: 'receivable' as 'payable' | 'receivable',
    description: '',
    amount: 0,
    date: new Date().toISOString().split('T')[0],
    status: 'paid' as 'paid' | 'pending',
    customerId: '',
    bookingId: ''
  });

  const [customerSearch, setCustomerSearch] = useState('');

  const filtered = useMemo(() => {
    const start = new Date(dateRange.start + 'T00:00:00').getTime();
    const end = new Date(dateRange.end + 'T23:59:59').getTime();
    return transactions.filter(t => {
      const d = new Date(t.date).getTime();
      return d >= start && d <= end && (filter === 'all' || t.type === filter);
    }).sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [transactions, filter, dateRange]);

  const summary = useMemo(() => {
    const rec = filtered.filter(t => t.type === 'receivable' && t.status === 'paid').reduce((a, b) => a + b.amount, 0);
    const pay = filtered.filter(t => t.type === 'payable' && t.status === 'paid').reduce((a, b) => a + b.amount, 0);
    const pendingRec = filtered.filter(t => t.type === 'receivable' && t.status === 'pending').reduce((a, b) => a + b.amount, 0);
    return { rec, pay, balance: rec - pay, pendingRec };
  }, [filtered]);

  const selectedCustomer = customers.find(c => c.id === newTrans.customerId);
  const customerBookings = bookings.filter(b => b.customerId === newTrans.customerId && b.status !== 'cancelled');

  const handleSave = async () => {
    if (!newTrans.description || newTrans.amount <= 0) return alert("Preencha descrição e valor.");

    const booking = bookings.find(b => b.id === newTrans.bookingId);

    const data = {
      ...newTrans,
      customerName: selectedCustomer?.name || '',
      serviceName: booking?.serviceName || '',
      procedureDate: booking?.dateTime || '',
      paidAt: newTrans.status === 'paid' ? new Date().toISOString() : null
    };

    await onAdd(data);
    setShowAddForm(false);
    setNewTrans({ type: 'receivable', description: '', amount: 0, date: new Date().toISOString().split('T')[0], status: 'paid', customerId: '', bookingId: '' });
  };

  return (
    <div className="space-y-8 animate-fade-in pb-20">
      <div className="flex flex-col lg:flex-row justify-between items-center bg-white p-8 rounded-[3rem] border border-gray-100 shadow-sm gap-6">
        <div>
          <h2 className="text-2xl font-bold text-tea-950 font-serif italic">Fluxo Moriá</h2>
          <p className="text-gray-500 text-sm">Gestão de entradas, saídas e vínculos de serviços.</p>
        </div>
        <div className="flex flex-wrap gap-4 items-center">
           <div className="flex bg-gray-100 p-1 rounded-xl">
              <button onClick={() => setFilter('all')} className={`px-4 py-2 rounded-lg text-[9px] font-bold uppercase ${filter === 'all' ? 'bg-white text-tea-900 shadow-sm' : 'text-gray-400'}`}>Tudo</button>
              <button onClick={() => setFilter('receivable')} className={`px-4 py-2 rounded-lg text-[9px] font-bold uppercase ${filter === 'receivable' ? 'bg-white text-tea-900 shadow-sm' : 'text-gray-400'}`}>Entradas</button>
              <button onClick={() => setFilter('payable')} className={`px-4 py-2 rounded-lg text-[9px] font-bold uppercase ${filter === 'payable' ? 'bg-white text-tea-900 shadow-sm' : 'text-gray-400'}`}>Saídas</button>
           </div>
           <input type="date" value={dateRange.start} onChange={e => setDateRange({...dateRange, start: e.target.value})} className="p-2.5 bg-gray-50 rounded-xl text-[10px] font-bold outline-none" />
           <input type="date" value={dateRange.end} onChange={e => setDateRange({...dateRange, end: e.target.value})} className="p-2.5 bg-gray-50 rounded-xl text-[10px] font-bold outline-none" />
           <button onClick={() => setShowAddForm(true)} className="bg-tea-900 text-white px-6 py-3 rounded-xl font-bold uppercase text-[10px] tracking-widest hover:bg-black transition-all shadow-lg">+ Novo Lançamento</button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        <div className="bg-green-50 p-6 rounded-[2rem] border border-green-100">
          <p className="text-[9px] font-bold text-green-700 uppercase tracking-widest mb-1">Entradas (Pagas)</p>
          <p className="text-2xl font-bold text-green-900">R$ {summary.rec.toLocaleString('pt-BR')}</p>
        </div>
        <div className="bg-red-50 p-6 rounded-[2rem] border border-red-100">
          <p className="text-[9px] font-bold text-red-700 uppercase tracking-widest mb-1">Despesas Pagas</p>
          <p className="text-2xl font-bold text-red-900">R$ {summary.pay.toLocaleString('pt-BR')}</p>
        </div>
        <div className="bg-orange-50 p-6 rounded-[2rem] border border-orange-100">
          <p className="text-[9px] font-bold text-orange-700 uppercase tracking-widest mb-1">A Receber (Pendente)</p>
          <p className="text-2xl font-bold text-orange-900">R$ {summary.pendingRec.toLocaleString('pt-BR')}</p>
        </div>
        <div className="bg-tea-950 p-6 rounded-[2rem] text-white">
          <p className="text-[9px] font-bold text-tea-400 uppercase tracking-widest mb-1">Saldo Líquido</p>
          <p className="text-2xl font-bold">R$ {summary.balance.toLocaleString('pt-BR')}</p>
        </div>
      </div>

      <div className="bg-white rounded-[3rem] shadow-sm border border-gray-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-gray-50 border-b border-gray-100">
              <tr>
                <th className="px-8 py-5 text-[9px] font-bold text-gray-400 uppercase tracking-widest">Data Lanc.</th>
                <th className="px-8 py-5 text-[9px] font-bold text-gray-400 uppercase tracking-widest">Descrição / Cliente</th>
                <th className="px-8 py-5 text-[9px] font-bold text-gray-400 uppercase tracking-widest">Vínculo Procedimento</th>
                <th className="px-8 py-5 text-[9px] font-bold text-gray-400 uppercase tracking-widest text-center">Status</th>
                <th className="px-8 py-5 text-[9px] font-bold text-gray-400 uppercase tracking-widest text-right">Valor</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {filtered.map(t => (
                <tr key={t.id} className="hover:bg-tea-50/20 group">
                  <td className="px-8 py-6">
                    <p className="font-bold text-xs text-gray-700">{new Date(t.date).toLocaleDateString()}</p>
                  </td>
                  <td className="px-8 py-6">
                    <p className="font-bold text-gray-900 text-sm">{t.description}</p>
                    {t.customerName && <p className="text-[10px] text-tea-600 font-bold uppercase">{t.customerName}</p>}
                  </td>
                  <td className="px-8 py-6">
                    {t.serviceName ? (
                      <div className="space-y-0.5">
                        <p className="text-xs font-medium text-gray-600">{t.serviceName}</p>
                        <p className="text-[9px] text-gray-400 font-bold uppercase tracking-tighter italic">Sessão: {t.procedureDate}</p>
                      </div>
                    ) : (
                      <span className="text-gray-300 italic text-[10px]">Sem vínculo</span>
                    )}
                  </td>
                  <td className="px-8 py-6 text-center">
                    <span className={`px-3 py-1 rounded-full text-[8px] font-bold uppercase tracking-widest ${t.status === 'paid' ? 'bg-green-100 text-green-700' : 'bg-orange-100 text-orange-700'}`}>
                      {t.status === 'paid' ? 'Pago' : 'Pendente'}
                    </span>
                  </td>
                  <td className={`px-8 py-6 font-bold text-right text-sm ${t.type === 'receivable' ? 'text-tea-800' : 'text-red-500'}`}>
                    {t.type === 'receivable' ? '+' : '-'} R$ {t.amount.toFixed(2)}
                  </td>
                </tr>
              ))}
              {filtered.length === 0 && (
                <tr><td colSpan={5} className="py-20 text-center text-gray-300 italic">Nenhum lançamento no período selecionado.</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {showAddForm && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fade-in">
          <div className="bg-white w-full max-w-xl rounded-[3rem] p-10 shadow-3xl animate-slide-up space-y-6 max-h-[90vh] overflow-y-auto custom-scroll">
            <h3 className="text-2xl font-serif text-tea-950 font-bold italic text-center">Novo Lançamento Financeiro</h3>

            <div className="space-y-6">
               <div className="flex bg-gray-100 p-1.5 rounded-2xl">
                  <button onClick={() => setNewTrans({...newTrans, type: 'receivable'})} className={`flex-1 py-3 rounded-xl text-[10px] font-bold uppercase tracking-widest transition-all ${newTrans.type === 'receivable' ? 'bg-white text-tea-900 shadow-sm' : 'text-gray-400'}`}>Entrada (Receita)</button>
                  <button onClick={() => setNewTrans({...newTrans, type: 'payable'})} className={`flex-1 py-3 rounded-xl text-[10px] font-bold uppercase tracking-widest transition-all ${newTrans.type === 'payable' ? 'bg-white text-red-600 shadow-sm' : 'text-gray-400'}`}>Saída (Despesa)</button>
               </div>

               <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[9px] font-bold text-gray-400 uppercase ml-2">Data</label>
                    <input type="date" value={newTrans.date} onChange={e => setNewTrans({...newTrans, date: e.target.value})} className="w-full p-4 bg-gray-50 rounded-2xl outline-none font-bold text-sm" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[9px] font-bold text-gray-400 uppercase ml-2">Status</label>
                    <select value={newTrans.status} onChange={e => setNewTrans({...newTrans, status: e.target.value as any})} className="w-full p-4 bg-gray-50 rounded-2xl outline-none font-bold text-sm">
                       <option value="paid">Confirmado (Pago)</option>
                       <option value="pending">Pendente (A Receber)</option>
                    </select>
                  </div>
               </div>

               <div className="space-y-1">
                  <label className="text-[9px] font-bold text-gray-400 uppercase ml-2">Descrição</label>
                  <input type="text" placeholder="Ex: Pagamento Sobrancelha ou Aluguel Unidade" value={newTrans.description} onChange={e => setNewTrans({...newTrans, description: e.target.value})} className="w-full p-4 bg-gray-50 rounded-2xl outline-none font-bold text-sm" />
               </div>

               <div className="space-y-1">
                  <label className="text-[9px] font-bold text-gray-400 uppercase ml-2">Valor R$</label>
                  <input type="number" placeholder="0,00" value={newTrans.amount || ''} onChange={e => setNewTrans({...newTrans, amount: parseFloat(e.target.value)})} className="w-full p-4 bg-gray-50 rounded-2xl outline-none font-bold text-lg text-tea-900" />
               </div>

               {newTrans.type === 'receivable' && (
                 <div className="p-6 bg-tea-50/50 rounded-3xl border border-tea-100 space-y-4">
                    <p className="text-[9px] font-bold text-tea-800 uppercase tracking-widest text-center">Vincular a Cliente & Serviço</p>
                    <input type="text" placeholder="Buscar cliente..." value={customerSearch} onChange={e => setCustomerSearch(e.target.value)} className="w-full p-3 bg-white rounded-xl text-xs outline-none border border-gray-100" />
                    <div className="max-h-32 overflow-y-auto space-y-1">
                       {customers.filter(c => c.name.toLowerCase().includes(customerSearch.toLowerCase())).slice(0, 4).map(c => (
                         <button key={c.id} onClick={() => { setNewTrans({...newTrans, customerId: c.id}); setCustomerSearch(c.name); }} className={`w-full p-3 text-left text-[11px] rounded-lg transition-all ${newTrans.customerId === c.id ? 'bg-tea-800 text-white font-bold' : 'bg-white hover:bg-tea-50'}`}>{c.name}</button>
                       ))}
                    </div>

                    {newTrans.customerId && (
                      <div className="space-y-2 animate-fade-in">
                         <label className="text-[9px] font-bold text-gray-400 uppercase ml-2">Selecione o Agendamento</label>
                         <select value={newTrans.bookingId} onChange={e => setNewTrans({...newTrans, bookingId: e.target.value})} className="w-full p-3 bg-white rounded-xl text-xs font-bold outline-none border border-gray-100">
                            <option value="">Lançamento Avulso (Sem agendamento)</option>
                            {customerBookings.map(b => (
                              <option key={b.id} value={b.id}>{b.serviceName} - {b.dateTime}</option>
                            ))}
                         </select>
                         <p className="text-[8px] text-tea-600 font-bold uppercase tracking-widest text-center italic">* Vincular ajuda no controle do histórico da cliente.</p>
                      </div>
                    )}
                 </div>
               )}

               <div className="flex gap-4 pt-4">
                  <button onClick={() => setShowAddForm(false)} className="flex-1 py-4 text-gray-400 font-bold uppercase text-[10px] tracking-widest">Cancelar</button>
                  <button onClick={handleSave} className="flex-[2] bg-tea-900 text-white py-4 rounded-2xl font-bold uppercase text-[10px] tracking-widest shadow-xl hover:bg-black">Salvar Lançamento</button>
               </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminFinance;

import React, { useState, useEffect } from 'react';
import { View, Customer, Service, Booking, Transaction, SalonSettings, WaitlistEntry, Promotion } from './types.ts';
import { INITIAL_SERVICES, DEFAULT_SETTINGS } from './constants.ts';
import { db } from './firebase.ts';
import { 
  collection, 
  onSnapshot, 
  doc, 
  setDoc, 
  addDoc, 
  updateDoc, 
  deleteDoc,
  increment
} from "firebase/firestore";

import Navbar from './components/Navbar.tsx';
import CustomerHome from './components/CustomerHome.tsx';
import CustomerRegister from './components/CustomerRegister.tsx';
import CustomerLoginView from './components/CustomerLoginView.tsx';
import CustomerProfile from './components/CustomerProfile.tsx';
import CustomerDashboard from './components/CustomerDashboard.tsx';
import AdminDashboard from './components/AdminDashboard.tsx';
import AdminCalendar from './components/AdminCalendar.tsx';
import AdminFinance from './components/AdminFinance.tsx';
import AdminClients from './components/AdminClients.tsx';
import AdminConfirmations from './components/AdminConfirmations.tsx';
import AdminSettingsView from './components/AdminSettingsView.tsx';
import AdminLogin from './components/AdminLogin.tsx';
import AdminMarketing from './components/AdminMarketing.tsx';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.CUSTOMER_HOME);
  const [isAdmin, setIsAdmin] = useState(false);
  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  const [settings, setSettings] = useState<SalonSettings>(DEFAULT_SETTINGS);
  const [services, setServices] = useState<Service[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [waitlist, setWaitlist] = useState<WaitlistEntry[]>([]);
  const [promotions, setPromotions] = useState<Promotion[]>([]);
  const [currentUser, setCurrentUser] = useState<Customer | null>(null);

  useEffect(() => {
    if (db._isMock) {
      console.log("Modo Visual: Firestore Mock Ativo.");
      setIsLoading(false);
      return;
    }

    const unsubSettings = onSnapshot(doc(db, "settings", "main"), (snap) => {
      if (snap.exists()) {
        setSettings(snap.data() as SalonSettings);
        setIsLoading(false);
      } else {
        setDoc(doc(db, "settings", "main"), DEFAULT_SETTINGS).then(() => setIsLoading(false));
      }
    }, () => setIsLoading(false));

    const unsubServices = onSnapshot(collection(db, "services"), (snapshot) => {
      setServices(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Service)));
    });

    const unsubCustomers = onSnapshot(collection(db, "customers"), (snapshot) => {
      setCustomers(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Customer)));
    });

    const unsubBookings = onSnapshot(collection(db, "bookings"), (snapshot) => {
      setBookings(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Booking)));
    });

    const unsubTransactions = onSnapshot(collection(db, "transactions"), (snapshot) => {
      setTransactions(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Transaction)));
    });

    const unsubWaitlist = onSnapshot(collection(db, "waitlist"), (snapshot) => {
      setWaitlist(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as WaitlistEntry)));
    });

    const unsubPromotions = onSnapshot(collection(db, "promotions"), (snapshot) => {
      setPromotions(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Promotion)));
    });

    return () => {
      unsubSettings(); unsubServices(); unsubCustomers();
      unsubBookings(); unsubTransactions(); unsubWaitlist(); unsubPromotions();
    };
  }, []);

  const handleUpdateStatus = async (id: string, status: any) => {
    if (db._isMock) return;
    const updateData: any = { status };
    if (status === 'cancelled') updateData.cancelledAt = new Date().toISOString();
    await updateDoc(doc(db, "bookings", id), updateData);
  };

  const handleUpdateDeposit = async (id: string, depositStatus: 'paid' | 'pending') => {
    if (db._isMock) return;
    await updateDoc(doc(db, "bookings", id), { depositStatus });
  };

  const renderView = () => {
    if (isAdmin) {
      if (!isAdminAuthenticated) return <AdminLogin onLogin={() => { setIsAdminAuthenticated(true); setCurrentView(View.ADMIN_DASHBOARD); }} onBack={() => setIsAdmin(false)} />;
      switch (currentView) {
        case View.ADMIN_SETTINGS: return <AdminSettingsView settings={settings} services={services} customers={customers} bookings={bookings} transactions={transactions} />;
        case View.ADMIN_CALENDAR: return <AdminCalendar bookings={bookings} services={services} customers={customers} teamMembers={settings.teamMembers} settings={settings} onUpdateStatus={handleUpdateStatus} />;
        case View.ADMIN_CONFIRMATIONS: return <AdminConfirmations bookings={bookings} customers={customers} onUpdateStatus={handleUpdateStatus} onUpdateDeposit={handleUpdateDeposit} onDeleteBooking={(id) => !db._isMock && updateDoc(doc(db, "bookings", id), {status: 'cancelled'})} waitlist={waitlist} onRemoveWaitlist={(id) => !db._isMock && deleteDoc(doc(db, "waitlist", id))} />;
        case View.ADMIN_CLIENTS: return <AdminClients customers={customers} bookings={bookings} transactions={transactions} onDelete={(id) => !db._isMock && deleteDoc(doc(db, "customers", id))} onUpdate={(id, data) => !db._isMock && updateDoc(doc(db, "customers", id), data)} />;
        case View.ADMIN_FINANCE: return <AdminFinance transactions={transactions} bookings={bookings} customers={customers} onAdd={async (d) => { if(!db._isMock) await addDoc(collection(db, "transactions"), d); }} onUpdate={(id, d) => !db._isMock && updateDoc(doc(db, "transactions", id), d)} onDelete={(id) => !db._isMock && deleteDoc(doc(db, "transactions", id))} />;
        case View.ADMIN_MARKETING: return <AdminMarketing customers={customers} promotions={promotions} services={services} bookings={bookings} />;
        default: return <AdminDashboard bookings={bookings} transactions={transactions} customers={customers} settings={settings} />;
      }
    }

    if (currentUser && currentView === View.CUSTOMER_DASHBOARD) {
       return (
         <CustomerDashboard 
            customer={currentUser} 
            bookings={bookings} 
            services={services}
            settings={settings}
            onBook={() => {}}
            onUpdateProfile={(upd) => !db._isMock && updateDoc(doc(db, "customers", currentUser.id), upd)}
            onLogout={() => { setCurrentUser(null); setCurrentView(View.CUSTOMER_HOME); }}
            onCancelBooking={(id) => !db._isMock && updateDoc(doc(db, "bookings", id), {status: 'cancelled'})}
            onAddToWaitlist={() => {}}
            waitlist={waitlist.filter(w => w.customerId === currentUser.id && w.status !== 'cancelled')}
            onRemoveWaitlist={(id) => !db._isMock && deleteDoc(doc(db, "waitlist", id))}
            promotions={promotions}
         />
       );
    }

    switch (currentView) {
      case View.CUSTOMER_REGISTER: return (
        <CustomerRegister 
          onRegister={async (n, w, c, p, not) => {
            if(db._isMock) return;
            const id = Math.random().toString(36).substr(2, 9);
            const user = { id, name: n, whatsapp: w, cpf: c, password: p, receivesNotifications: not, agreedToTerms: true, history: [] };
            await setDoc(doc(db, "customers", id), user);
            setCurrentUser(user);
            setCurrentView(View.CUSTOMER_DASHBOARD);
          }} 
          customers={customers} 
          onBack={() => setCurrentView(View.CUSTOMER_HOME)} 
        />
      );
      case View.CUSTOMER_LOGIN: return (
        <CustomerLoginView 
          onLogin={(cpf, pass) => {
            const user = customers.find(c => c.cpf === cpf && c.password === pass);
            if (user) { setCurrentUser(user); setCurrentView(View.CUSTOMER_DASHBOARD); }
            else alert("Acesso inválido.");
          }} 
          onRegisterClick={() => setCurrentView(View.CUSTOMER_REGISTER)} 
          onBack={() => setCurrentView(View.CUSTOMER_HOME)} 
        />
      );
      default: return (
        <CustomerHome 
          settings={settings} services={services} bookings={bookings} 
          onBook={() => {}} 
          onAuthClick={() => setCurrentView(View.CUSTOMER_LOGIN)} 
          onAddToWaitlist={() => {}} 
          currentUser={currentUser} 
        />
      );
    }
  };

  return (
    <div className="min-h-screen bg-white">
      {currentView !== View.CUSTOMER_DASHBOARD && (
        <Navbar 
          view={currentView} setView={setCurrentView} isAdmin={isAdmin} 
          onToggleAdmin={() => { setIsAdmin(!isAdmin); if(!isAdminAuthenticated) setCurrentView(View.ADMIN_LOGIN); else setCurrentView(isAdmin ? View.CUSTOMER_HOME : View.ADMIN_DASHBOARD); }} 
          salonName={settings.name} logo={settings.logo} currentUser={currentUser} 
          onLogout={() => { setCurrentUser(null); setCurrentView(View.CUSTOMER_HOME); }} 
          onAdminLogout={() => { setIsAdminAuthenticated(false); setIsAdmin(false); setCurrentView(View.CUSTOMER_HOME); }} 
          isAdminAuthenticated={isAdminAuthenticated} pendingBookingsCount={bookings.filter(b => b.status === 'pending').length} 
        />
      )}
      <main className={currentView === View.CUSTOMER_DASHBOARD ? "" : "max-w-7xl mx-auto px-4 py-8"}>
        {isLoading ? (
          <div className="flex flex-col items-center justify-center py-40 gap-4">
            <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-tea-600"></div>
            <p className="text-tea-800 font-serif italic">Studio Moriá Estética...</p>
          </div>
        ) : renderView()}
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Customer, Transaction, Booking } from '../types';
import TermsModal from './TermsModal';

interface CustomerProfileProps {
  customer: Customer;
  transactions: Transaction[];
  bookings: Booking[];
  onUpdateNotification: (val: boolean) => void;
  onBack: () => void;
}

const CustomerProfile: React.FC<CustomerProfileProps> = ({ customer, transactions, bookings, onUpdateNotification, onBack }) => {
  const [modalConfig, setModalConfig] = useState<{ open: boolean; title: string; type: 'terms' | 'privacy' }>({
    open: false,
    title: '',
    type: 'terms'
  });

  const openModal = (type: 'terms' | 'privacy') => {
    setModalConfig({
      open: true,
      type,
      title: type === 'terms' ? 'Termos de Uso' : 'Política de Privacidade (LGPD)'
    });
  };

  const myTransactions = transactions.filter(t => t.customerId === customer.id).sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  const myBookings = bookings.filter(b => b.customerId === customer.id);

  const totalPaid = myTransactions
    .filter(t => t.status === 'paid' && t.type === 'receivable')
    .reduce((sum, t) => sum + t.amount, 0);

  const totalPending = myTransactions
    .filter(t => t.status === 'pending' && t.type === 'receivable')
    .reduce((sum, t) => sum + t.amount, 0);

  const nextDueDate = myTransactions
    .filter(t => t.status === 'pending')
    .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime())[0];

  const todayStr = new Date().toISOString().split('T')[0];
  const isDueToday = nextDueDate && nextDueDate.date === todayStr;

  return (
    <div className="max-w-4xl mx-auto px-4 py-16 animate-fade-in">
      <button onClick={onBack} className="flex items-center gap-2 text-tea-600 font-bold mb-10 group">
        <svg className="w-5 h-5 group-hover:-translate-x-1 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M10 19l-7-7m0 0l7-7m-7 7h18"></path></svg>
        Voltar para a Home
      </button>

      {isDueToday && (
        <div className="mb-8 bg-orange-50 border-l-4 border-orange-400 p-6 rounded-2xl flex items-center justify-between shadow-sm animate-bounce-subtle">
          <div className="flex items-center gap-4">
            <span className="text-3xl">⚠️</span>
            <div>
              <p className="font-bold text-orange-900">Vencimento Hoje!</p>
              <p className="text-sm text-orange-700">Olá {customer.name.split(' ')[0]}, seu pagamento de R$ {nextDueDate.amount.toFixed(2)} vence hoje.</p>
            </div>
          </div>
        </div>
      )}

      <div className="bg-white rounded-[2.5rem] shadow-sm border border-tea-50 overflow-hidden">
        <div className="bg-tea-800 p-10 text-white flex justify-between items-end relative overflow-hidden">
           <div className="absolute top-0 right-0 w-32 h-32 bg-tea-700 rounded-full -mr-16 -mt-16 opacity-30"></div>
          <div>
            <h2 className="text-3xl font-serif font-bold mb-2">{customer.name}</h2>
            <p className="opacity-80 text-sm">CPF: {customer.cpf}</p>
          </div>
          <div className="bg-white/10 backdrop-blur-sm px-4 py-2 rounded-full text-xs font-bold uppercase tracking-widest relative z-10 border border-white/20">Perfil Verificado</div>
        </div>

        <div className="p-10 space-y-12">
          <section>
            <h3 className="text-xl font-bold text-tea-900 mb-6 flex items-center gap-3">
              <span className="w-8 h-8 rounded-full bg-tea-50 flex items-center justify-center text-sm">💰</span>
              Meu Extrato Financeiro
            </h3>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 mb-8">
              <div className="bg-tea-50 p-8 rounded-3xl border border-tea-100">
                <p className="text-xs font-bold text-tea-700 uppercase tracking-widest mb-4">Total Investido (Pago)</p>
                <p className="text-4xl font-serif font-bold text-tea-900">R$ {totalPaid.toFixed(2)}</p>
              </div>
              <div className="bg-orange-50 p-8 rounded-3xl border border-orange-100">
                <p className="text-xs font-bold text-orange-700 uppercase tracking-widest mb-4">Total Pendente (A Pagar)</p>
                <p className="text-4xl font-serif font-bold text-orange-900">R$ {totalPending.toFixed(2)}</p>
              </div>
            </div>

            <div className="overflow-hidden border border-gray-100 rounded-2xl">
              <div className="overflow-x-auto">
                <table className="w-full text-left text-sm">
                  <thead className="bg-gray-50 text-[10px] font-bold text-gray-400 uppercase tracking-widest">
                    <tr>
                      <th className="px-6 py-4">Data Pagto.</th>
                      <th className="px-6 py-4">Procedimento / Detalhes</th>
                      <th className="px-6 py-4 text-right">Valor</th>
                      <th className="px-6 py-4 text-center">Situação</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-50">
                    {myTransactions.map(t => (
                      <tr key={t.id} className="hover:bg-gray-50 transition-colors">
                        <td className="px-6 py-4 text-gray-500 font-medium">{new Date(t.date).toLocaleDateString()}</td>
                        <td className="px-6 py-4">
                          <p className="font-bold text-gray-800">{t.description}</p>
                          {t.serviceName && (
                            <p className="text-[9px] text-tea-600 font-bold uppercase tracking-tighter mt-0.5">
                              Sessão de {t.serviceName} em {t.procedureDate}
                            </p>
                          )}
                        </td>
                        <td className="px-6 py-4 text-right font-bold text-tea-900">R$ {t.amount.toFixed(2)}</td>
                        <td className="px-6 py-4 text-center">
                          <span className={`px-3 py-1 rounded-full text-[9px] font-bold uppercase tracking-widest ${t.status === 'paid' ? 'bg-green-100 text-green-700' : 'bg-orange-100 text-orange-700'}`}>
                            {t.status === 'paid' ? 'Pago' : 'Pendente'}
                          </span>
                        </td>
                      </tr>
                    ))}
                    {myTransactions.length === 0 && (
                      <tr><td colSpan={4} className="px-6 py-12 text-center text-gray-400 italic">Nenhum lançamento financeiro registrado.</td></tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </section>

          <section>
            <h3 className="text-xl font-bold text-tea-900 mb-6 flex items-center gap-3">
              <span className="w-8 h-8 rounded-full bg-tea-50 flex items-center justify-center text-sm">📅</span>
              Meus Agendamentos
            </h3>
            <div className="space-y-4">
              {myBookings.sort((a,b) => new Date(b.dateTime).getTime() - new Date(a.dateTime).getTime()).map(b => (
                 <div key={b.id} className="p-6 border border-gray-100 rounded-[1.5rem] flex justify-between items-center bg-white shadow-sm">
                    <div>
                      <p className="font-bold text-tea-900 text-lg">{b.serviceName}</p>
                      <p className="text-xs text-gray-400">Data: {new Date(b.dateTime.replace(' ', 'T')).toLocaleDateString()} às {b.dateTime.split(' ')[1]}</p>
                    </div>
                    <span className={`px-4 py-1.5 rounded-full text-[10px] font-bold uppercase tracking-wider ${
                      b.status === 'completed' ? 'bg-green-50 text-green-600' : 
                      b.status === 'pending' ? 'bg-orange-50 text-orange-600' :
                      b.status === 'cancelled' ? 'bg-red-50 text-red-600' :
                      'bg-blue-50 text-blue-600'
                    }`}>
                      {b.status === 'completed' ? 'Finalizado' : 
                       b.status === 'pending' ? 'Pendente' :
                       b.status === 'cancelled' ? 'Cancelado' :
                       'Confirmado'}
                    </span>
                 </div>
              ))}
              {myBookings.length === 0 && (
                <div className="text-center py-12 bg-gray-50 rounded-[2rem] border-2 border-dashed border-gray-100">
                  <p className="text-gray-400 text-sm italic">Você ainda não realizou agendamentos.</p>
                </div>
