import React, { useState } from 'react';
import { Booking, Service, TeamMember, SalonSettings, Customer } from '../types';
import { db } from '../firebase.ts';
import { collection, addDoc, deleteDoc, doc, updateDoc, query, where, getDocs } from "firebase/firestore";

interface AdminCalendarProps {
  bookings: Booking[];
  services: Service[];
  customers: Customer[];
  teamMembers: TeamMember[];
  settings?: SalonSettings;
}

const AdminCalendar: React.FC<AdminCalendarProps> = ({ bookings, services, customers, teamMembers, settings }) => {
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedProId, setSelectedProId] = useState(teamMembers[0]?.id || '');
  const [modal, setModal] = useState<{ open: boolean; hour: string; type: 'free' | 'occupied' | 'opened' }>({ open: false, hour: '', type: 'free' });
  const [customerSearch, setCustomerSearch] = useState('');
  const [selectedCustomerId, setSelectedCustomerId] = useState('');
  const [selectedServiceId, setSelectedServiceId] = useState('');

  const startHourNum = parseInt((settings?.businessHours?.start || "08:00").split(':')[0]);
  const endHourNum = parseInt((settings?.businessHours?.end || "19:00").split(':')[0]);

  const timeSlots = Array.from({ length: (endHourNum - startHourNum) * 2 }, (_, i) => {
    const totalMinutes = startHourNum * 60 + i * 30;
    const h = Math.floor(totalMinutes / 60);
    const m = totalMinutes % 60;
    return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
  });

  const getSlotData = (hour: string) => {
    const fullDateTime = `${selectedDate} ${hour}`;
    const booking = bookings.find(b => b.dateTime === fullDateTime && b.teamMemberId === selectedProId && b.status !== 'cancelled');
    if (!booking) return { type: 'locked' };
    return { type: booking.status, booking };
  };

  const handleOpenSlot = async (hour: string) => {
    if ((db as any)._isMock) return alert("Modo visual: Horário liberado simulado.");
    await addDoc(collection(db, "bookings"), {
      dateTime: `${selectedDate} ${hour}`,
      status: 'open',
      teamMemberId: selectedProId,
      teamMemberName: teamMembers.find(m => m.id === selectedProId)?.name,
      customerName: 'LIBERADO PARA CLIENTES',
      customerId: 'none'
    });
    setModal({ open: false, hour: '', type: 'free' });
  };

  const handleCloseSlot = async (bookingId: string) => {
    if ((db as any)._isMock) return;
    await updateDoc(doc(db, "bookings", bookingId), { status: 'cancelled' });
    setModal({ open: false, hour: '', type: 'free' });
  };

  const handleManualBooking = async () => {
    const customer = customers.find(c => c.id === selectedCustomerId);
    const service = services.find(s => s.id === selectedServiceId);
    if (!customer || !service) return alert("Selecione cliente e serviço.");

    await addDoc(collection(db, "bookings"), {
      customerId: customer.id,
      customerName: customer.name,
      serviceId: service.id,
      serviceName: service.name,
      teamMemberId: selectedProId,
      teamMemberName: teamMembers.find(m => m.id === selectedProId)?.name,
      dateTime: `${selectedDate} ${modal.hour}`,
      duration: service.duration,
      status: 'scheduled',
      depositStatus: 'paid',
      agreedToCancellationPolicy: true,
      policyAgreedAt: new Date().toISOString()
    });
    setModal({ open: false, hour: '', type: 'free' });
    setCustomerSearch(''); setSelectedCustomerId(''); setSelectedServiceId('');
  };

  return (
    <div className="space-y-8 animate-fade-in pb-20">
      <div className="bg-white p-8 rounded-[3rem] border border-gray-100 shadow-sm flex flex-col md:flex-row gap-6 items-end">
        <div className="flex-1 space-y-2">
          <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Dia da Agenda</label>
          <input type="date" value={selectedDate} onChange={e => setSelectedDate(e.target.value)} className="w-full p-4 bg-gray-50 border-none rounded-2xl font-bold" />
        </div>
        <div className="flex-1 space-y-2">
          <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Profissional</label>
          <select value={selectedProId} onChange={e => setSelectedProId(e.target.value)} className="w-full p-4 bg-gray-50 border-none rounded-2xl font-bold">
            {teamMembers.map(m => <option key={m.id} value={m.id}>{m.name}</option>)}
          </select>
        </div>
      </div>

      <div className="bg-white rounded-[3.5rem] shadow-sm border border-gray-100 overflow-hidden p-8">
        <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-6 gap-4">
          {timeSlots.map(hour => {
            const data = getSlotData(hour);
            let style = "bg-gray-50 text-gray-300 border-transparent cursor-not-allowed";
            let label = "Bloqueado";

            if (data.type === 'open') {
              style = "bg-white border-tea-500 text-tea-900 border-2 cursor-pointer";
              label = "Aberto p/ Clientes";
            } else if (data.type === 'scheduled' || data.type === 'completed') {
              style = "bg-tea-900 text-white border-tea-900 cursor-pointer shadow-lg";
              label = data.booking?.customerName.split(' ')[0] || "Ocupado";
            }

            return (
              <button 
                key={hour} 
                onClick={() => setModal({ open: true, hour, type: data.type === 'locked' ? 'free' : (data.type === 'open' ? 'opened' : 'occupied') })}
                className={`p-6 rounded-3xl transition-all flex flex-col items-center justify-center min-h-[100px] ${style} hover:scale-105`}
              >
                <span className="text-xl font-serif font-bold italic">{hour}</span>
                <span className="text-[8px] font-bold uppercase tracking-widest mt-1">{label}</span>
              </button>
            );
          })}
        </div>
      </div>

      {modal.open && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-fade-in">
          <div className="bg-white w-full max-w-md rounded-[3rem] p-10 shadow-3xl space-y-6">
            <h3 className="text-2xl font-serif text-tea-950 font-bold italic text-center">Horário: {modal.hour}</h3>

            {modal.type === 'free' && (
              <div className="space-y-4">
                <button onClick={() => handleOpenSlot(modal.hour)} className="w-full py-5 bg-tea-100 text-tea-900 rounded-2xl font-bold uppercase text-[10px] tracking-widest hover:bg-tea-200 transition-all">Liberar para Clientes (Site)</button>
                <div className="p-6 bg-gray-50 rounded-3xl space-y-4">
                  <p className="text-[9px] font-bold text-gray-400 uppercase tracking-widest text-center">Ou Agendar Manualmente</p>
                  <input type="text" placeholder="Buscar cliente..." value={customerSearch} onChange={e => setCustomerSearch(e.target.value)} className="w-full p-3 bg-white border border-gray-100 rounded-xl text-xs outline-none" />
                  <div className="max-h-24 overflow-y-auto space-y-1">
                    {customers.filter(c => c.name.toLowerCase().includes(customerSearch.toLowerCase())).slice(0, 3).map(c => (
                      <button key={c.id} onClick={() => { setSelectedCustomerId(c.id); setCustomerSearch(c.name); }} className={`w-full p-2 text-left text-[10px] rounded-lg ${selectedCustomerId === c.id ? 'bg-tea-900 text-white' : 'bg-white'}`}>{c.name}</button>
                    ))}
                  </div>
                  <select value={selectedServiceId} onChange={e => setSelectedServiceId(e.target.value)} className="w-full p-3 bg-white border border-gray-100 rounded-xl text-xs outline-none">
                    <option value="">Selecione o serviço...</option>
                    {services.map(s => <option key={s.id} value={s.id}>{s.name} - R$ {s.price}</option>)}
                  </select>
                  <button onClick={handleManualBooking} className="w-full py-4 bg-tea-900 text-white rounded-xl font-bold uppercase text-[10px]">Agendar Agora</button>
                </div>
              </div>
            )}

            {modal.type === 'opened' && (
              <button onClick={() => handleCloseSlot(getSlotData(modal.hour).booking!.id)} className="w-full py-5 bg-red-50 text-red-600 rounded-2xl font-bold uppercase text-[10px] tracking-widest border border-red-100">Bloquear / Fechar Horário</button>
            )}

            {modal.type === 'occupied' && (
               <div className="text-center space-y-4">
                  <p className="font-bold text-tea-950">{getSlotData(modal.hour).booking?.customerName}</p>
                  <p className="text-xs text-gray-400">{getSlotData(modal.hour).booking?.serviceName}</p>
                  <button onClick={() => handleCloseSlot(getSlotData(modal.hour).booking!.id)} className="w-full py-4 bg-red-50 text-red-600 rounded-xl text-[10px] font-bold">Cancelar Agendamento</button>
               </div>
            )}

            <button onClick={() => setModal({ open: false, hour: '', type: 'free' })} className="w-full py-2 text-gray-300 font-bold uppercase text-[9px]">Fechar</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminCalendar;

import React, { useState, useMemo } from 'react';
import { Transaction, Customer, Booking } from '../types';
import { db } from '../firebase.ts';
import { collection, addDoc, doc, updateDoc } from "firebase/firestore";

interface AdminFinanceProps {
  transactions: Transaction[];
  bookings: Booking[];
  customers: Customer[];
  onAdd?: (data: any) => Promise<void>;
}

const AdminFinance: React.FC<AdminFinanceProps> = ({ transactions, bookings, customers }) => {
  const [showAddForm, setShowAddForm] = useState(false);
  const [newTrans, setNewTrans] = useState({
    type: 'receivable' as 'payable' | 'receivable',
    description: '',
    amount: 0,
    date: new Date().toISOString().split('T')[0],
    customerId: '',
    bookingId: '',
    status: 'paid' as 'paid' | 'pending'
  });

  const [customerSearch, setCustomerSearch] = useState('');

  const handleSave = async () => {
    if (!newTrans.description || newTrans.amount <= 0) return alert("Dados insuficientes.");

    const customer = customers.find(c => c.id === newTrans.customerId);
    const booking = bookings.find(b => b.id === newTrans.bookingId);

    const transData = {
      ...newTrans,
      customerName: customer?.name || '',
      serviceName: booking?.serviceName || '',
      procedureDate: booking?.dateTime || '',
      paidAt: newTrans.status === 'paid' ? new Date().toISOString() : null
    };

    if (!(db as any)._isMock) {
      await addDoc(collection(db, "transactions"), transData);
      // Se for pagamento de um serviço, atualizamos o agendamento
      if (newTrans.bookingId && newTrans.status === 'paid') {
        await updateDoc(doc(db, "bookings", newTrans.bookingId), { 
          paymentReceived: newTrans.amount,
          paymentDate: new Date().toISOString(),
          status: 'completed' 
        });
      }
    }

    setShowAddForm(false);
    setNewTrans({ type: 'receivable', description: '', amount: 0, date: new Date().toISOString().split('T')[0], customerId: '', bookingId: '', status: 'paid' });
  };

  const totals = useMemo(() => {
    const revenue = transactions.filter(t => t.type === 'receivable' && t.status === 'paid').reduce((a, b) => a + b.amount, 0);
    const expenses = transactions.filter(t => t.type === 'payable' && t.status === 'paid').reduce((a, b) => a + b.amount, 0);
    return { revenue, expenses, balance: revenue - expenses };
  }, [transactions]);

  return (
    <div className="space-y-8 animate-fade-in pb-20">
      <div className="flex justify-between items-center bg-white p-8 rounded-[3rem] border border-gray-100 shadow-sm">
        <div>
          <h2 className="text-2xl font-bold text-tea-950 font-serif italic">Fluxo Moriá</h2>
          <p className="text-gray-400 text-xs">Gestão detalhada de ganhos e despesas.</p>
        </div>
        <button onClick={() => setShowAddForm(true)} className="bg-tea-900 text-white px-8 py-4 rounded-2xl font-bold uppercase text-[10px] tracking-widest hover:bg-black shadow-lg">+ Novo Lançamento</button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-green-50 p-8 rounded-[2.5rem] border border-green-100">
          <p className="text-[9px] font-bold text-green-700 uppercase tracking-widest mb-1">Total Ganhos</p>
          <p className="text-3xl font-bold text-green-900">R$ {totals.revenue.toLocaleString('pt-BR')}</p>
        </div>
        <div className="bg-red-50 p-8 rounded-[2.5rem] border border-red-100">
          <p className="text-[9px] font-bold text-red-700 uppercase tracking-widest mb-1">Total Despesas</p>
          <p className="text-3xl font-bold text-red-900">R$ {totals.expenses.toLocaleString('pt-BR')}</p>
        </div>
        <div className="bg-tea-950 p-8 rounded-[2.5rem] text-white shadow-xl">
          <p className="text-[9px] font-bold text-tea-300 uppercase tracking-widest mb-1">Saldo em Caixa</p>
          <p className="text-3xl font-bold">R$ {totals.balance.toLocaleString('pt-BR')}</p>
        </div>
      </div>

      <div className="bg-white rounded-[3rem] border border-gray-100 overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-gray-50 border-b border-gray-100">
            <tr>
              <th className="px-8 py-5 text-[9px] font-bold text-gray-400 uppercase tracking-widest">Data</th>
              <th className="px-8 py-5 text-[9px] font-bold text-gray-400 uppercase tracking-widest">Descrição / Cliente</th>
              <th className="px-8 py-5 text-[9px] font-bold text-gray-400 uppercase tracking-widest">Procedimento</th>
              <th className="px-8 py-5 text-[9px] font-bold text-gray-400 uppercase tracking-widest text-right">Valor</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-50">
            {transactions.sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()).map(t => (
              <tr key={t.id} className="hover:bg-tea-50/20">
                <td className="px-8 py-6 text-xs font-bold text-gray-500">{new Date(t.date).toLocaleDateString()}</td>
                <td className="px-8 py-6">
                  <p className="font-bold text-tea-950">{t.description}</p>
                  {t.customerName && <p className="text-[9px] text-tea-600 font-bold uppercase">{t.customerName}</p>}
                </td>
                <td className="px-8 py-6">
                  <p className="text-xs text-gray-500 italic">{t.serviceName || 'Lançamento Geral'}</p>
                </td>
                <td className={`px-8 py-6 text-right font-bold ${t.type === 'receivable' ? 'text-tea-800' : 'text-red-500'}`}>
                  {t.type === 'receivable' ? '+' : '-'} R$ {t.amount.toFixed(2)}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {showAddForm && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fade-in">
          <div className="bg-white w-full max-w-xl rounded-[3.5rem] p-12 shadow-3xl space-y-8 max-h-[90vh] overflow-y-auto custom-scroll">
            <h3 className="text-3xl font-serif text-tea-950 font-bold italic text-center">Lançamento de Caixa</h3>

            <div className="space-y-6">
               <div className="flex bg-gray-100 p-1 rounded-2xl">
                  <button onClick={() => setNewTrans({...newTrans, type: 'receivable'})} className={`flex-1 py-4 rounded-xl text-[10px] font-bold uppercase tracking-widest ${newTrans.type === 'receivable' ? 'bg-white text-tea-900 shadow-sm' : 'text-gray-400'}`}>Ganhos (Entrada)</button>
                  <button onClick={() => setNewTrans({...newTrans, type: 'payable'})} className={`flex-1 py-4 rounded-xl text-[10px] font-bold uppercase tracking-widest ${newTrans.type === 'payable' ? 'bg-white text-red-600 shadow-sm' : 'text-gray-400'}`}>Despesas (Saída)</button>
               </div>

               <div className="space-y-2">
                  <label className="text-[9px] font-bold text-gray-400 uppercase ml-2">Descrição</label>
                  <input type="text" value={newTrans.description} onChange={e => setNewTrans({...newTrans, description: e.target.value})} className="w-full p-4 bg-gray-50 rounded-2xl outline-none font-bold" placeholder="Ex: Pagamento Unha em Gel" />
               </div>

               <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <label className="text-[9px] font-bold text-gray-400 uppercase ml-2">Valor R$</label>
                    <input type="number" value={newTrans.amount} onChange={e => setNewTrans({...newTrans, amount: parseFloat(e.target.value)})} className="w-full p-4 bg-gray-50 rounded-2xl outline-none font-bold" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[9px] font-bold text-gray-400 uppercase ml-2">Data</label>
                    <input type="date" value={newTrans.date} onChange={e => setNewTrans({...newTrans, date: e.target.value})} className="w-full p-4 bg-gray-50 rounded-2xl outline-none font-bold" />
                  </div>
               </div>

               {newTrans.type === 'receivable' && (
                 <div className="p-6 bg-tea-50/50 rounded-3xl border border-tea-100 space-y-4">
                    <p className="text-[9px] font-bold text-tea-900 uppercase tracking-widest text-center">Vincular a Cliente</p>
                    <input type="text" placeholder="Buscar cliente..." value={customerSearch} onChange={e => setCustomerSearch(e.target.value)} className="w-full p-3 bg-white border border-gray-100 rounded-xl text-xs outline-none" />
                    <div className="max-h-32 overflow-y-auto space-y-1">
                      {customers.filter(c => c.name.toLowerCase().includes(customerSearch.toLowerCase())).slice(0, 4).map(c => (
                        <button key={c.id} onClick={() => { setNewTrans({...newTrans, customerId: c.id}); setCustomerSearch(c.name); }} className={`w-full p-3 text-left text-[11px] rounded-lg ${newTrans.customerId === c.id ? 'bg-tea-900 text-white font-bold' : 'bg-white'}`}>{c.name}</button>
                      ))}
                    </div>

                    {newTrans.customerId && (
                      <div className="space-y-2 animate-fade-in">
                        <label className="text-[9px] font-bold text-gray-400 uppercase ml-2">Vincular Agendamento</label>
                        <select value={newTrans.bookingId} onChange={e => setNewTrans({...newTrans, bookingId: e.target.value})} className="w-full p-3 bg-white border border-gray-100 rounded-xl text-[10px] outline-none">
                           <option value="">Lançamento Avulso</option>
                           {bookings.filter(b => b.customerId === newTrans.customerId && b.status !== 'cancelled').map(b => (
                             <option key={b.id} value={b.id}>{b.serviceName} - {b.dateTime}</option>
                           ))}
                        </select>
                      </div>
                    )}
                 </div>
               )}

               <button onClick={handleSave} className="w-full py-6 bg-tea-900 text-white rounded-2xl font-bold uppercase text-[11px] tracking-widest shadow-xl">Salvar no Caixa</button>
               <button onClick={() => setShowAddForm(false)} className="w-full py-2 text-gray-300 font-bold uppercase text-[9px]">Cancelar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminFinance;

import React, { useState } from 'react';
import { Booking, Customer, WaitlistEntry, Service } from '../types';
import { db } from '../firebase.ts';
import { collection, addDoc, deleteDoc, doc } from "firebase/firestore";

interface AdminConfirmationsProps {
  bookings: Booking[];
  customers: Customer[];
  waitlist: WaitlistEntry[];
  services: Service[];
  onUpdateStatus?: (id: string, status: any) => void;
  onUpdateDeposit?: (id: string, status: any) => void;
  onDeleteBooking?: (id: string) => void;
  onRemoveWaitlist?: (id: string) => void;
}

const AdminConfirmations: React.FC<AdminConfirmationsProps> = ({ bookings, customers, waitlist, services }) => {
  const [activeTab, setActiveTab] = useState<'pending' | 'waitlist'>('pending');
  const [showWaitlistForm, setShowWaitlistForm] = useState(false);
  const [manualEntry, setManualEntry] = useState({ name: '', whatsapp: '', serviceId: '', date: '' });

  const handleAddManualWaitlist = async () => {
    if (!manualEntry.name || !manualEntry.whatsapp || !manualEntry.serviceId) return alert("Preencha todos os campos.");

    const service = services.find(s => s.id === manualEntry.serviceId);

    await addDoc(collection(db, "waitlist"), {
      customerName: manualEntry.name,
      customerWhatsapp: manualEntry.whatsapp,
      serviceId: manualEntry.serviceId,
      serviceName: service?.name || '',
      preferredDate: manualEntry.date,
      status: 'active',
      createdAt: new Date().toISOString(),
      customerId: 'manual'
    });

    setShowWaitlistForm(false);
    setManualEntry({ name: '', whatsapp: '', serviceId: '', date: '' });
  };

  return (
    <div className="space-y-8 animate-fade-in pb-20">
      <div className="flex gap-4 border-b border-gray-100 pb-4">
        <button onClick={() => setActiveTab('pending')} className={`px-6 py-3 rounded-full text-[10px] font-bold uppercase tracking-widest transition-all ${activeTab === 'pending' ? 'bg-tea-900 text-white' : 'bg-gray-100 text-gray-400'}`}>Pedidos Site</button>
        <button onClick={() => setActiveTab('waitlist')} className={`px-6 py-3 rounded-full text-[10px] font-bold uppercase tracking-widest transition-all ${activeTab === 'waitlist' ? 'bg-tea-900 text-white' : 'bg-gray-100 text-gray-400'}`}>Lista de Espera</button>
      </div>

      {activeTab === 'pending' && (
        <div className="space-y-6">
          {bookings.filter(b => b.status === 'pending').map(b => (
            <div key={b.id} className="bg-white p-8 rounded-[3rem] border border-gray-100 shadow-sm flex flex-col md:flex-row justify-between items-center gap-6">
              <div className="flex items-center gap-6">
                <div className="w-16 h-16 bg-tea-50 text-tea-900 rounded-2xl flex items-center justify-center font-bold text-2xl">{b.customerName.charAt(0)}</div>
                <div>
                   <h3 className="text-xl font-bold text-tea-950">{b.customerName}</h3>
                   <p className="text-[10px] text-tea-600 font-bold uppercase tracking-widest">{b.serviceName} • {b.dateTime}</p>
                </div>
              </div>
              <div className="flex gap-4">
                 <button className="px-6 py-3 bg-tea-800 text-white rounded-xl font-bold uppercase text-[9px] tracking-widest">Aprovar</button>
                 <button className="px-6 py-3 bg-red-50 text-red-500 rounded-xl font-bold uppercase text-[9px] tracking-widest">Recusar</button>
              </div>
            </div>
          ))}
          {bookings.filter(b => b.status === 'pending').length === 0 && <p className="text-center py-20 opacity-30 italic">Nenhum pedido pendente.</p>}
        </div>
      )}

      {activeTab === 'waitlist' && (
        <div className="space-y-6">
          <div className="flex justify-between items-center px-4">
             <h3 className="text-xl font-serif font-bold text-tea-950 italic">Interesses de Encaixe</h3>
             <button onClick={() => setShowWaitlistForm(true)} className="bg-tea-900 text-white px-6 py-3 rounded-xl font-bold uppercase text-[9px] tracking-widest">+ Adicionar Nome</button>
          </div>

          <div className="grid grid-cols-1 gap-4">
            {waitlist.map(w => (
              <div key={w.id} className="bg-white p-8 rounded-[3rem] border border-orange-50 flex justify-between items-center shadow-sm">
                 <div>
                    <h4 className="font-bold text-tea-950">{w.customerName}</h4>
                    <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">{w.serviceName} • Deseja em: {w.preferredDate}</p>
                 </div>
                 <button className="text-[9px] font-bold text-tea-700 uppercase hover:underline">📱 Chamar WhatsApp</button>
              </div>
            ))}
          </div>

          {showWaitlistForm && (
            <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-fade-in">
              <div className="bg-white w-full max-w-md rounded-[3rem] p-10 shadow-3xl space-y-6">
                 <h3 className="text-2xl font-serif text-tea-950 font-bold italic text-center">Inclusão Manual na Espera</h3>
                 <div className="space-y-4">
                    <input placeholder="Nome da Cliente" value={manualEntry.name} onChange={e => setManualEntry({...manualEntry, name: e.target.value})} className="w-full p-4 bg-gray-50 rounded-2xl outline-none font-bold" />
                    <input placeholder="WhatsApp" value={manualEntry.whatsapp} onChange={e => setManualEntry({...manualEntry, whatsapp: e.target.value})} className="w-full p-4 bg-gray-50 rounded-2xl outline-none font-bold" />
                    <select value={manualEntry.serviceId} onChange={e => setManualEntry({...manualEntry, serviceId: e.target.value})} className="w-full p-4 bg-gray-50 rounded-2xl outline-none font-bold">
                       <option value="">Qual o procedimento?</option>
                       {services.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                    </select>
                    <input type="date" value={manualEntry.date} onChange={e => setManualEntry({...manualEntry, date: e.target.value})} className="w-full p-4 bg-gray-50 rounded-2xl outline-none font-bold" />
                    <button onClick={handleAddManualWaitlist} className="w-full py-5 bg-tea-900 text-white rounded-2xl font-bold uppercase text-[10px] tracking-widest shadow-xl">Salvar na Lista</button>
                    <button onClick={() => setShowWaitlistForm(false)} className="w-full py-2 text-gray-300 font-bold uppercase text-[9px]">Cancelar</button>
                 </div>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default AdminConfirmations;

