            <button onClick={() => setActiveTab('agenda')} className={`text-xl ${activeTab === 'agenda' ? 'text-tea-400 scale-110' : 'text-white/40'}`}>🗓️</button>
            <button onClick={onLogout} className="text-xl text-white/20">👋</button>
         </div>
      </nav>
    </div>
  );
};

