import React, { useState, useEffect } from 'react';
import { View, Customer, Service, Booking, Transaction, SalonSettings, WaitlistEntry, Promotion } from './types.ts';
import { INITIAL_SERVICES, DEFAULT_SETTINGS } from './constants.ts';
import { db } from './firebase.ts';
import { 
  collection, 
  onSnapshot, 
  doc, 
  setDoc, 
  addDoc, 
  updateDoc, 
  deleteDoc,
  increment
} from "firebase/firestore";

import Navbar from './components/Navbar.tsx';
import CustomerHome from './components/CustomerHome.tsx';
import CustomerRegister from './components/CustomerRegister.tsx';
import CustomerLoginView from './components/CustomerLoginView.tsx';
import CustomerProfile from './components/CustomerProfile.tsx';
import CustomerDashboard from './components/CustomerDashboard.tsx';
import AdminDashboard from './components/AdminDashboard.tsx';
import AdminCalendar from './components/AdminCalendar.tsx';
import AdminFinance from './components/AdminFinance.tsx';
import AdminClients from './components/AdminClients.tsx';
import AdminConfirmations from './components/AdminConfirmations.tsx';
import AdminSettingsView from './components/AdminSettingsView.tsx';
import AdminLogin from './components/AdminLogin.tsx';
import AdminMarketing from './components/AdminMarketing.tsx';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.CUSTOMER_HOME);
  const [isAdmin, setIsAdmin] = useState(false);
  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  const [settings, setSettings] = useState<SalonSettings>(DEFAULT_SETTINGS);
  const [services, setServices] = useState<Service[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [waitlist, setWaitlist] = useState<WaitlistEntry[]>([]);
  const [promotions, setPromotions] = useState<Promotion[]>([]);
  const [currentUser, setCurrentUser] = useState<Customer | null>(null);

  useEffect(() => {
    // FIX: Using (db as any) to check _isMock property which is not part of standard Firestore type
    if ((db as any)._isMock) {
      console.log("Modo Visual: Firestore Mock Ativo.");
      setIsLoading(false);
      return;
    }

    const unsubSettings = onSnapshot(doc(db, "settings", "main"), (snap) => {
      if (snap.exists()) {
        setSettings(snap.data() as SalonSettings);
        setIsLoading(false);
      } else {
        setDoc(doc(db, "settings", "main"), DEFAULT_SETTINGS).then(() => setIsLoading(false));
      }
    }, () => setIsLoading(false));

    const unsubServices = onSnapshot(collection(db, "services"), (snapshot) => {
      setServices(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Service)));
    });

    const unsubCustomers = onSnapshot(collection(db, "customers"), (snapshot) => {
      setCustomers(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Customer)));
    });

    const unsubBookings = onSnapshot(collection(db, "bookings"), (snapshot) => {
      setBookings(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Booking)));
    });

    const unsubTransactions = onSnapshot(collection(db, "transactions"), (snapshot) => {
      setTransactions(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Transaction)));
    });

    const unsubWaitlist = onSnapshot(collection(db, "waitlist"), (snapshot) => {
      setWaitlist(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as WaitlistEntry)));
    });

    const unsubPromotions = onSnapshot(collection(db, "promotions"), (snapshot) => {
      setPromotions(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Promotion)));
    });

    return () => {
      unsubSettings(); unsubServices(); unsubCustomers();
      unsubBookings(); unsubTransactions(); unsubWaitlist(); unsubPromotions();
    };
  }, []);

  const handleUpdateStatus = async (id: string, status: any) => {
    // FIX: Using (db as any) for _isMock check
    if ((db as any)._isMock) return;
    const updateData: any = { status };
    if (status === 'cancelled') updateData.cancelledAt = new Date().toISOString();
    await updateDoc(doc(db, "bookings", id), updateData);
  };

  const handleUpdateDeposit = async (id: string, depositStatus: 'paid' | 'pending') => {
    // FIX: Using (db as any) for _isMock check
    if ((db as any)._isMock) return;
    await updateDoc(doc(db, "bookings", id), { depositStatus });
  };

  const renderView = () => {
    if (isAdmin) {
      if (!isAdminAuthenticated) return <AdminLogin onLogin={() => { setIsAdminAuthenticated(true); setCurrentView(View.ADMIN_DASHBOARD); }} onBack={() => setIsAdmin(false)} />;
      switch (currentView) {
        case View.ADMIN_SETTINGS: return <AdminSettingsView settings={settings} services={services} customers={customers} bookings={bookings} transactions={transactions} />;
        case View.ADMIN_CALENDAR: return <AdminCalendar bookings={bookings} services={services} customers={customers} teamMembers={settings.teamMembers} settings={settings} onUpdateStatus={handleUpdateStatus} />;
        // FIX: Added missing 'services' prop to AdminConfirmations to resolve TS error
        case View.ADMIN_CONFIRMATIONS: return <AdminConfirmations bookings={bookings} customers={customers} services={services} onUpdateStatus={handleUpdateStatus} onUpdateDeposit={handleUpdateDeposit} onDeleteBooking={(id) => !(db as any)._isMock && updateDoc(doc(db, "bookings", id), {status: 'cancelled'})} waitlist={waitlist} onRemoveWaitlist={(id) => !(db as any)._isMock && deleteDoc(doc(db, "waitlist", id))} />;
        case View.ADMIN_CLIENTS: return <AdminClients customers={customers} bookings={bookings} transactions={transactions} onDelete={(id) => !(db as any)._isMock && deleteDoc(doc(db, "customers", id))} onUpdate={(id, data) => !(db as any)._isMock && updateDoc(doc(db, "customers", id), data)} />;
        case View.ADMIN_FINANCE: return <AdminFinance transactions={transactions} bookings={bookings} customers={customers} onAdd={async (d) => { if(!(db as any)._isMock) await addDoc(collection(db, "transactions"), d); }} onUpdate={(id, d) => !(db as any)._isMock && updateDoc(doc(db, "transactions", id), d)} onDelete={(id) => !(db as any)._isMock && deleteDoc(doc(db, "transactions", id))} />;
        case View.ADMIN_MARKETING: return <AdminMarketing customers={customers} promotions={promotions} services={services} bookings={bookings} />;
        default: return <AdminDashboard bookings={bookings} transactions={transactions} customers={customers} settings={settings} />;
      }
    }

    if (currentUser && currentView === View.CUSTOMER_DASHBOARD) {
       return (
         <CustomerDashboard 
            customer={currentUser} 
            bookings={bookings} 
            services={services}
            settings={settings}
            onBook={() => {}}
            // FIX: Using (db as any) for _isMock checks
            onUpdateProfile={(upd) => !(db as any)._isMock && updateDoc(doc(db, "customers", currentUser.id), upd)}
            onLogout={() => { setCurrentUser(null); setCurrentView(View.CUSTOMER_HOME); }}
            onCancelBooking={(id) => !(db as any)._isMock && updateDoc(doc(db, "bookings", id), {status: 'cancelled'})}
            onAddToWaitlist={() => {}}
            waitlist={waitlist.filter(w => w.customerId === currentUser.id && w.status !== 'cancelled')}
            onRemoveWaitlist={(id) => !(db as any)._isMock && deleteDoc(doc(db, "waitlist", id))}
            promotions={promotions}
         />
       );
    }

    switch (currentView) {
      case View.CUSTOMER_REGISTER: return (
        <CustomerRegister 
          onRegister={async (n, w, c, p, not) => {
            // FIX: Using (db as any) for _isMock checks
            if((db as any)._isMock) return;
            const id = Math.random().toString(36).substr(2, 9);
            const user = { id, name: n, whatsapp: w, cpf: c, password: p, receivesNotifications: not, agreedToTerms: true, history: [] };
            await setDoc(doc(db, "customers", id), user);
            setCurrentUser(user);
            setCurrentView(View.CUSTOMER_DASHBOARD);
          }} 
          customers={customers} 
          onBack={() => setCurrentView(View.CUSTOMER_HOME)} 
        />
      );
      case View.CUSTOMER_LOGIN: return (
        <CustomerLoginView 
          onLogin={(cpf, pass) => {
            const user = customers.find(c => c.cpf === cpf && c.password === pass);
            if (user) { setCurrentUser(user); setCurrentView(View.CUSTOMER_DASHBOARD); }
            else alert("Acesso inválido.");
          }} 
          onRegisterClick={() => setCurrentView(View.CUSTOMER_REGISTER)} 
          onBack={() => setCurrentView(View.CUSTOMER_HOME)} 
        />
      );
      default: return (
        <CustomerHome 
          settings={settings} services={services} bookings={bookings} 
          onBook={() => {}} 
          onAuthClick={() => setCurrentView(View.CUSTOMER_LOGIN)} 
          onAddToWaitlist={() => {}} 
          currentUser={currentUser} 
        />
      );
    }
  };

  return (
    <div className="min-h-screen bg-white">
      {currentView !== View.CUSTOMER_DASHBOARD && (
        <Navbar 
          view={currentView} setView={setCurrentView} isAdmin={isAdmin} 
          onToggleAdmin={() => { setIsAdmin(!isAdmin); if(!isAdminAuthenticated) setCurrentView(View.ADMIN_LOGIN); else setCurrentView(isAdmin ? View.CUSTOMER_HOME : View.ADMIN_DASHBOARD); }} 
          salonName={settings.name} logo={settings.logo} currentUser={currentUser} 
          onLogout={() => { setCurrentUser(null); setCurrentView(View.CUSTOMER_HOME); }} 
          onAdminLogout={() => { setIsAdminAuthenticated(false); setIsAdmin(false); setCurrentView(View.CUSTOMER_HOME); }} 
          isAdminAuthenticated={isAdminAuthenticated} pendingBookingsCount={bookings.filter(b => b.status === 'pending').length} 
        />
      )}
      <main className={currentView === View.CUSTOMER_DASHBOARD ? "" : "max-w-7xl mx-auto px-4 py-8"}>
        {isLoading ? (
          <div className="flex flex-col items-center justify-center py-40 gap-4">
            <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-tea-600"></div>
            <p className="text-tea-800 font-serif italic">Studio Moriá Estética...</p>
          </div>
        ) : renderView()}
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Booking, Service, TeamMember, SalonSettings, Customer } from '../types';
import { db } from '../firebase.ts';
import { collection, addDoc, deleteDoc, doc, updateDoc, query, where, getDocs } from "firebase/firestore";

interface AdminCalendarProps {
  bookings: Booking[];
  services: Service[];
  customers: Customer[];
  teamMembers: TeamMember[];
  settings?: SalonSettings;
  // Added onUpdateStatus to match passing in App.tsx
  onUpdateStatus?: (id: string, status: any) => void;
}

const AdminCalendar: React.FC<AdminCalendarProps> = ({ bookings, services, customers, teamMembers, settings }) => {
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedProId, setSelectedProId] = useState(teamMembers[0]?.id || '');
  const [modal, setModal] = useState<{ open: boolean; hour: string; type: 'free' | 'occupied' | 'opened' }>({ open: false, hour: '', type: 'free' });
  const [customerSearch, setCustomerSearch] = useState('');
  const [selectedCustomerId, setSelectedCustomerId] = useState('');
  const [selectedServiceId, setSelectedServiceId] = useState('');

  const startHourNum = parseInt((settings?.businessHours?.start || "08:00").split(':')[0]);
  const endHourNum = parseInt((settings?.businessHours?.end || "19:00").split(':')[0]);

  const timeSlots = Array.from({ length: (endHourNum - startHourNum) * 2 }, (_, i) => {
    const totalMinutes = startHourNum * 60 + i * 30;
    const h = Math.floor(totalMinutes / 60);
    const m = totalMinutes % 60;
    return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
  });

  const getSlotData = (hour: string) => {
    const fullDateTime = `${selectedDate} ${hour}`;
    const booking = bookings.find(b => b.dateTime === fullDateTime && b.teamMemberId === selectedProId && b.status !== 'cancelled');
    if (!booking) return { type: 'locked' };
    return { type: booking.status, booking };
  };

  const handleOpenSlot = async (hour: string) => {
    if ((db as any)._isMock) return alert("Modo visual: Horário liberado simulado.");
    await addDoc(collection(db, "bookings"), {
      dateTime: `${selectedDate} ${hour}`,
      status: 'open',
      teamMemberId: selectedProId,
      teamMemberName: teamMembers.find(m => m.id === selectedProId)?.name,
      customerName: 'LIBERADO PARA CLIENTES',
      customerId: 'none'
    });
    setModal({ open: false, hour: '', type: 'free' });
  };

  const handleCloseSlot = async (bookingId: string) => {
    if ((db as any)._isMock) return;
    await updateDoc(doc(db, "bookings", bookingId), { status: 'cancelled' });
    setModal({ open: false, hour: '', type: 'free' });
  };

  const handleManualBooking = async () => {
    const customer = customers.find(c => c.id === selectedCustomerId);
    const service = services.find(s => s.id === selectedServiceId);
    if (!customer || !service) return alert("Selecione cliente e serviço.");

    await addDoc(collection(db, "bookings"), {
      customerId: customer.id,
      customerName: customer.name,
      serviceId: service.id,
      serviceName: service.name,
      teamMemberId: selectedProId,
      teamMemberName: teamMembers.find(m => m.id === selectedProId)?.name,
      dateTime: `${selectedDate} ${modal.hour}`,
      duration: service.duration,
      status: 'scheduled',
      depositStatus: 'paid',
      agreedToCancellationPolicy: true,
      policyAgreedAt: new Date().toISOString()
    });
    setModal({ open: false, hour: '', type: 'free' });
    setCustomerSearch(''); setSelectedCustomerId(''); setSelectedServiceId('');
  };

  return (
    <div className="space-y-8 animate-fade-in pb-20">
      <div className="bg-white p-8 rounded-[3rem] border border-gray-100 shadow-sm flex flex-col md:flex-row gap-6 items-end">
        <div className="flex-1 space-y-2">
          <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Dia da Agenda</label>
          <input type="date" value={selectedDate} onChange={e => setSelectedDate(e.target.value)} className="w-full p-4 bg-gray-50 border-none rounded-2xl font-bold" />
        </div>
        <div className="flex-1 space-y-2">
          <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Profissional</label>
          <select value={selectedProId} onChange={e => setSelectedProId(e.target.value)} className="w-full p-4 bg-gray-50 border-none rounded-2xl font-bold">
            {teamMembers.map(m => <option key={m.id} value={m.id}>{m.name}</option>)}
          </select>
        </div>
      </div>

      <div className="bg-white rounded-[3.5rem] shadow-sm border border-gray-100 overflow-hidden p-8">
        <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-6 gap-4">
          {timeSlots.map(hour => {
            const data = getSlotData(hour);
            let style = "bg-gray-50 text-gray-300 border-transparent cursor-not-allowed";
            let label = "Bloqueado";

            if (data.type === 'open') {
              style = "bg-white border-tea-500 text-tea-900 border-2 cursor-pointer";
              label = "Aberto p/ Clientes";
            } else if (data.type === 'scheduled' || data.type === 'completed') {
              style = "bg-tea-900 text-white border-tea-900 cursor-pointer shadow-lg";
              label = data.booking?.customerName.split(' ')[0] || "Ocupado";
            }

            return (
              <button 
                key={hour} 
                onClick={() => setModal({ open: true, hour, type: data.type === 'locked' ? 'free' : (data.type === 'open' ? 'opened' : 'occupied') })}
                className={`p-6 rounded-3xl transition-all flex flex-col items-center justify-center min-h-[100px] ${style} hover:scale-105`}
              >
                <span className="text-xl font-serif font-bold italic">{hour}</span>
                <span className="text-[8px] font-bold uppercase tracking-widest mt-1">{label}</span>
              </button>
            );
          })}
        </div>
      </div>

      {modal.open && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-fade-in">
          <div className="bg-white w-full max-w-md rounded-[3rem] p-10 shadow-3xl space-y-6">
            <h3 className="text-2xl font-serif text-tea-950 font-bold italic text-center">Horário: {modal.hour}</h3>

            {modal.type === 'free' && (
              <div className="space-y-4">
                <button onClick={() => handleOpenSlot(modal.hour)} className="w-full py-5 bg-tea-100 text-tea-900 rounded-2xl font-bold uppercase text-[10px] tracking-widest hover:bg-tea-200 transition-all">Liberar para Clientes (Site)</button>
                <div className="p-6 bg-gray-50 rounded-3xl space-y-4">
                  <p className="text-[9px] font-bold text-gray-400 uppercase tracking-widest text-center">Ou Agendar Manualmente</p>
                  <input type="text" placeholder="Buscar cliente..." value={customerSearch} onChange={e => setCustomerSearch(e.target.value)} className="w-full p-3 bg-white border border-gray-100 rounded-xl text-xs outline-none" />
                  <div className="max-h-24 overflow-y-auto space-y-1">
                    {customers.filter(c => c.name.toLowerCase().includes(customerSearch.toLowerCase())).slice(0, 3).map(c => (
                      <button key={c.id} onClick={() => { setSelectedCustomerId(c.id); setCustomerSearch(c.name); }} className={`w-full p-2 text-left text-[10px] rounded-lg ${selectedCustomerId === c.id ? 'bg-tea-900 text-white' : 'bg-white'}`}>{c.name}</button>
                    ))}
                  </div>
                  <select value={selectedServiceId} onChange={e => setSelectedServiceId(e.target.value)} className="w-full p-3 bg-white border border-gray-100 rounded-xl text-xs outline-none">
                    <option value="">Selecione o serviço...</option>
                    {services.map(s => <option key={s.id} value={s.id}>{s.name} - R$ {s.price}</option>)}
                  </select>
                  <button onClick={handleManualBooking} className="w-full py-4 bg-tea-900 text-white rounded-xl font-bold uppercase text-[10px]">Agendar Agora</button>
                </div>
              </div>
            )}

            {modal.type === 'opened' && (
              <button onClick={() => handleCloseSlot(getSlotData(modal.hour).booking!.id)} className="w-full py-5 bg-red-50 text-red-600 rounded-2xl font-bold uppercase text-[10px] tracking-widest border border-red-100">Bloquear / Fechar Horário</button>
            )}

            {modal.type === 'occupied' && (
               <div className="text-center space-y-4">
                  <p className="font-bold text-tea-950">{getSlotData(modal.hour).booking?.customerName}</p>
                  <p className="text-xs text-gray-400">{getSlotData(modal.hour).booking?.serviceName}</p>
                  <button onClick={() => handleCloseSlot(getSlotData(modal.hour).booking!.id)} className="w-full py-4 bg-red-50 text-red-600 rounded-xl text-[10px] font-bold">Cancelar Agendamento</button>
               </div>
            )}

            <button onClick={() => setModal({ open: false, hour: '', type: 'free' })} className="w-full py-2 text-gray-300 font-bold uppercase text-[9px]">Fechar</button>
          </div>
        </div>
      )}
    </div>
  );
};

